INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木马", "is_correct": true, "explanation": "木马是可以骑的玩具，句中“排队等着骑”指向它。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件是纸质材料，不能骑。"}, {"text": "电线", "is_correct": false, "explanation": "搭配：“骑”的对象是可以骑的物件，不说“骑电线”。"}, {"text": "石板", "is_correct": false, "explanation": "语义：石板是铺地或建筑的材料，不是可以骑的东西。"}], "explanations": {"木马": "木马是可以骑的玩具，句中“排队等着骑”指向它。", "文件": "语义：文件是纸质材料，不能骑。", "电线": "搭配：“骑”的对象是可以骑的物件，不说“骑电线”。", "石板": "语义：石板是铺地或建筑的材料，不是可以骑的东西。"}, "sentence_index": 6, "correct_answer": "木马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室的墙上挂着一张木马。", "explanation": "这里应该用〈个〉。“张”用于平面物品，木马是立体的玩具，应说“一个木马”。"}, {"text": "他的手里拿着一根木马。", "explanation": "这里应该用〈个〉。“根”用于细长物，木马不能用“根”，应说“一个木马”。"}, {"text": "院子里放着一台木马。", "explanation": "这里应该用〈个〉。“台”用于机器，木马是玩具，不能用“台”，应说“一个木马”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐送给我一辆木马。", "corrected_sentence": "姐姐送给我一个木马。", "error_description": "量词错误：“木马”是玩具，应配量词“个”，不用“辆”（“辆”用于车辆）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼儿园的院子里放着两个木马们。", "corrected_sentence": "幼儿园的院子里放着两个木马。", "error_description": "“们”错误：“们”只用于指人的名词之后，“木马”是事物，不能加“们”表示复数；应直接说“两个木马”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
