INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种动物，人们可以骑它。", "primary_collocate": null, "pronunciation": "mǎ", "ipa": "ma˨˩˦", "syllable_count": 1, "sentences": [{"text": "草地上有一匹白马。", "target_word": "马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "马在河边喝水。", "target_word": "马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这匹马跑得真快。", "target_word": "马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近有一个养马的农场。", "target_word": "马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的人常常用马拉车。", "target_word": "马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的马又高又大。", "target_word": "马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩给马喂了一些草。", "target_word": "马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马的腿又细又长。", "target_word": "马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就很喜欢马。", "target_word": "马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那匹黑马是我爷爷的。", "target_word": "马", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "匹", "label": "量词"}, {"form": "馬", "label": "繁体"}, {"form": "马匹", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以骑的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39826, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "马", "is_correct": true, "explanation": "正确答案。马 mǎ，一种可以骑的动物。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 mǎ（第三声）声调不同，意思是妈妈。"}, {"text": "骂", "is_correct": false, "explanation": "mà（第四声）与 mǎ（第三声）声调不同，意思是责骂。"}, {"text": "吗", "is_correct": false, "explanation": "ma（轻声）与 mǎ（第三声）声调不同，是语气词。"}], "explanations": {"马": "正确答案。马 mǎ，一种可以骑的动物。", "妈": "mā（第一声）与 mǎ（第三声）声调不同，意思是妈妈。", "骂": "mà（第四声）与 mǎ（第三声）声调不同，意思是责骂。", "吗": "ma（轻声）与 mǎ（第三声）声调不同，是语气词。"}, "sentence_index": null, "correct_answer": "马"}, "level_3": {"options": [{"text": "马", "is_correct": true, "explanation": "正确答案。“一匹白马”指白色的马。"}, {"text": "牛", "is_correct": false, "explanation": "量词：牛用“头”，不用“匹”，“一匹白牛”不成立。"}, {"text": "猫", "is_correct": false, "explanation": "量词：猫用“只”，不用“匹”，“一匹白猫”不成立。"}, {"text": "树", "is_correct": false, "explanation": "量词：树用“棵”，不用“匹”，“一匹白树”不成立。"}], "explanations": {"马": "正确答案。“一匹白马”指白色的马。", "牛": "量词：牛用“头”，不用“匹”，“一匹白牛”不成立。", "猫": "量词：猫用“只”，不用“匹”，“一匹白猫”不成立。", "树": "量词：树用“棵”，不用“匹”，“一匹白树”不成立。"}, "sentence_index": 0, "correct_answer": "马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这匹马在院子里喵喵地叫。", "explanation": "这里应该用〈嘶〉。喵喵是猫的叫声，马的叫声应说“嘶”，不能用“喵喵”。"}, {"text": "公马每天早上打鸣，吵醒了整个村子。", "explanation": "这里应该用〈嘶〉。打鸣是公鸡的叫声，马的叫声应说“嘶”。"}, {"text": "他每天开马去学校。", "explanation": "这里应该用〈骑〉。开用于车辆，马不能被开，应改为“骑马”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39826, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "马", "is_correct": true, "explanation": "正确答案。马 mǎ，一种可以骑的动物。"}, {"text": "哪", "is_correct": false, "explanation": "nǎ 与 mǎ 声母不同（n 与 m），意思是哪。"}, {"text": "把", "is_correct": false, "explanation": "bǎ 与 mǎ 声母不同（b 与 m），意思是把。"}, {"text": "法", "is_correct": false, "explanation": "fǎ 与 mǎ 声母不同（f 与 m），意思是法律、方法。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 mǎ（第三声）声调不同，意思是麻。"}], "explanations": {"马": "正确答案。马 mǎ，一种可以骑的动物。", "哪": "nǎ 与 mǎ 声母不同（n 与 m），意思是哪。", "把": "bǎ 与 mǎ 声母不同（b 与 m），意思是把。", "法": "fǎ 与 mǎ 声母不同（f 与 m），意思是法律、方法。", "麻": "má（第二声）与 mǎ（第三声）声调不同，意思是麻。"}, "sentence_index": null, "correct_answer": "马"}, "level_3": {"options": [{"text": "马", "is_correct": true, "explanation": "正确答案。“给马喂草”指给马吃草。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不吃草，“给树喂草”不合常理。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“喂”多用于动物，不用于花。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不能吃草，句子描述的是活的动物。"}], "explanations": {"马": "正确答案。“给马喂草”指给马吃草。", "树": "语义：树不吃草，“给树喂草”不合常理。", "花": "搭配：“喂”多用于动物，不用于花。", "墙": "语义：墙不能吃草，句子描述的是活的动物。"}, "sentence_index": 6, "correct_answer": "马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用马洗衣服。", "explanation": "这里应该用〈盆〉。马是动物，不能当洗衣工具，洗衣服要用盆。"}, {"text": "他每天坐马去上班。", "explanation": "这里应该用〈骑〉。人可以坐车，但骑马才是正确说法，马不能用“坐”。"}, {"text": "他用马吃饭。", "explanation": "这里应该用〈碗〉。马是动物，不能当餐具，吃饭要用碗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家养了一只马。", "corrected_sentence": "我家养了一匹马。", "error_description": "量词错误：马的量词应为“匹”，不能用“只”。正确形式是“一匹马”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家养了一只白马。", "corrected_sentence": "他家养了一匹白马。", "error_description": "量词错误：马的量词应为“匹”，不能用“只”。正确形式是“一匹白马”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
