INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出一个样子，让别人以为是真的。", "primary_collocate": null, "pronunciation": "jiǎ zhuāng", "ipa": "tɕja˨˩˦ ʈʂwaŋ˥", "syllable_count": 2, "sentences": [{"text": "她假装不累，继续往前走。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗假装没看见我们。", "target_word": "假装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他假装喝醉了，躺在沙发上。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用假装高兴。", "target_word": "假装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师知道他在假装，没有说话。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹假装自己是医生，给娃娃看病。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他假装打电话，不想理那个人。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我假装没有看到，就走开了。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们假装睡着了，等着妈妈关灯。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥假装生气，其实一点也不生气。", "target_word": "假装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "假装着", "label": "体标"}, {"form": "假装过", "label": "体标"}, {"form": "假裝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做出样子，让别人信以为真", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "假装", "is_correct": true, "explanation": "正确答案。假装 jiǎ zhuāng，做出一个样子，让别人以为是真的。"}, {"text": "加装", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加安装。"}, {"text": "家装", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家庭装修。"}, {"text": "嫁妆", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是陪嫁的财物。"}], "explanations": {"假装": "正确答案。假装 jiǎ zhuāng，做出一个样子，让别人以为是真的。", "加装": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加安装。", "家装": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家庭装修。", "嫁妆": "jià（第四声）与 jiǎ（第三声）声调不同，意思是陪嫁的财物。"}, "sentence_index": null, "correct_answer": "假装"}, "level_3": {"options": [{"text": "假装", "is_correct": true, "explanation": "正确答案。“假装不累”表示故意做出不累的样子。"}, {"text": "担心", "is_correct": false, "explanation": "搭配：“担心”接的是可能发生的坏事，不接“不累”这样的状态。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：“拒绝”要接请求或事情，不能直接接“不累”这样的状态。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指记不住，与句中有意识地继续往前走的语境不符。"}], "explanations": {"假装": "正确答案。“假装不累”表示故意做出不累的样子。", "担心": "搭配：“担心”接的是可能发生的坏事，不接“不累”这样的状态。", "拒绝": "配价：“拒绝”要接请求或事情，不能直接接“不累”这样的状态。", "忘记": "语义：“忘记”指记不住，与句中有意识地继续往前走的语境不符。"}, "sentence_index": 0, "correct_answer": "假装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子假装很舒服。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，椅子不能故意做样子；只说外观时用“显得”。"}, {"text": "这间屋子假装得很暖和。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，屋子不能故意做样子；只说感觉时用“显得”。"}, {"text": "这张桌子假装很结实。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，桌子不能故意做样子；只说外观时用“显得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假装", "is_correct": true, "explanation": "正确答案。“假装打电话”表示做出打电话的样子。"}, {"text": "担心", "is_correct": false, "explanation": "搭配：“担心”接的是可能发生的坏事，不接“打电话”这样的动作。"}, {"text": "练习", "is_correct": false, "explanation": "语义：“练习”指反复学习，与“不想理那个人”的语境不合。"}, {"text": "帮助", "is_correct": false, "explanation": "配价：“帮助”需要受助对象，句中没有受助者，且与语境不合。"}], "explanations": {"假装": "正确答案。“假装打电话”表示做出打电话的样子。", "担心": "搭配：“担心”接的是可能发生的坏事，不接“打电话”这样的动作。", "练习": "语义：“练习”指反复学习，与“不想理那个人”的语境不合。", "帮助": "配价：“帮助”需要受助对象，句中没有受助者，且与语境不合。"}, "sentence_index": 6, "correct_answer": "假装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书假装很厚。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，书不能故意做样子；只说外观时用“显得”。"}, {"text": "这碗粥假装很香。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，粥不能故意做样子；只说气味或外观时用“显得”。"}, {"text": "这块石头假装很甜。", "explanation": "这里应该用〈显得〉。假装要求有意图的施事者，石头不能故意做样子；只说外观时用“显得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把假装累了，躺在床上。", "corrected_sentence": "他假装累了，躺在床上。", "error_description": "结构错误：“假装”前不能加“把”，“把”字句要求处置某个对象，这里应删去“把”。正确形式：“他假装累了，躺在床上。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们假过装睡着了，等着妈妈回来。", "corrected_sentence": "孩子们假装睡着了，等着妈妈回来。", "error_description": "词内插入：“过”被插在双音词“假装”中间，把整词拆开。“假装”不能拆分，应删去“过”。正确形式：“孩子们假装睡着了，等着妈妈回来。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
