INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39830, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "骑马就是坐在马背上，让马带着你走。", "primary_collocate": null, "pronunciation": "qí mǎ", "ipa": "tɕʰi˧˥ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想去草原骑马。", "target_word": "骑马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑马骑得很好。", "target_word": "骑马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友不能一个人骑马。", "target_word": "骑马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑马的人都要戴安全帽。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐明天带我去骑马。", "target_word": "骑马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢在海边骑马。", "target_word": "骑马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑马时，你的身体要坐直。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸教我骑马，我很快就学会了。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里可以骑马，也可以划船。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们骑马过河，对面就是农场。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骑着马", "label": "体标"}, {"form": "骑过马", "label": "体标"}, {"form": "騎馬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "坐在马背上，让马带着走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骑马", "is_correct": true, "explanation": "骑马：去草原做的活动，符合“草原”的语境。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“想去草原咳嗽”不是可以去做的活动，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能被人“去”做，句意不通。"}, {"text": "洗碗", "is_correct": false, "explanation": "搭配：“去草原洗碗”的说法不符合去草原的活动，与语境不搭。"}], "explanations": {"骑马": "骑马：去草原做的活动，符合“草原”的语境。", "咳嗽": "语义：“想去草原咳嗽”不是可以去做的活动，句意不通。", "下雨": "语义：“下雨”是天气现象，不能被人“去”做，句意不通。", "洗碗": "搭配：“去草原洗碗”的说法不符合去草原的活动，与语境不搭。"}, "sentence_index": 0, "correct_answer": "骑马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天骑马做饭，做得很快。", "explanation": "语义：骑马指骑在马背上让马带着走，不能用来表示做饭这类家务。"}, {"text": "那只小狗骑马去了农场。", "explanation": "语义：骑马的动作应由人完成，小狗不能骑马，这里的主语与动作不匹配。"}, {"text": "他骑马擦完了窗户。", "explanation": "语义：骑马指骑在马背上让马带着走，不能用来表示擦窗户这类家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骑马", "is_correct": true, "explanation": "骑马：骑在马背上时身体要坐直，符合句子的语境。"}, {"text": "打滚", "is_correct": false, "explanation": "语义：打滚时身体要翻转，与“要坐直”的要求相矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时要躺下，不能要求身体坐直，与句意矛盾。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”是及物动词，要接所扔之物，句中没有宾语，句子不完整。"}], "explanations": {"骑马": "骑马：骑在马背上时身体要坐直，符合句子的语境。", "打滚": "语义：打滚时身体要翻转，与“要坐直”的要求相矛盾。", "睡觉": "语义：睡觉时要躺下，不能要求身体坐直，与句意矛盾。", "扔": "配价：“扔”是及物动词，要接所扔之物，句中没有宾语，句子不完整。"}, "sentence_index": 6, "correct_answer": "骑马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐姐每天骑马看书，看得很快。", "explanation": "语义：骑马指骑在马背上让马带着走，不能用来表示阅读，这里的“骑马”与看书的动作无关。"}, {"text": "这些汽车都会骑马。", "explanation": "语义：骑马的主体是人，汽车不能骑马，这里的“骑马”被误用于机动车。"}, {"text": "这只猫骑马睡着了。", "explanation": "语义：骑马的主体应是骑马的人，猫不能骑马，这句话中的动作与骑马的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候在草原上骑马过。", "corrected_sentence": "我小时候在草原上骑过马。", "error_description": "错误形式：“过”放在“马”后，写成“骑马过”。正确形式：“过”应紧接动词，写作“骑过马”，即“我小时候在草原上骑过马”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候骑马那匹老马。", "corrected_sentence": "他小时候骑了那匹老马。", "error_description": "错误形式：“骑马”是离合词，已含宾语“马”，不能再直接接宾语“那匹老马”。正确形式：在“骑”与宾语之间用“了”，写作“他小时候骑了那匹老马。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
