INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39831, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39831, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指骑在马上，是一种活动或运动。", "primary_collocate": null, "pronunciation": "qí mǎ", "ipa": "tɕʰi˧˥ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "他每天清早骑马巡视牧场。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去草原骑马。", "target_word": "骑马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就会骑马。", "target_word": "骑马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑马是一项很有意思的运动。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学骑马，你能教我吗？", "target_word": "骑马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿着长裤去骑马。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天第一次骑马，有点害怕。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时常常骑马上山。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑马的时候要戴帽子。", "target_word": "骑马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们骑马走过了那片草地。", "target_word": "骑马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骑着马", "label": "体标"}, {"form": "骑过马", "label": "体标"}, {"form": "騎馬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "骑在马上，作为活动或运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骑马", "is_correct": true, "explanation": "骑马：骑在马背上巡视牧场，符合句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与巡视牧场的动作不相容，句意不通。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋与巡视牧场无关，句意不通。"}, {"text": "种花", "is_correct": false, "explanation": "语义：种花与巡视牧场的活动不相容，句意不通。"}], "explanations": {"骑马": "骑马：骑在马背上巡视牧场，符合句意。", "游泳": "语义：游泳与巡视牧场的动作不相容，句意不通。", "下棋": "语义：下棋与巡视牧场无关，句意不通。", "种花": "语义：种花与巡视牧场的活动不相容，句意不通。"}, "sentence_index": 0, "correct_answer": "骑马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们每天骑马耕地，干活很辛苦。", "explanation": "这里应该用〈赶马〉。骑马指人骑在马背上游玩或运动，用马耕地要说赶马，不能说骑马。"}, {"text": "这间屋子骑马很宽敞。", "explanation": "语义：骑马的主体必须是骑的人或能骑的动物，房屋不能骑马，这里的“骑马”与描述空间大小毫无关系。"}, {"text": "他骑马把饭煮好了。", "explanation": "语义：骑马指骑在马背上移动或运动，不能用来表示做饭；做饭要用〈做〉之类的动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骑马", "is_correct": true, "explanation": "骑马：第一次骑马有点害怕，符合句子的语境。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：“大笑”表示高兴地笑，与“有点害怕”的情绪相反，句意矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“第一次桌子”不是动作，句意不通。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：“第一次雨水”不是动作，句意不通。"}], "explanations": {"骑马": "骑马：第一次骑马有点害怕，符合句子的语境。", "大笑": "语义：“大笑”表示高兴地笑，与“有点害怕”的情绪相反，句意矛盾。", "桌子": "语义：“第一次桌子”不是动作，句意不通。", "雨水": "语义：“第一次雨水”不是动作，句意不通。"}, "sentence_index": 6, "correct_answer": "骑马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们每天骑马洗衣服，已经很多年了。", "explanation": "语义：骑马指骑在马背上游玩或运动，不能用于洗衣服这类家务。"}, {"text": "那辆汽车骑马开得很稳。", "explanation": "语义：骑马的主体必须是骑的人，汽车不能骑马；开车要说〈驾驶〉。"}, {"text": "他们骑马写了三封信。", "explanation": "语义：骑马指骑在马背上移动或运动，不表示书写；写信要用〈书写〉之类的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天去草原骑马了。", "corrected_sentence": "我们明天去草原骑马。", "error_description": "错误形式：“明天”表示将来，句尾不能加“了”。正确形式：去掉“了”，写作“我们明天去草原骑马”。“了”表示已经完成，与将来的时间词冲突。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我上周骑马那匹白马，很开心。", "corrected_sentence": "我上周骑了那匹白马，很开心。", "error_description": "错误形式：“骑马”是离合词，已含宾语“马”，不能再直接接宾语“那匹白马”。正确形式：在“骑”与宾语之间用“了”，写作“我上周骑了那匹白马，很开心。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
