INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指做游戏或进行娱乐活动。", "primary_collocate": null, "pronunciation": "wán shuǎ", "ipa": "wan˧˥ ʂwa˨˩˦", "syllable_count": 2, "sentences": [{"text": "木马让儿童的玩耍时光更加有趣。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "古罗马的孩子们很喜欢各种玩具，他们通过玩耍来学习和成长。", "target_word": "玩耍", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "古罗马的儿童也有玩耍的时间。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "孩子们在公园里玩耍。", "target_word": "玩耍", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下课后，同学们在操场上玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗和小猫在草地上一起玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们玩耍了一个下午，都累了。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不让孩子在马路上玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在河边玩耍着，笑声不断。", "target_word": "玩耍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我常和朋友在树下玩耍。", "target_word": "玩耍", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "玩耍了", "label": "体标"}, {"form": "玩耍着", "label": "体标"}, {"form": "玩耍过", "label": "体标"}], "register": "中性", "sense_fingerprint": "孩子等做游戏、进行娱乐活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2add0e14-7aad-4c53-8a62-eca53035b254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玩耍", "is_correct": true, "explanation": "正确：“玩耍”指儿童做游戏、娱乐，与“木马”和“有趣”相合。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作”指劳动谋生，与儿童的“有趣”时光不符。"}, {"text": "劳动", "is_correct": false, "explanation": "搭配：“时光”多与“快乐”“童年”搭配，“劳动时光”不是常用说法。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是不愉快的状态，不能修饰“更加有趣”的时光。"}], "explanations": {"玩耍": "正确：“玩耍”指儿童做游戏、娱乐，与“木马”和“有趣”相合。", "工作": "语义：“工作”指劳动谋生，与儿童的“有趣”时光不符。", "劳动": "搭配：“时光”多与“快乐”“童年”搭配，“劳动时光”不是常用说法。", "生病": "语义：“生病”是不愉快的状态，不能修饰“更加有趣”的时光。"}, "sentence_index": 0, "correct_answer": "玩耍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们在工地上玩耍。", "explanation": "这里应该用〈劳动〉。玩耍指做游戏、娱乐，不用于工作场合。"}, {"text": "法官在法庭上玩耍，不认真审案。", "explanation": "这里应该用〈审理〉。玩耍是娱乐活动，不能用于法庭上的严肃审理。"}, {"text": "学生们在考场上玩耍。", "explanation": "这里应该用〈考试〉。玩耍是轻松的娱乐，不能用来描述严肃的考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩耍", "is_correct": true, "explanation": "正确：“玩耍”表示一段时间里做游戏，与“一个下午”“累了”相合。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”是一次性的事件，不能持续“一个下午”。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”是一次性的动作，不能说持续了一个下午。"}, {"text": "结婚", "is_correct": false, "explanation": "体貌：“结婚”是离合词，持续时间要插在中间，应说“结了一个下午婚”。"}], "explanations": {"玩耍": "正确：“玩耍”表示一段时间里做游戏，与“一个下午”“累了”相合。", "出生": "语义：“出生”是一次性的事件，不能持续“一个下午”。", "迟到": "语义：“迟到”是一次性的动作，不能说持续了一个下午。", "结婚": "体貌：“结婚”是离合词，持续时间要插在中间，应说“结了一个下午婚”。"}, "sentence_index": 6, "correct_answer": "玩耍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "信徒们在教堂里玩耍。", "explanation": "这里应该用〈祈祷〉。玩耍是轻松的娱乐，不用于宗教活动。"}, {"text": "人们在葬礼上玩耍。", "explanation": "这里应该用〈哀悼〉。葬礼是严肃场合，不能用“玩耍”来描述。"}, {"text": "警察在执勤时玩耍。", "explanation": "这里应该用〈值班〉。玩耍是娱乐，不能用于执勤这类职责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们玩耍的很开心。", "corrected_sentence": "孩子们玩耍得很开心。", "error_description": "补语标记应用“得”，不能用“的”。程度补语紧跟在动词后面，应说“玩耍得很开心”，不能说“玩耍的很开心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们河边玩耍。", "corrected_sentence": "他们在河边玩耍。", "error_description": "处所状语要用“在”引出，应说“他们在河边玩耍”，不能省略“在”说“他们河边玩耍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不断流逝的时间本身，如“时光飞逝”。", "primary_collocate": null, "pronunciation": "shí guāng", "ipa": "ʂʐ̩˧˥ kuɑŋ˥", "syllable_count": 2, "sentences": [{"text": "时光过得真快，一年又过去了。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天和黑夜，都是时光的一部分。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起又落下，时光就这样走过。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要珍惜时光，不要浪费。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时光一天天过去，孩子长高了。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一天有二十四小时，时光不会停下来。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟表的指针转动，告诉我们时光在走。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春夏秋冬，时光不停地向前走。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时光慢慢地过去，天黑了。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天读书，不想浪费时光。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "時光", "label": "繁体"}, {"form": "时光机", "label": "复合"}], "register": "书面", "sense_fingerprint": "时光：不断流逝的时间本身（时光飞逝、珍惜时光）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时光", "is_correct": true, "explanation": "时光：不断流逝的时间本身，“时光过得真快”符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是流逝的时间，“天气过得真快”与句意不合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会“过得”快慢，与句中的时间流逝不相符。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本过得真快”的说法不成立，课本不能作为时间流逝的主语。"}], "explanations": {"时光": "时光：不断流逝的时间本身，“时光过得真快”符合句意。", "天气": "语义：天气不是流逝的时间，“天气过得真快”与句意不合。", "作业": "语义：作业不会“过得”快慢，与句中的时间流逝不相符。", "课本": "搭配：“课本过得真快”的说法不成立，课本不能作为时间流逝的主语。"}, "sentence_index": 0, "correct_answer": "时光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天没有时光去超市了，因为作业太多。", "explanation": "这里应该用〈时间〉。时光指不断流逝的时间本身，可支配的空闲要说时间。"}, {"text": "我们要珍惜一个时光，不要浪费。", "explanation": "这里应该用量词〈段〉。“一段时光”才是正确的说法。"}, {"text": "这个房间的时光很亮，照得人睁不开眼。", "explanation": "语义：时光不指光线，用来描述房间的亮度是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时光", "is_correct": true, "explanation": "时光：不断流逝的时间本身，“告诉我们时光在走”指时间在流逝，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会自己移动，“告诉我们桌子在走”与钟表指针的语境不合。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“在走”不能用于窗户，窗户不会行走。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐不是流逝的时间，“告诉我们盐在走”句意不通。"}], "explanations": {"时光": "时光：不断流逝的时间本身，“告诉我们时光在走”指时间在流逝，符合句意。", "桌子": "语义：桌子不会自己移动，“告诉我们桌子在走”与钟表指针的语境不合。", "窗户": "搭配：“在走”不能用于窗户，窗户不会行走。", "盐": "语义：盐不是流逝的时间，“告诉我们盐在走”句意不通。"}, "sentence_index": 6, "correct_answer": "时光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天读书，没有时光休息。", "explanation": "这里应该用〈时间〉。时光指不断流逝的时间本身，表示可以休息的空闲要说时间。"}, {"text": "他每天读书，一个时光都不想浪费。", "explanation": "这里应该用量词〈段〉，“一段时光”才是正确的说法。"}, {"text": "他的时光很亮，照亮了整个屋子。", "explanation": "语义：时光不指光线，用“时光很亮”来形容光线是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年时光得过很快。", "corrected_sentence": "这几年时光过得很快。", "error_description": "错误形式：“过得”后的补语结构颠倒，写成了“得过”。正确形式：应写作“过得很快”，补语“得”后接形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一起度过了一只愉快的时光。", "corrected_sentence": "他们一起度过了一段愉快的时光。", "error_description": "错误形式：“时光”的量词用了“只”。正确形式：应用“段”，写作“一段愉快的时光”。“只”不用于指一段时期。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
