INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指时间、光阴，常用来描述一段有特定意义或感受的时期。", "primary_collocate": null, "pronunciation": "shí guāng", "ipa": "ʂʐ̩˧˥ kuɑŋ˥", "syllable_count": 2, "sentences": [{"text": "木马让儿童的玩耍时光更加有趣。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们在海边度过了一段美好的时光。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学时光让我认识了很多好朋友。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想念和奶奶在一起的那段时光。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "童年时光是我最难忘的回忆。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和家人吃饭的时光总是很温暖。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在乡下过着安静的时光。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段时光虽然辛苦，但我很珍惜。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老照片让我想起了那些快乐的时光。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一起学习的时光过得特别快。", "target_word": "时光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段时光", "label": "量词"}, {"form": "時光", "label": "繁体"}, {"form": "时光机", "label": "复合"}], "register": "书面", "sense_fingerprint": "时光：有特定意义或感受的一段时期（美好时光、童年时光）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时光", "is_correct": true, "explanation": "时光：一段有特定感受的时期，“玩耍时光”指玩耍的那段时期，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是一段时期，“玩耍作业”与句意矛盾。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“玩耍课本”的说法不成立，课本不能作为玩耍的对象。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典不是玩耍的对象，“玩耍字典”句意不通。"}], "explanations": {"时光": "时光：一段有特定感受的时期，“玩耍时光”指玩耍的那段时期，符合句意。", "作业": "语义：作业不是一段时期，“玩耍作业”与句意矛盾。", "课本": "搭配：“玩耍课本”的说法不成立，课本不能作为玩耍的对象。", "字典": "语义：字典不是玩耍的对象，“玩耍字典”句意不通。"}, "sentence_index": 0, "correct_answer": "时光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天没有时光做作业了，因为要去超市。", "explanation": "这里应该用〈时间〉。时光指一段有感受的时期，表示可支配的空闲要说时间。"}, {"text": "我小时光去过那里，还记得那里的花。", "explanation": "这里应该用〈时候〉。时光指一段有感受的时期，指小时候这类时间点要说时候。"}, {"text": "中午的时光很刺眼，照得人睁不开眼。", "explanation": "语义：时光不指光线，这里的“时光”用来表示光线是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时光", "is_correct": true, "explanation": "时光：一段安静的时期，“过着安静的时光”符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“过着安静的桌子”的说法不成立，桌子不能被“过”。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不是可以度过的一段时期，“过着安静的雨水”句意不通。"}, {"text": "收音机", "is_correct": false, "explanation": "搭配：收音机不能被“过着”来描述，“过着安静的收音机”的说法不成立。"}], "explanations": {"时光": "时光：一段安静的时期，“过着安静的时光”符合句意。", "桌子": "搭配：“过着安静的桌子”的说法不成立，桌子不能被“过”。", "雨水": "语义：雨水不是可以度过的一段时期，“过着安静的雨水”句意不通。", "收音机": "搭配：收音机不能被“过着”来描述，“过着安静的收音机”的说法不成立。"}, "sentence_index": 6, "correct_answer": "时光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约在明天这个时光见面。", "explanation": "这里应该用〈时刻〉。时光指一段有感受的时期，指某个时间点要说时刻。"}, {"text": "这个时光的人都爱手机。", "explanation": "这里应该用〈时代〉。时光指一段有感受的时期，指一个历史阶段要说时代。"}, {"text": "黄昏的时光照在窗户上，很暖和。", "explanation": "语义：时光不指光线，“黄昏的时光照在窗户上”中的“时光”用来指光线是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在湖边度过了一只难忘的时光。", "corrected_sentence": "他们在湖边度过了一段难忘的时光。", "error_description": "错误形式：“时光”的量词用了“只”。正确形式：应用“段”，写作“一段难忘的时光”。“只”用于动物或成对之物，不能用来指一段时期。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶在院子里度了一段悠闲的时光。", "corrected_sentence": "奶奶在院子里度过了一段悠闲的时光。", "error_description": "错误形式：“度”后缺少“过”，写成“度了”。正确形式：应写作“度过了”，即“度过了一段悠闲的时光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
