INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39838, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人慢慢长大，变得更强。", "primary_collocate": null, "pronunciation": "chéng zhǎng", "ipa": "ʈʂʰɤŋ˧˥ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子们在山里慢慢成长。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小吃得好，成长得很快。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷看着我一天天成长。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明已经成长为一个强壮的青年。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动能让孩子成长得更强壮。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在农村成长，身体特别好。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成长的路上，爸爸一直陪着我。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些孩子成长得又高又壮。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看着他长大，看着他成长。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在爱里成长，变得越来越强。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成长了", "label": "体标"}, {"form": "成长着", "label": "体标"}, {"form": "成长过", "label": "体标"}, {"form": "成長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "成长：人慢慢长大并变强壮（成长得很快、成长为青年）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成长", "is_correct": true, "explanation": "正确：“孩子们在山里慢慢成长”，“成长”指人慢慢长大变强，符合句意。"}, {"text": "回答", "is_correct": false, "explanation": "语义：“回答”指应答说话，与“慢慢长大”无关，句意不通。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”用于火或灯，不能用来说孩子。"}, {"text": "下沉", "is_correct": false, "explanation": "语义：“下沉”指向下落，不是孩子长大变强的意思，句意不通。"}], "explanations": {"成长": "正确：“孩子们在山里慢慢成长”，“成长”指人慢慢长大变强，符合句意。", "回答": "语义：“回答”指应答说话，与“慢慢长大”无关，句意不通。", "熄灭": "搭配：“熄灭”用于火或灯，不能用来说孩子。", "下沉": "语义：“下沉”指向下落，不是孩子长大变强的意思，句意不通。"}, "sentence_index": 0, "correct_answer": "成长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的水位成长了两米。", "explanation": "这里应该用〈上涨〉。成长指人慢慢长大变强，水位的升高要用上涨。"}, {"text": "他的考试成绩成长得很快。", "explanation": "这里应该用〈提高〉。成长指人慢慢长大变强，成绩变好要用提高。"}, {"text": "他的书包成长了五公斤。", "explanation": "这里应该用〈增加〉。成长指人慢慢长大变强，书包重量的变化要用增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成长", "is_correct": true, "explanation": "正确：“成长的路上”指孩子慢慢长大变强的过程，“成长”作定语，符合句意。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”指金属被氧化，不能用来说人慢慢长大的过程。"}, {"text": "烧焦", "is_correct": false, "explanation": "搭配：“烧焦”形容食物或物体被烧坏，不能修饰“路上”。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：“腐烂”与爸爸一直陪伴的温情语境相反，句意不通。"}], "explanations": {"成长": "正确：“成长的路上”指孩子慢慢长大变强的过程，“成长”作定语，符合句意。", "生锈": "搭配：“生锈”指金属被氧化，不能用来说人慢慢长大的过程。", "烧焦": "搭配：“烧焦”形容食物或物体被烧坏，不能修饰“路上”。", "腐烂": "语义：“腐烂”与爸爸一直陪伴的温情语境相反，句意不通。"}, "sentence_index": 6, "correct_answer": "成长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个商场的面积成长了一倍。", "explanation": "这里应该用〈扩大〉。成长指人慢慢长大变强，面积变大要用扩大。"}, {"text": "这个小镇的人口成长到了一万。", "explanation": "这里应该用〈增长〉。成长指人慢慢长大变强，人口的增长要用增长。"}, {"text": "奶奶的身体成长得越来越好。", "explanation": "这里应该用〈好转〉。成长指人慢慢长大变强，只用于成长中的人；老人身体变好要用好转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹在我们的照顾下慢慢成长上来了。", "corrected_sentence": "妹妹在我们的照顾下慢慢成长起来了。", "error_description": "错误在补语：“成长”后面应接“起来”，表示逐渐长大变强；“上来”不能接在“成长”后面。正确形式：成长起来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长大后成长了为优秀的医生。", "corrected_sentence": "他长大后成长为优秀的医生。", "error_description": "错误在“了”的位置：“成长为”表示发展变成某种身份，中间不能插入“了”，“了”不能放在“成长”和“为”之间。正确形式：成长为优秀的医生。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
