INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39839, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在身体、心理或能力方面逐渐发展成熟。", "primary_collocate": null, "pronunciation": "chéng zhǎng", "ipa": "ʈʂʰɤŋ˧˥ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "古罗马的孩子们很喜欢这个玩具，他们通过玩耍来学习和成长。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "孩子在爱的环境里健康成长。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过这次失败，他成长了很多。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书能帮助我们在心理上成长。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从一个新手成长为优秀的老师。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司帮助年轻人快速成长。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母要多给孩子成长的空间。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在朋友的帮助下，他一步步成长起来。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都要在困难中成长。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着孩子一天天成长，妈妈很高兴。", "target_word": "成长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成长了", "label": "体标"}, {"form": "成长着", "label": "体标"}, {"form": "成长过", "label": "体标"}, {"form": "成長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "成长：身体、心理、能力逐渐发展成熟（健康成长、成长为）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成长", "is_correct": true, "explanation": "正确：“学习和成长”并列，“成长”指在身心上逐渐发展成熟，符合句意。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”与“通过玩耍来学习”的目的无关，句意不通。"}, {"text": "打碎", "is_correct": false, "explanation": "配价：“打碎”是及物动词，需要宾语，这里没有宾语，且与学习无关。"}, {"text": "摔倒", "is_correct": false, "explanation": "搭配：“学习和摔倒”不成搭配，“摔倒”不能与“学习”并列作为玩耍的目的。"}], "explanations": {"成长": "正确：“学习和成长”并列，“成长”指在身心上逐渐发展成熟，符合句意。", "生病": "语义：“生病”与“通过玩耍来学习”的目的无关，句意不通。", "打碎": "配价：“打碎”是及物动词，需要宾语，这里没有宾语，且与学习无关。", "摔倒": "搭配：“学习和摔倒”不成搭配，“摔倒”不能与“学习”并列作为玩耍的目的。"}, "sentence_index": 0, "correct_answer": "成长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的工资成长了三百元。", "explanation": "这里应该用〈增长〉。成长指人在身体、心理或能力方面逐渐发展成熟，工资的增加要用增长。"}, {"text": "他的手机成长得很快。", "explanation": "这里应该用〈更新〉。成长指人在身体、心理或能力方面逐渐发展成熟，手机的换代要用更新。"}, {"text": "他的病情成长了一些。", "explanation": "这里应该用〈好转〉。成长指人在身体、心理或能力方面逐渐发展成熟，病情变好要用好转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成长", "is_correct": true, "explanation": "正确：“孩子成长的空间”指孩子发展的余地，“成长”作定语修饰“空间”，符合句意。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”指睡不着觉，不能修饰“空间”表示发展的余地，句意不通。"}, {"text": "迷路", "is_correct": false, "explanation": "搭配：“迷路”是人的动作，“迷路的空间”不成搭配，空间不会迷路。"}, {"text": "挨饿", "is_correct": false, "explanation": "语义：“挨饿”与父母给孩子发展余地的意思相反，句意不通。"}], "explanations": {"成长": "正确：“孩子成长的空间”指孩子发展的余地，“成长”作定语修饰“空间”，符合句意。", "失眠": "语义：“失眠”指睡不着觉，不能修饰“空间”表示发展的余地，句意不通。", "迷路": "搭配：“迷路”是人的动作，“迷路的空间”不成搭配，空间不会迷路。", "挨饿": "语义：“挨饿”与父母给孩子发展余地的意思相反，句意不通。"}, "sentence_index": 6, "correct_answer": "成长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的人数成长到了四十人。", "explanation": "这里应该用〈增加〉。成长指人在身体、心理或能力方面逐渐发展成熟，人数的增多要用增加。"}, {"text": "这块地的面积成长了一倍。", "explanation": "这里应该用〈扩大〉。成长指人在身体、心理或能力方面逐渐发展成熟，面积变大要用扩大。"}, {"text": "他病好以后，伤口成长得很快。", "explanation": "这里应该用〈愈合〉。成长指人在身体、心理或能力方面逐渐发展成熟，伤口的复原要用愈合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子在学校里慢慢成长下来。", "corrected_sentence": "孩子在学校里慢慢成长起来。", "error_description": "错误在补语：“成长”后面应接“起来”，表示逐渐开始并发展；“下来”表示由高到低或由动到静，不能说“成长下来”。正确形式：成长起来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的身体成长地很好。", "corrected_sentence": "他的身体成长得很好。", "error_description": "错误在程度补语的标记：“成长”后面的程度补语要用“得”，“地”只用来修饰动词。正确形式：成长得很好。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39840, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确：“怯懦”与“勇敢”构成反义，指胆小、不敢去做，与本义相反。"}, {"text": "善良", "is_correct": false, "explanation": "与“勇敢”无反义关系，“善良”指心地纯净、待人友好。"}, {"text": "富裕", "is_correct": false, "explanation": "与“勇敢”无反义关系，“富裕”指钱财多。"}, {"text": "热闹", "is_correct": false, "explanation": "与“勇敢”无反义关系，“热闹”指人多、声音大。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确：“怯懦”与“勇敢”构成反义，指胆小、不敢去做，与本义相反。", "善良": "与“勇敢”无反义关系，“善良”指心地纯净、待人友好。", "富裕": "与“勇敢”无反义关系，“富裕”指钱财多。", "热闹": "与“勇敢”无反义关系，“热闹”指人多、声音大。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39840, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确：“怯懦”与“勇敢”构成反义，指胆小、不敢去做，与本义相反。"}, {"text": "清楚", "is_correct": false, "explanation": "与“勇敢”无反义关系，“清楚”指明白、不模糊。"}, {"text": "圆滑", "is_correct": false, "explanation": "与“勇敢”无反义关系，“圆滑”指处事灵活、不得罪人。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“勇敢”无反义关系，“漂亮”指外貌好看。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确：“怯懦”与“勇敢”构成反义，指胆小、不敢去做，与本义相反。", "清楚": "与“勇敢”无反义关系，“清楚”指明白、不模糊。", "圆滑": "与“勇敢”无反义关系，“圆滑”指处事灵活、不得罪人。", "漂亮": "与“勇敢”无反义关系，“漂亮”指外貌好看。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39840, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "勇敢就是不怕危险，敢去做。", "primary_collocate": null, "pronunciation": "yǒng gǎn", "ipa": "jʊŋ˨˩˦ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个孩子很勇敢，不怕黑。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他勇敢地跳进河里。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要勇敢，别怕。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗勇敢地跑向大狗。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇敢的人敢一个人走夜路。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很勇敢，第一个举手说话。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想做一个勇敢的人。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕蛇，真勇敢。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇敢的小男孩去了山洞。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大水，他勇敢地救了小孩。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勇敢地", "label": "状语形式"}, {"form": "勇敢者", "label": "复合"}], "register": "中性", "sense_fingerprint": "勇敢：不怕危险、敢于去做（很勇敢、勇敢地跳）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勇敢", "is_correct": true, "explanation": "正确：“很勇敢”作谓语，与后面“不怕黑”呼应，符合句意。"}, {"text": "胆小", "is_correct": false, "explanation": "语义：“胆小”与“不怕黑”矛盾，句意不通。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“很饿”与“不怕黑”没有关系，句意不通。"}, {"text": "近视", "is_correct": false, "explanation": "语义：“近视”指看远处模糊，与“不怕黑”的胆量无关，句意不通。"}], "explanations": {"勇敢": "正确：“很勇敢”作谓语，与后面“不怕黑”呼应，符合句意。", "胆小": "语义：“胆小”与“不怕黑”矛盾，句意不通。", "饿": "语义：“很饿”与“不怕黑”没有关系，句意不通。", "近视": "语义：“近视”指看远处模糊，与“不怕黑”的胆量无关，句意不通。"}, "sentence_index": 0, "correct_answer": "勇敢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑很勇敢，运行得很流畅。", "explanation": "这里应该用〈流畅〉。勇敢形容人不怕危险、敢去做，电脑运行顺畅要用流畅。"}, {"text": "今天的天气很勇敢，阳光很好。", "explanation": "这里应该用〈晴朗〉。勇敢形容人敢去做，天气的晴朗要用晴朗。"}, {"text": "他的嗓音很勇敢，在合唱中很突出。", "explanation": "这里应该用〈洪亮〉。勇敢形容人敢去做，嗓音的响亮要用洪亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勇敢", "is_correct": true, "explanation": "正确：“勇敢的人”修饰“人”，指敢于面对危险、敢去做的人，符合句意。"}, {"text": "方形", "is_correct": false, "explanation": "搭配：“方形”指物体的形状，不能用来形容人。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与人的品质无关，句意不通。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“湿”形容物体的状态，不能用来形容人的品质。"}], "explanations": {"勇敢": "正确：“勇敢的人”修饰“人”，指敢于面对危险、敢去做的人，符合句意。", "方形": "搭配：“方形”指物体的形状，不能用来形容人。", "咸": "语义：“咸”指味道，与人的品质无关，句意不通。", "湿": "搭配：“湿”形容物体的状态，不能用来形容人的品质。"}, "sentence_index": 6, "correct_answer": "勇敢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的朗读很勇敢，每个字都清楚。", "explanation": "这里应该用〈流畅〉。勇敢形容人敢去做，朗读的顺畅要用流畅。"}, {"text": "这条路很勇敢，弯弯曲曲很长。", "explanation": "这里应该用〈崎岖〉。勇敢形容人敢去做，路面的不平要用崎岖。"}, {"text": "这顿饭很勇敢，有鱼有肉。", "explanation": "这里应该用〈丰盛〉。勇敢形容人敢去做，饭菜的品种多要用丰盛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过训练，他慢慢勇敢下来了。", "corrected_sentence": "经过训练，他慢慢勇敢起来了。", "error_description": "错误在补语：“勇敢”后面应接“起来”，表示逐渐变得有胆量；“下来”不能接在“勇敢”后面。正确形式：勇敢起来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在危险时勇敢的站了出来。", "corrected_sentence": "他在危险时勇敢地站了出来。", "error_description": "错误形式：“勇敢”作状语修饰动词“站”时，应用“地”，却写成了“的”。正确形式：应写作“勇敢地站了出来”。“的”用来修饰名词，不用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39841, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确：“怯懦”与“勇敢”构成反义，指胆小、不敢面对危险，与本义相反。"}, {"text": "聪明", "is_correct": false, "explanation": "与“勇敢”无反义关系，“聪明”指智力好，不指胆量。"}, {"text": "安静", "is_correct": false, "explanation": "与“勇敢”无反义关系，“安静”指没有声音或不躁动，不指胆量。"}, {"text": "结实", "is_correct": false, "explanation": "与“勇敢”无反义关系，“结实”指身体强壮或物体牢固。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确：“怯懦”与“勇敢”构成反义，指胆小、不敢面对危险，与本义相反。", "聪明": "与“勇敢”无反义关系，“聪明”指智力好，不指胆量。", "安静": "与“勇敢”无反义关系，“安静”指没有声音或不躁动，不指胆量。", "结实": "与“勇敢”无反义关系，“结实”指身体强壮或物体牢固。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39841, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确：“怯懦”与“勇敢”构成反义，指胆小、不敢面对危险，与本义相反。"}, {"text": "整齐", "is_correct": false, "explanation": "与“勇敢”无反义关系，“整齐”指排列有序。"}, {"text": "灵活", "is_correct": false, "explanation": "与“勇敢”无反义关系，“灵活”指动作敏捷或变通。"}, {"text": "苦涩", "is_correct": false, "explanation": "与“勇敢”无反义关系，“苦涩”指味道或心情不好。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确：“怯懦”与“勇敢”构成反义，指胆小、不敢面对危险，与本义相反。", "整齐": "与“勇敢”无反义关系，“整齐”指排列有序。", "灵活": "与“勇敢”无反义关系，“灵活”指动作敏捷或变通。", "苦涩": "与“勇敢”无反义关系，“苦涩”指味道或心情不好。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39841, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指不怕危险和困难，有胆量，能坚持做正确的事。", "primary_collocate": null, "pronunciation": "yǒng gǎn", "ipa": "jʊŋ˨˩˦ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个玩具帮助他们想象自己是勇敢的骑士，在广阔的土地上奔驰。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他勇敢地说出了自己的错误。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员勇敢地冲进了火里。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对困难，我们要勇敢一点。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩很勇敢，敢说真话。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个勇敢的人，总是帮助别人。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李勇敢地站出来，保护了同学。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然害怕，她还是勇敢地走了过去。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇敢不是不害怕，而是继续做对的事。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸他勇敢，因为他没有放弃。", "target_word": "勇敢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勇敢地", "label": "状语形式"}, {"form": "勇敢者", "label": "复合"}], "register": "中性", "sense_fingerprint": "勇敢：不怕危险和困难、有胆量并坚持做对的事（勇敢地面对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bad1194d-b4c2-4591-8424-556e394eac48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39841, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勇敢", "is_correct": true, "explanation": "正确：“勇敢的骑士”修饰“骑士”，指有胆量、不怕危险，符合句意。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”与后面的“广阔的土地”相反，句意矛盾。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容物体的质地，不能用来形容骑士。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能用来形容骑士。"}], "explanations": {"勇敢": "正确：“勇敢的骑士”修饰“骑士”，指有胆量、不怕危险，符合句意。", "狭窄": "语义：“狭窄”与后面的“广阔的土地”相反，句意矛盾。", "柔软": "搭配：“柔软”形容物体的质地，不能用来形容骑士。", "清澈": "搭配：“清澈”形容水或眼神，不能用来形容骑士。"}, "sentence_index": 0, "correct_answer": "勇敢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很勇敢，坐上去很稳当。", "explanation": "这里应该用〈稳当〉。勇敢形容人有胆量、能坚持做正确的事，椅子的稳固要用稳当。"}, {"text": "他对客人很勇敢，总是笑着迎接。", "explanation": "这里应该用〈热情〉。勇敢指不怕危险、有胆量，对人的友好态度要用热情。"}, {"text": "他写作业很勇敢，每道题都仔细检查。", "explanation": "这里应该用〈认真〉。勇敢指不怕危险、有胆量，做事专心、不马虎要用认真。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勇敢", "is_correct": true, "explanation": "正确：“勇敢地站出来”修饰动作，表示不怕危险地站出来，符合句意。"}, {"text": "懒洋洋", "is_correct": false, "explanation": "语义：“懒洋洋地站出来”与“保护同学”的主动、紧急行动矛盾。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠地站出来”的态度与“保护同学”的关心矛盾。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”形容空气或物体，不能修饰站出来的动作。"}], "explanations": {"勇敢": "正确：“勇敢地站出来”修饰动作，表示不怕危险地站出来，符合句意。", "懒洋洋": "语义：“懒洋洋地站出来”与“保护同学”的主动、紧急行动矛盾。", "冷漠": "语义：“冷漠地站出来”的态度与“保护同学”的关心矛盾。", "干燥": "搭配：“干燥”形容空气或物体，不能修饰站出来的动作。"}, "sentence_index": 6, "correct_answer": "勇敢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子很勇敢，能承受很大的重量。", "explanation": "这里应该用〈坚韧〉。勇敢形容人不怕危险，绳子的坚韧要用坚韧。"}, {"text": "他的口才很勇敢，能说服所有人。", "explanation": "这里应该用〈流利〉。勇敢形容人不怕危险，说话的顺畅要用流利。"}, {"text": "这座老房子很勇敢，墙壁很平整。", "explanation": "这里应该用〈平整〉。勇敢形容人有胆量、能坚持做正确的事，墙壁的平坦要用平整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员勇敢得救出了老人。", "corrected_sentence": "消防员勇敢地救出了老人。", "error_description": "错误在修饰标记：“勇敢”修饰动词“救出”时要用“地”，不能用“得”；“得”用来引出补语。正确形式：勇敢地救出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他遇到危险时非常勇敢地。", "corrected_sentence": "他遇到危险时非常勇敢。", "error_description": "错误在词尾：“勇敢”作谓语时不能加“地”，“地”只用于修饰动词。正确形式：非常勇敢。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bb6c90-b587-4158-8bcf-8f8fb63305be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
