INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "骑士是古代欧洲骑在马上、穿着盔甲、为领主服务的战士。", "primary_collocate": null, "pronunciation": "qí shì", "ipa": "tɕʰi˧˥ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这个玩具帮助他们想象自己是勇敢的骑士，在广阔的土地上奔驰。", "target_word": "骑士", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "中世纪的欧洲骑士要保护国王和城堡。", "target_word": "骑士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位骑士穿着重重的盔甲走进城堡。", "target_word": "骑士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧洲的骑士要听领主的话。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑士的盔甲和剑都很重。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻的骑士向领主行礼。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代欧洲的骑士要先学会骑马。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位骑士为领主打了很多仗。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里有一套欧洲骑士的盔甲。", "target_word": "骑士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑士跪在国王面前，保证忠于领主。", "target_word": "骑士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "骑士精神", "label": "复合"}, {"form": "騎士", "label": "繁体"}], "register": "中性", "sense_fingerprint": "古代欧洲穿盔甲、为领主服务的战士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42917911-9350-48ef-8d24-179b3d6d9c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士指古代欧洲骑马、穿盔甲、为领主服务的战士。"}, {"text": "其实", "is_correct": false, "explanation": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是「其实」（实际上）。"}, {"text": "气势", "is_correct": false, "explanation": "第一个音节 qì（第四声）与 qí（第二声）声调不同，意思是「气势」（气派与力量）。"}, {"text": "启示", "is_correct": false, "explanation": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启示」（引人领悟的道理）。"}, {"text": "情势", "is_correct": false, "explanation": "第一个音节 qíng 比 qí 多了 ng 韵尾，意思是「情势」（情况和形势）。"}, {"text": "亲事", "is_correct": false, "explanation": "第一个音节 qīn（第一声）与 qí 的韵母和声调都不同，意思是「亲事」（婚事）。"}], "explanations": {"骑士": "正确：骑士指古代欧洲骑马、穿盔甲、为领主服务的战士。", "其实": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是「其实」（实际上）。", "气势": "第一个音节 qì（第四声）与 qí（第二声）声调不同，意思是「气势」（气派与力量）。", "启示": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启示」（引人领悟的道理）。", "情势": "第一个音节 qíng 比 qí 多了 ng 韵尾，意思是「情势」（情况和形势）。", "亲事": "第一个音节 qīn（第一声）与 qí 的韵母和声调都不同，意思是「亲事」（婚事）。"}, "sentence_index": null, "correct_answer": "骑士"}, "level_3": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士指骑马穿盔甲的战士，符合「勇敢」与「在土地上奔驰」的想象。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与「在广阔的土地上奔驰」的想象场景不相符，句子不通。"}, {"text": "花朵", "is_correct": false, "explanation": "体貌：花朵没有能奔驰的身体，「奔驰」的主体不能是花。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：「勇敢」修饰能行动的人，不能修饰教室。"}], "explanations": {"骑士": "正确：骑士指骑马穿盔甲的战士，符合「勇敢」与「在土地上奔驰」的想象。", "厨师": "语义：厨师与「在广阔的土地上奔驰」的想象场景不相符，句子不通。", "花朵": "体貌：花朵没有能奔驰的身体，「奔驰」的主体不能是花。", "教室": "搭配：「勇敢」修饰能行动的人，不能修饰教室。"}, "sentence_index": 0, "correct_answer": "骑士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位骑士每天在工厂里组装汽车。", "explanation": "这里应该用〈工人〉。骑士指古代为领主打仗的战士，在工厂组装汽车的人要用工人。"}, {"text": "这位骑士每天在厨房里炒菜。", "explanation": "这里应该用〈厨师〉。骑士指古代为领主打仗的战士，在厨房里炒菜的人要用厨师。"}, {"text": "这位骑士每天开车送孩子上学。", "explanation": "这里应该用〈司机〉。骑士指骑马的战士，开车送孩子上学的人要用司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士指古代欧洲骑马、穿盔甲、为领主服务的战士。"}, {"text": "骑师", "is_correct": false, "explanation": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是「骑师」（职业赛马骑手）。"}, {"text": "启事", "is_correct": false, "explanation": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启事」（公开的通知文告）。"}, {"text": "奇思", "is_correct": false, "explanation": "第二个音节 sī（第一声）与 shì（第四声）声母和声调都不同，意思是「奇思」（新奇的想法）。"}, {"text": "集市", "is_correct": false, "explanation": "第一个音节 jí（第二声）与 qí 声母不同（j 与 q），意思是「集市」（定期交易的市场）。"}, {"text": "喜事", "is_correct": false, "explanation": "第一个音节 xǐ（第三声）与 qí 声母和声调都不同，意思是「喜事」（值得高兴的事）。"}], "explanations": {"骑士": "正确：骑士指古代欧洲骑马、穿盔甲、为领主服务的战士。", "骑师": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是「骑师」（职业赛马骑手）。", "启事": "第一个音节 qǐ（第三声）与 qí（第二声）声调不同，意思是「启事」（公开的通知文告）。", "奇思": "第二个音节 sī（第一声）与 shì（第四声）声母和声调都不同，意思是「奇思」（新奇的想法）。", "集市": "第一个音节 jí（第二声）与 qí 声母不同（j 与 q），意思是「集市」（定期交易的市场）。", "喜事": "第一个音节 xǐ（第三声）与 qí 声母和声调都不同，意思是「喜事」（值得高兴的事）。"}, "sentence_index": null, "correct_answer": "骑士"}, "level_3": {"options": [{"text": "骑士", "is_correct": true, "explanation": "正确：骑士是古代欧洲的战士，「学会骑马」正是他们的训练内容。"}, {"text": "钢琴家", "is_correct": false, "explanation": "语义：钢琴是近代乐器，与「古代欧洲」的时代背景不符。"}, {"text": "小猫", "is_correct": false, "explanation": "体貌：小猫的身体不能骑马，与「学会骑马」的主体不符。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：「学会骑马」的主体应是人，不能说花园学会骑马。"}], "explanations": {"骑士": "正确：骑士是古代欧洲的战士，「学会骑马」正是他们的训练内容。", "钢琴家": "语义：钢琴是近代乐器，与「古代欧洲」的时代背景不符。", "小猫": "体貌：小猫的身体不能骑马，与「学会骑马」的主体不符。", "花园": "搭配：「学会骑马」的主体应是人，不能说花园学会骑马。"}, "sentence_index": 6, "correct_answer": "骑士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位骑士在画布上画了一幅风景。", "explanation": "这里应该用〈画家〉。骑士指古代为领主打仗的战士，在画布上画风景的人要用画家。"}, {"text": "赛马场上，那位骑士紧紧握着缰绳，冲过了终点。", "explanation": "这里应该用〈骑手〉。骑士指古代为领主服务的战士，参加赛马的人要用骑手。"}, {"text": "这位骑士每天给病人打针。", "explanation": "这里应该用〈护士〉。骑士指古代为领主打仗的战士，给病人打针的人要用护士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只骑士披着沉重的盔甲走进城堡。", "corrected_sentence": "那位骑士披着沉重的盔甲走进城堡。", "error_description": "「骑士」指人，量词应用「位」，不能用「只」。错误在「那只」，应改为「那位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个位骑士在宫廷里向国王行礼。", "corrected_sentence": "那位骑士在宫廷里向国王行礼。", "error_description": "错误：“那个”与“位”两个量词重复使用，同一名词只用一个量词。正确应为“那位骑士”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭窄", "is_correct": true, "explanation": "反义：「狭窄」指场地或空间窄小，与「很大很宽」相对。"}, {"text": "灵活", "is_correct": false, "explanation": "「灵活」形容动作或思路敏捷，与场地大小无关，不是反义词。"}, {"text": "柔和", "is_correct": false, "explanation": "「柔和」形容光线、声音或态度温和，与场地大小无关，不是反义词。"}, {"text": "缓慢", "is_correct": false, "explanation": "「缓慢」形容速度慢，与场地大小无关，不是反义词。"}], "correct_answer": "狭窄", "explanations": {"狭窄": "反义：「狭窄」指场地或空间窄小，与「很大很宽」相对。", "灵活": "「灵活」形容动作或思路敏捷，与场地大小无关，不是反义词。", "柔和": "「柔和」形容光线、声音或态度温和，与场地大小无关，不是反义词。", "缓慢": "「缓慢」形容速度慢，与场地大小无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
