INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很大很宽的地方。", "primary_collocate": null, "pronunciation": "guǎng kuò", "ipa": "kwɑŋ˨˩˦ kʰwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们喜欢在广阔的操场上玩。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个广场很广阔，能站几万人。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想去外面看看广阔的世界。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座广阔的牧场可以养很多牛羊。", "target_word": "广阔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有广阔的公园和绿地。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广阔的空间让人觉得很自由。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山后是一片广阔的地方，没有一间房子。", "target_word": "广阔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在广阔的雪地中间，他觉得自己很小。", "target_word": "广阔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么广阔的地方，可以建一个大公园。", "target_word": "广阔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跑进广阔的田野里玩。", "target_word": "广阔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "广阔无边", "label": "复合"}, {"form": "广阔天地", "label": "复合"}, {"form": "廣闊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "场地、空间很大很宽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42917911-9350-48ef-8d24-179b3d6d9c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广阔", "is_correct": true, "explanation": "正确：广阔指场地很大很宽，与「在操场上玩」的场景相合。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：陡峭说地势斜而高，与平坦的操场不符。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：「聪明」修饰人或头脑，不能修饰操场。"}, {"text": "低矮", "is_correct": false, "explanation": "体貌：低矮形容物体外形矮小，操场是大面积场地，不能这样形容。"}], "explanations": {"广阔": "正确：广阔指场地很大很宽，与「在操场上玩」的场景相合。", "陡峭": "语义：陡峭说地势斜而高，与平坦的操场不符。", "聪明": "搭配：「聪明」修饰人或头脑，不能修饰操场。", "低矮": "体貌：低矮形容物体外形矮小，操场是大面积场地，不能这样形容。"}, "sentence_index": 0, "correct_answer": "广阔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的价格很广阔，大家都买不起。", "explanation": "这里应该用〈昂贵〉。广阔形容很大很宽的场地，价格的高低要用昂贵。"}, {"text": "他的力气很广阔，一个人能拉动一辆车。", "explanation": "这里应该用〈强大〉。广阔形容很大很宽的场地，力气的大小要用强大。"}, {"text": "这一小块饼很广阔，我们一口就吃完了。", "explanation": "这里应该用〈小〉。广阔指很大很宽的地方，一小块饼不能用广阔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广阔", "is_correct": true, "explanation": "正确：广阔指很大很宽，与「没有一间房子」的空旷场景相符。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：拥挤说人或物太多，与「没有一间房子」的空旷场景矛盾。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：繁华指商业兴旺、建筑众多，与「没有一间房子」矛盾。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：「高耸」多修饰山峰或建筑，说「一片高耸的地方」不通。"}], "explanations": {"广阔": "正确：广阔指很大很宽，与「没有一间房子」的空旷场景相符。", "拥挤": "语义：拥挤说人或物太多，与「没有一间房子」的空旷场景矛盾。", "繁华": "语义：繁华指商业兴旺、建筑众多，与「没有一间房子」矛盾。", "高耸": "搭配：「高耸」多修饰山峰或建筑，说「一片高耸的地方」不通。"}, "sentence_index": 6, "correct_answer": "广阔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台大型机器很广阔，占满了整个车间。", "explanation": "这里应该用〈庞大〉。广阔形容很大很宽的场地，机器这样的实体要用庞大。"}, {"text": "这次会议的时间很广阔，开了一整天。", "explanation": "这里应该用〈漫长〉。广阔形容很大很宽的场地，时间的长短要用漫长。"}, {"text": "这张纸的字很广阔，写得满满的。", "explanation": "这里应该用〈大〉。广阔指很大很宽的场地，字的大小要用大，不用广阔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片田野广阔地很，孩子们可以尽情奔跑。", "corrected_sentence": "这片田野广阔得很，孩子们可以尽情奔跑。", "error_description": "「广阔得很」是形容词加补语结构，要用「得」，不能用「地」。错误在「广阔地很」，应改为「广阔得很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在广阔地场地上踢球。", "corrected_sentence": "孩子们在广阔的场地上踢球。", "error_description": "「广阔」作定语应用「的」，「地」用于动词前修饰动作。错误在「广阔地场地」，应改为「广阔的场地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
