INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39846, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39846, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跑得很快", "primary_collocate": null, "pronunciation": "bēn chí", "ipa": "pən˥ ʈʂʰʅ˧˥", "syllable_count": 2, "sentences": [{"text": "小狗在公园里欢快地奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动员在跑道上奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在海边的沙滩上奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "羚羊在草原上奔驰，躲开了狮子。", "target_word": "奔驰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课了，孩子们奔驰着冲向操场。", "target_word": "奔驰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在球场上奔驰，一直追着球。", "target_word": "奔驰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎豹奔驰起来，速度非常快。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在田野里奔驰，笑声不断。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向终点奔驰，别人都落在后面。", "target_word": "奔驰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鹿在草地上奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "奔驰着", "label": "体标"}, {"form": "奔驰了", "label": "体标"}, {"form": "奔驰过", "label": "体标"}, {"form": "奔馳", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或动物飞快地跑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42917911-9350-48ef-8d24-179b3d6d9c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奔驰", "is_correct": true, "explanation": "“奔驰”指人或动物飞快地跑，与小狗在公园里欢快奔跑的描写相符。"}, {"text": "发言", "is_correct": false, "explanation": "语义：“发言”需要能说话的人，小狗不能发言。"}, {"text": "写作", "is_correct": false, "explanation": "语义：“写作”指用文字创作，小狗不会写作，与句子语境无关。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”是及物动词，需要被修的东西作宾语，句中没有这样的宾语。"}], "explanations": {"奔驰": "“奔驰”指人或动物飞快地跑，与小狗在公园里欢快奔跑的描写相符。", "发言": "语义：“发言”需要能说话的人，小狗不能发言。", "写作": "语义：“写作”指用文字创作，小狗不会写作，与句子语境无关。", "修理": "配价：“修理”是及物动词，需要被修的东西作宾语，句中没有这样的宾语。"}, "sentence_index": 0, "correct_answer": "奔驰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏台灯在书桌上奔驰。", "explanation": "这里应该用〈摆〉。“奔驰”指人或动物跑得很快，台灯不能自己移动，要说“摆”。"}, {"text": "他慢慢地奔驰到教室门口。", "explanation": "这里应该用〈走〉。“奔驰”指跑得很快，与“慢慢地”的缓慢意思矛盾；慢慢移动要说“走”。"}, {"text": "他在床上奔驰，整天都没起来。", "explanation": "这里应该用〈躺〉。「奔驰」指跑得很快，与整天卧床不起的状态矛盾；卧床要说「躺」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲话", "is_correct": false, "explanation": "语义：猎豹不会讲话，句子描写的是猎豹跑得很快。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”与“速度非常快”的描写相矛盾，句子描写的是动作而非情绪。"}, {"text": "编织", "is_correct": false, "explanation": "配价：“编织”是及物动词，需要编织物作宾语，句中没有这样的宾语。"}, {"text": "奔驰", "is_correct": true, "explanation": "“奔驰”指飞快地跑，与猎豹奔驰起来、速度非常快的描写相符。"}], "explanations": {"讲话": "语义：猎豹不会讲话，句子描写的是猎豹跑得很快。", "哭泣": "语义：“哭泣”与“速度非常快”的描写相矛盾，句子描写的是动作而非情绪。", "编织": "配价：“编织”是及物动词，需要编织物作宾语，句中没有这样的宾语。", "奔驰": "“奔驰”指飞快地跑，与猎豹奔驰起来、速度非常快的描写相符。"}, "sentence_index": 6, "correct_answer": "奔驰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头在山坡上奔驰。", "explanation": "这里应该用〈滚〉。“奔驰”指人或动物快速跑动，石头只能滚落，要说“滚”。"}, {"text": "这只冰箱在厨房里奔驰。", "explanation": "这里应该用〈摆〉。“奔驰”指人或动物快速跑动，冰箱不能自己移动，要说“摆”。"}, {"text": "这个小孩站着奔驰，一动不动。", "explanation": "这里应该用〈静立〉。“奔驰”指跑得很快，与“一动不动”的静止矛盾；静止要说“静立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只小猫在花园里很奔驰。", "corrected_sentence": "那只小猫在花园里奔驰。", "error_description": "错误形式：“很奔驰”。正确形式：“奔驰”前不加“很”。“奔驰”是动词，不能用程度副词“很”修饰，应说“在花园里奔驰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她们在田野上奔驰了着。", "corrected_sentence": "她们在田野上奔驰着。", "error_description": "错误形式：“奔驰了着”，动词后同时带“了”和“着”两个体标。正确形式：“奔驰着”。表示动作正在持续，只用动态助词“着”即可，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
