INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容马或车等快速奔跑", "primary_collocate": null, "pronunciation": "bēn chí", "ipa": "pən˥ ʈʂʰʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这个玩具帮助他们想象自己是勇敢的骑士，在广阔的土地上奔驰。", "target_word": "奔驰", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "一匹白马在草原上奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车在铁路上飞快地奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骏马奔驰着，向远方跑去。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车在高速公路上奔驰了一天。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "马群在草地上奔驰，声音很大。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "列车奔驰过一座又一座大山。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黑色的马奔驰在雪地上。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一辆红色的车在公路上奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑着马向前奔驰。", "target_word": "奔驰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "奔驰着", "label": "体标"}, {"form": "奔驰了", "label": "体标"}, {"form": "奔驰过", "label": "体标"}, {"form": "奔馳", "label": "繁体"}], "register": "中性", "sense_fingerprint": "马或车辆快速奔跑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42917911-9350-48ef-8d24-179b3d6d9c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打印", "is_correct": false, "explanation": "语义：“打印”要以纸张或设备为对象，不能在广阔的土地上进行。"}, {"text": "奔驰", "is_correct": true, "explanation": "“奔驰”指马或车快速奔跑，与骑士在广阔土地上奔驰的情境相符。"}, {"text": "缝补", "is_correct": false, "explanation": "配价：“缝补”需要衣物之类的受事宾语，句中没有可缝补的对象。"}, {"text": "下载", "is_correct": false, "explanation": "语义：“下载”指从网络获取文件，与广阔土地和想象骑士的语境无关。"}], "explanations": {"打印": "语义：“打印”要以纸张或设备为对象，不能在广阔的土地上进行。", "奔驰": "“奔驰”指马或车快速奔跑，与骑士在广阔土地上奔驰的情境相符。", "缝补": "配价：“缝补”需要衣物之类的受事宾语，句中没有可缝补的对象。", "下载": "语义：“下载”指从网络获取文件，与广阔土地和想象骑士的语境无关。"}, "sentence_index": 0, "correct_answer": "奔驰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子在教室里奔驰。", "explanation": "这里应该用〈挪动〉。「奔驰」指马或车快速奔跑，椅子不能自己跑动，要说「挪动」。"}, {"text": "这匹老马慢慢地奔驰到草场上。", "explanation": "这里应该用〈踱〉。“奔驰”指快速奔跑，与“慢慢地”的缓慢意思矛盾；缓慢走动要说“踱”。"}, {"text": "这只蜗牛在草地上奔驰。", "explanation": "这里应该用〈爬〉。“奔驰”指快速奔跑，蜗牛行动极慢，要说“爬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉睡", "is_correct": false, "explanation": "语义：列车不会沉睡，句子描写的是快速经过群山。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：列车不会歌唱，句子描写的是快速经过群山。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”是不及物动词，不能带“大山”作宾语来表示经过。"}, {"text": "奔驰", "is_correct": true, "explanation": "“奔驰”指快速移动，与列车飞快经过一座又一座大山的语境相符。"}], "explanations": {"沉睡": "语义：列车不会沉睡，句子描写的是快速经过群山。", "歌唱": "语义：列车不会歌唱，句子描写的是快速经过群山。", "生长": "配价：“生长”是不及物动词，不能带“大山”作宾语来表示经过。", "奔驰": "“奔驰”指快速移动，与列车飞快经过一座又一座大山的语境相符。"}, "sentence_index": 6, "correct_answer": "奔驰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子在屋子里奔驰。", "explanation": "这里应该用〈挪动〉。“奔驰”指马、车等快速跑动，桌子不能自己移动，要说“挪动”。"}, {"text": "这块石头从山坡上奔驰下来。", "explanation": "这里应该用〈滚〉。“奔驰”指马、车等快速跑动，石头只能滚落，要说“滚”。"}, {"text": "这匹马站在草地上奔驰，一动也不动。", "explanation": "这里应该用〈停留〉。“奔驰”指快速跑动，与静止不动的意思矛盾；静止要说“停留”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那匹白马在草原上很奔驰。", "corrected_sentence": "那匹白马在草原上奔驰。", "error_description": "错误形式：“很奔驰”。正确形式：“奔驰”前不加“很”。“奔驰”是动词，不能像形容词一样用程度副词“很”修饰，应说“在草原上奔驰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那群马在雪地上奔驰了着。", "corrected_sentence": "那群马在雪地上奔驰着。", "error_description": "错误形式：“奔驰了着”，动词后同时带“了”和“着”两个体标。正确形式：“奔驰着”。表示动作正在持续，只用动态助词“着”即可，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同之处", "is_correct": true, "explanation": "“不同之处”指两者不一样的地方，与“相似之处”相对。"}, {"text": "优点", "is_correct": false, "explanation": "“优点”指好的方面，与“相似之处”没有反义关系。"}, {"text": "原因", "is_correct": false, "explanation": "“原因”指事情发生的缘由，与“相似之处”没有反义关系。"}, {"text": "办法", "is_correct": false, "explanation": "“办法”指解决问题的方式，与“相似之处”没有反义关系。"}], "correct_answer": "不同之处", "explanations": {"不同之处": "“不同之处”指两者不一样的地方，与“相似之处”相对。", "优点": "“优点”指好的方面，与“相似之处”没有反义关系。", "原因": "“原因”指事情发生的缘由，与“相似之处”没有反义关系。", "办法": "“办法”指解决问题的方式，与“相似之处”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
