INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指两个或更多事物之间相同或类似的部分。", "primary_collocate": null, "pronunciation": "xiāng sì zhī chù", "ipa": "ɕjɑŋ˥ sɨ˥˩ ʈʂɨ˥ ʈʂʰu˥˩", "syllable_count": 4, "sentences": [{"text": "在古罗马，孩子们的日常生活和今天的孩子有些不同，但也有相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这两本书有很多相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国菜和意大利菜有哪些相似之处？", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹俩的性格有一个相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说这两个城市的相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的相似之处是都爱运动。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到这两张画的相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语和日语在文字上有相似之处。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种动物的相似之处不多。", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较两个故事，你发现了哪些相似之处？", "target_word": "相似之处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "多个事物之间相同或类似的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0e16fe-f24e-4396-aacb-44762e195d23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相似之处", "is_correct": true, "explanation": "“相似之处”指两者相同或类似的部分，与前句“有些不同”形成转折，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古罗马没有手机，与句首“在古罗马”的时代背景冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：古罗马没有汽车，与“在古罗马”的背景不符。"}, {"text": "时代", "is_correct": false, "explanation": "搭配：“有”后不能直接带“时代”作宾语，此处说不通。"}], "explanations": {"相似之处": "“相似之处”指两者相同或类似的部分，与前句“有些不同”形成转折，符合句意。", "手机": "语义：古罗马没有手机，与句首“在古罗马”的时代背景冲突。", "汽车": "语义：古罗马没有汽车，与“在古罗马”的背景不符。", "时代": "搭配：“有”后不能直接带“时代”作宾语，此处说不通。"}, "sentence_index": 0, "correct_answer": "相似之处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姐妹俩的性格有一条相似之处。", "explanation": "这里应该用〈个〉。“之处”前的数量词一般用“个”或“些”，“条”用于细长或成条的东西，不能修饰“之处”。"}, {"text": "姐妹俩的性格有一根相似之处。", "explanation": "这里应该用〈个〉。“根”用于细长的物体，不能用来修饰“之处”。"}, {"text": "姐妹俩的性格有一张相似之处。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等，不能用来修饰“之处”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相似之处", "is_correct": true, "explanation": "“相似之处”与“找不到”搭配，指两张画之间相同或类似的部分，符合句意。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：画作没有音乐，与句中的“这两张画”对象不符。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：画作没有温度，不能说“这两张画的温度”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不能说画的体重。"}], "explanations": {"相似之处": "“相似之处”与“找不到”搭配，指两张画之间相同或类似的部分，符合句意。", "音乐": "语义：画作没有音乐，与句中的“这两张画”对象不符。", "温度": "搭配：画作没有温度，不能说“这两张画的温度”。", "体重": "搭配：“体重”用于人或动物，不能说画的体重。"}, "sentence_index": 6, "correct_answer": "相似之处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个故事的相似之处是结局不同。", "explanation": "这里应该用〈区别〉。“相似之处”指相同或类似的部分，后面接“结局不同”，前后自相矛盾，应说“区别”。"}, {"text": "两所学校的相似之处是校风不同。", "explanation": "这里应该用〈差异〉。“相似之处”后接“校风不同”，前后矛盾，应说“差异”。"}, {"text": "这两种茶的相似之处是口味不同。", "explanation": "这里应该用〈差别〉。“相似之处”后接“口味不同”，前后矛盾，应说“差别”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两部电影有一条相似之处：主角都是老师。", "corrected_sentence": "这两部电影有一个相似之处：主角都是老师。", "error_description": "量词错误：“相似之处”前应用量词“个”，说“一个相似之处”，不说“一条相似之处”（“条”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两所学校很多相似之处。", "corrected_sentence": "这两所学校有很多相似之处。", "error_description": "漏掉动词“有”：表示存在的“有”不能省，应说“有很多相似之处”，不说“很多相似之处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
