INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男孩就是小男孩，是家里的小男生。", "primary_collocate": null, "pronunciation": "nán hái", "ipa": "nan˧˥ xaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我邻居的男孩很有礼貌。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩喜欢玩汽车玩具。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生了一个可爱的男孩。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男孩正在画画。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里有五个男孩。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩的头发很短。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见一个男孩在哭。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男孩是我同学的弟弟。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩过生日，朋友送他一本书。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩每天骑车去上学。", "target_word": "男孩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "男孩子", "label": "复合"}], "register": "中性", "sense_fingerprint": "家里的小男生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0e16fe-f24e-4396-aacb-44762e195d23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男孩", "is_correct": true, "explanation": "男孩：指家里的小男生，与“很有礼貌”的评价相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有礼貌可言，与“有礼貌”不能搭配。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是人，不能说“很有礼貌”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不能说“很有礼貌”。"}], "explanations": {"男孩": "男孩：指家里的小男生，与“很有礼貌”的评价相符。", "石头": "语义：石头没有礼貌可言，与“有礼貌”不能搭配。", "电脑": "语义：电脑不是人，不能说“很有礼貌”。", "桌子": "语义：桌子不是人，不能说“很有礼貌”。"}, "sentence_index": 0, "correct_answer": "男孩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个男孩每个月都要还房贷，压力很大。", "explanation": "这里应该用〈男人〉。男孩指小男孩，不能用来指每个月还房贷的成年男子。"}, {"text": "我看见那个男孩的丈夫在画画。", "explanation": "这里应该用〈男人〉。男孩指小男孩，不能用来指已经结婚的成年男子。"}, {"text": "那位男孩已经退休，每天去公园散步。", "explanation": "这里应该用〈老人〉。男孩指小男孩，不能用来指已经退休的成年男子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男孩", "is_correct": true, "explanation": "男孩：指男性儿童，与“我看见……在哭”的描述相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会哭，不能作“在哭”的主语。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气没有哭的能力，不能作“在哭”的主语。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子没有哭的能力，不能作“在哭”的主语。"}], "explanations": {"男孩": "男孩：指男性儿童，与“我看见……在哭”的描述相符。", "太阳": "语义：太阳不会哭，不能作“在哭”的主语。", "空气": "语义：空气没有哭的能力，不能作“在哭”的主语。", "椅子": "语义：椅子没有哭的能力，不能作“在哭”的主语。"}, "sentence_index": 6, "correct_answer": "男孩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位男孩在公司里管理三百名员工。", "explanation": "这里应该用〈经理〉。男孩指儿童，不能用来指在公司里管理三百名员工的成年人。"}, {"text": "这位男孩每天开车送我上班。", "explanation": "这里应该用〈司机〉。男孩指儿童，不能用来指开车送人的司机。"}, {"text": "这位男孩每周都要去医院为病人做手术。", "explanation": "这里应该用〈外科医生〉。男孩指儿童，不能用来指给病人做手术的成年医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有两只男孩。", "corrected_sentence": "我家有两个男孩。", "error_description": "“男孩”指人，量词应用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们学校有很多男孩们在踢球。", "corrected_sentence": "他们学校有很多男孩在踢球。", "error_description": "“很多”是数量词，不能与“们”同用，应说“很多男孩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
