INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39854, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39854, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "读写就是看书和写字。", "primary_collocate": null, "pronunciation": "dú xiě", "ipa": "tu˧˥ ɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子们在教室里安静地读写。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都读写一个小时。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶不会读写，只会说话。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先学听说，再学读写。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲人也可以读写。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在图书馆读写了一下午。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子四岁就会读写了。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家安静，现在开始读写。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边听音乐，一边读写。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外，我每天都要读写中文。", "target_word": "读写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "读写能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "看书和写字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0e16fe-f24e-4396-aacb-44762e195d23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "读写", "is_correct": true, "explanation": "读写：指看书和写字的动作，与“安静地”的描写相符。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：在教室里安静地跑步与“安静”的情境矛盾。"}, {"text": "咆哮", "is_correct": false, "explanation": "语域：“咆哮”是激烈的书面化词语，与“安静地”的描写不协调。"}, {"text": "吵架", "is_correct": false, "explanation": "搭配：“安静地”不能修饰“吵架”，二者搭配不成立。"}], "explanations": {"读写": "读写：指看书和写字的动作，与“安静地”的描写相符。", "跑步": "语义：在教室里安静地跑步与“安静”的情境矛盾。", "咆哮": "语域：“咆哮”是激烈的书面化词语，与“安静地”的描写不协调。", "吵架": "搭配：“安静地”不能修饰“吵架”，二者搭配不成立。"}, "sentence_index": 0, "correct_answer": "读写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在班上读写课文，声音很清楚。", "explanation": "这里应该用〈朗读〉。读写指看书和写字，不涉及出声，不能用于说明“声音很清楚”。"}, {"text": "这本书的读写很好看。", "explanation": "这里应该用〈内容〉或〈文笔〉。读写指看书和写字的动作，不能用来形容书的内容或文字好不好看。"}, {"text": "妈妈每天读写衣服。", "explanation": "这里应该用〈洗〉。读写指看书和写字，不能用来指洗衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "读写", "is_correct": true, "explanation": "读写：指看书和写字，四岁就会做这件事，符合句意。"}, {"text": "开车", "is_correct": false, "explanation": "语义：四岁的孩子不会开车，与“四岁就会”的语境矛盾。"}, {"text": "长胡子", "is_correct": false, "explanation": "体貌：“长胡子”指成年男性的外貌特征，与四岁的孩子不符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚需要成年，四岁的孩子不能结婚，与“四岁就会”矛盾。"}], "explanations": {"读写": "读写：指看书和写字，四岁就会做这件事，符合句意。", "开车": "语义：四岁的孩子不会开车，与“四岁就会”的语境矛盾。", "长胡子": "体貌：“长胡子”指成年男性的外貌特征，与四岁的孩子不符。", "结婚": "语义：结婚需要成年，四岁的孩子不能结婚，与“四岁就会”矛盾。"}, "sentence_index": 6, "correct_answer": "读写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师要求我们每天读写教室。", "explanation": "这里应该用〈打扫〉。读写指看书和写字，不能用来指对教室的清洁动作。"}, {"text": "我每天读写锻炼身体。", "explanation": "这里应该用〈游泳〉。读写指看书和写字，不能用来锻炼身体。"}, {"text": "我每天读写汽车。", "explanation": "这里应该用〈修理〉。读写指看书和写字，不能用于对汽车的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天陪我读写了一个小时。", "corrected_sentence": "妈妈每天陪我读写一个小时。", "error_description": "“每天”表示习惯，“读写”后不能加“了”表示完成，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她读写地很快。", "corrected_sentence": "她读写得很快。", "error_description": "表示动作程度的补语要用“得”，不能用“地”，应说“读写得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
