INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39856, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5159cda2-c11f-4c39-a193-9c05d5e7fec4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "算术就是学习怎么算数，比如加法和减法。", "primary_collocate": null, "pronunciation": "suàn shù", "ipa": "suan˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "小明正在学习算术，今天学加法。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天晚上教我算术。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟刚开始学算术，还不会减法。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先学算术，再学别的数学。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学算术时，孩子可以用手指数数。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，学好算术要多练习。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天花半小时练算术。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏能帮孩子学算术。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用小石头教妹妹算术。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸买了一本书，帮我学算术。", "target_word": "算术", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "算術", "label": "繁体"}, {"form": "算术题", "label": "复合"}], "register": "中性", "sense_fingerprint": "算术：学习怎么算数，如加法和减法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc2fecc9-6265-49bd-9c21-bd45ff1a894c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39856, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "算术", "is_correct": true, "explanation": "正确：suàn shù，指学习怎么算数，如加法和减法。"}, {"text": "算是", "is_correct": false, "explanation": "算是（suàn shì）与算术（suàn shù）只有第二音节韵母不同（shì 与 shù），意思是“算作”。"}, {"text": "素数", "is_correct": false, "explanation": "素数（sù shù）与算术（suàn shù）第一音节少了 a 和韵尾 n，意思是质数。"}, {"text": "战术", "is_correct": false, "explanation": "战术（zhàn shù）与算术（suàn shù）第一音节声母不同（zh 与 s），意思是作战的方法。"}, {"text": "算书", "is_correct": false, "explanation": "算书（suàn shū）与算术（suàn shù）第一音节相同，第二音节只差声调（阴平与去声），意思是古代的数学书。"}], "explanations": {"算术": "正确：suàn shù，指学习怎么算数，如加法和减法。", "算是": "算是（suàn shì）与算术（suàn shù）只有第二音节韵母不同（shì 与 shù），意思是“算作”。", "素数": "素数（sù shù）与算术（suàn shù）第一音节少了 a 和韵尾 n，意思是质数。", "战术": "战术（zhàn shù）与算术（suàn shù）第一音节声母不同（zh 与 s），意思是作战的方法。", "算书": "算书（suàn shū）与算术（suàn shù）第一音节相同，第二音节只差声调（阴平与去声），意思是古代的数学书。"}, "sentence_index": null, "correct_answer": "算术"}, "level_3": {"options": [{"text": "算术", "is_correct": true, "explanation": "正确：“学习算术”与后半句“今天学加法”同属数学内容，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能作为学习的对象，与“学习……”不搭。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：绘画与后半句“今天学加法”属于不同内容，前后不一致。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不是可以学习的科目，“学习……”后不能接“体温”。"}], "explanations": {"算术": "正确：“学习算术”与后半句“今天学加法”同属数学内容，符合句意。", "天气": "搭配：“天气”不能作为学习的对象，与“学习……”不搭。", "绘画": "语义：绘画与后半句“今天学加法”属于不同内容，前后不一致。", "体温": "搭配：“体温”不是可以学习的科目，“学习……”后不能接“体温”。"}, "sentence_index": 0, "correct_answer": "算术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把算术装进了箱子里寄给了朋友。", "explanation": "这里应该用〈包裹〉。算术是学科名称，不是实物，不能装进箱子寄出。"}, {"text": "弟弟刚学会了一只算术。", "explanation": "这里应该用〈门〉。算术作为学科，量词用“门”；“只”多用于动物等，不用于学科。"}, {"text": "小明很快地算术完这十道题。", "explanation": "这里应该用〈算〉。算术是名词，不能当动词用，表示“做计算”要说“算”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5159cda2-c11f-4c39-a193-9c05d5e7fec4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "算术", "is_correct": true, "explanation": "正确：“练算术”指反复练习计算，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“练”的对象应是可以练习的技能，“空气”不能用“练”。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不是可以练习的技能，与“每天花半小时练”不合。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能练习，句意不通。"}], "explanations": {"算术": "正确：“练算术”指反复练习计算，符合句意。", "空气": "搭配：“练”的对象应是可以练习的技能，“空气”不能用“练”。", "星星": "语义：星星不是可以练习的技能，与“每天花半小时练”不合。", "月亮": "语义：月亮不能练习，句意不通。"}, "sentence_index": 6, "correct_answer": "算术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用算术买了一双鞋。", "explanation": "这里应该用〈钱〉。算术是学科，不能当作买东西的工具。"}, {"text": "这首歌的算术很好听。", "explanation": "这里应该用〈旋律〉。算术是学科名称，不能用来形容音乐，“好听”应搭配“旋律”。"}, {"text": "他每天唱算术练声。", "explanation": "这里应该用〈唱歌〉。算术是学科名称，不能作为“唱”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5159cda2-c11f-4c39-a193-9c05d5e7fec4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟去年开始学了一个算术。", "corrected_sentence": "弟弟去年开始学了一门算术。", "error_description": "错误：“一个算术”。应为“一门算术”。学科的量词用“门”，“个”不用于学科。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5159cda2-c11f-4c39-a193-9c05d5e7fec4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹已经学会了算术的。", "corrected_sentence": "妹妹已经学会了算术。", "error_description": "错误：句末多出“的”。应为“妹妹已经学会了算术。”。“学会了算术”后面不能直接加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5159cda2-c11f-4c39-a193-9c05d5e7fec4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
