INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜡板是涂有蜡层的平板，用尖笔刻写后可擦除重复使用，常用于教学或练习书写。", "primary_collocate": null, "pronunciation": "là bǎn", "ipa": "la˥˩ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "学校里，老师会用蜡板和笔来教他们写字。", "target_word": "蜡板", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "古代的学生在蜡板上练习写字。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用尖笔在蜡板上刻了几个字。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写错了，只要把蜡板擦干净就行。", "target_word": "蜡板", "complexity_tier": "T3", "furigana": "xiě cuò le, zhǐ yào bǎ là bǎn cā gānjìng jiù xíng.", "sentence_source": "generated"}, {"text": "这块蜡板上还留着昨天的字。", "target_word": "蜡板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个孩子发了一块蜡板。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜡板很软，用尖笔就能刻字。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里有一块古代的蜡板。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们把字写在蜡板上，再擦掉重写。", "target_word": "蜡板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜡板用完以后，可以重复使用。", "target_word": "蜡板", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "蠟板", "label": "繁体"}, {"form": "块", "label": "量词"}], "register": "中性", "sense_fingerprint": "蜡板：涂蜡的平板，用尖笔刻写，可擦除重复使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc2fecc9-6265-49bd-9c21-bd45ff1a894c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜡板", "is_correct": true, "explanation": "正确：蜡板是可以刻写、擦除的写字板，与“笔”配合用来写字，符合句意。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是写字用具，用它来教写字不合常理。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球不是书写工具，与句中“写字”的用途不合。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“用汽车和笔来教写字”不搭配，汽车不能作为书写工具。"}], "explanations": {"蜡板": "正确：蜡板是可以刻写、擦除的写字板，与“笔”配合用来写字，符合句意。", "饼干": "语义：饼干不是写字用具，用它来教写字不合常理。", "足球": "语义：足球不是书写工具，与句中“写字”的用途不合。", "汽车": "搭配：“用汽车和笔来教写字”不搭配，汽车不能作为书写工具。"}, "sentence_index": 0, "correct_answer": "蜡板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只蜡板。", "explanation": "这里应该用〈块〉。“只”多用于动物等，蜡板是平板，应用“块”。"}, {"text": "我用蜡板喝水。", "explanation": "这里应该用〈杯子〉。蜡板是写字用的平板，不能用来盛水喝。"}, {"text": "用蜡板烤面包。", "explanation": "这里应该用〈烤箱〉。蜡板不能加热，不能用来烤东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5159cda2-c11f-4c39-a193-9c05d5e7fec4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜡板", "is_correct": true, "explanation": "正确：蜡板表面是软蜡，尖笔可以在上面刻字，符合句意。"}, {"text": "石板", "is_correct": false, "explanation": "语义：石板很硬，与“很软”矛盾，尖笔刻不动。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁很硬，与“很软”矛盾。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：玻璃不适合用尖笔刻字，与“用尖笔就能刻字”的用法不搭配。"}], "explanations": {"蜡板": "正确：蜡板表面是软蜡，尖笔可以在上面刻字，符合句意。", "石板": "语义：石板很硬，与“很软”矛盾，尖笔刻不动。", "钢铁": "语义：钢铁很硬，与“很软”矛盾。", "玻璃": "搭配：玻璃不适合用尖笔刻字，与“用尖笔就能刻字”的用法不搭配。"}, "sentence_index": 6, "correct_answer": "蜡板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜡板用完以后，可以拿来煮汤。", "explanation": "这里应该用〈锅〉。蜡板是写字用的平板，不能用来煮汤。"}, {"text": "蜡板用完以后，可以拿来开车。", "explanation": "这里应该用〈汽车〉。蜡板不能用来驾驶，“开”只搭配汽车等交通工具。"}, {"text": "蜡板用完以后，要关机。", "explanation": "这里应该用〈电脑〉。蜡板没有开关机功能，“关机”只用于电脑等设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5159cda2-c11f-4c39-a193-9c05d5e7fec4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给每个学生发了一只蜡板。", "corrected_sentence": "老师给每个学生发了一块蜡板。", "error_description": "错误：“一只蜡板”。应为“一块蜡板”。“只”多用于动物等，蜡板是平板，应用“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5159cda2-c11f-4c39-a193-9c05d5e7fec4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在蜡板里刻了一个字。", "corrected_sentence": "他在蜡板上刻了一个字。", "error_description": "错误：“蜡板里”。应为“蜡板上”。蜡板是平面，表示位置要用“上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5159cda2-c11f-4c39-a193-9c05d5e7fec4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
