INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用线做出布来。", "primary_collocate": null, "pronunciation": "zhī bù", "ipa": "ʈʂɨ⁵⁵ pu⁵¹", "syllable_count": 2, "sentences": [{"text": "外婆每天早上都在院子里织布。", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的女人冬天没有别的事，就在家织布。", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她织布用的线是自己染的。", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种老式机器织布很慢。", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次看到有人用手织布。", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "织布时，手和脚要一起用力。", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会织布吗？", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我常看妈妈织布到很晚。", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想学织布，给孩子做一件衣服。", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在工厂里织布。", "target_word": "织布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "织了布", "label": "体标"}, {"form": "织过布", "label": "体标"}, {"form": "织布机", "label": "复合"}, {"form": "織布", "label": "繁体"}], "register": "中性", "sense_fingerprint": "织布|用线做出布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96be1c3a-0599-4f64-80f7-0c642716e3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39868, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "织布", "is_correct": true, "explanation": "正确答案：织布（zhī bù），用线做出布来。"}, {"text": "湿布", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh／zh），意思是湿的布。"}, {"text": "止步", "is_correct": false, "explanation": "zhǐ 与 zhī 声调不同（第三声与第一声），意思是停下脚步。"}, {"text": "织补", "is_correct": false, "explanation": "bǔ 与 bù 声调不同（第三声与第四声），意思是织补、修补衣物。"}], "explanations": {"织布": "正确答案：织布（zhī bù），用线做出布来。", "湿布": "shī 与 zhī 声母不同（sh／zh），意思是湿的布。", "止步": "zhǐ 与 zhī 声调不同（第三声与第一声），意思是停下脚步。", "织补": "bǔ 与 bù 声调不同（第三声与第四声），意思是织补、修补衣物。"}, "sentence_index": null, "correct_answer": "织布"}, "level_3": {"options": [{"text": "织布", "is_correct": true, "explanation": "正确答案：织布，指用线做布，外婆一早在院子里做的就是这件事。"}, {"text": "开飞机", "is_correct": false, "explanation": "语义：院子里不能开飞机，与“外婆”和“院子里”的日常场景矛盾。"}, {"text": "登月", "is_correct": false, "explanation": "语义：登月是太空活动，与外婆在院子里的日常场景完全不符。"}, {"text": "稽查", "is_correct": false, "explanation": "语域：“稽查”是正式的执法用语，与这句日常叙述不协调。"}], "explanations": {"织布": "正确答案：织布，指用线做布，外婆一早在院子里做的就是这件事。", "开飞机": "语义：院子里不能开飞机，与“外婆”和“院子里”的日常场景矛盾。", "登月": "语义：登月是太空活动，与外婆在院子里的日常场景完全不符。", "稽查": "语域：“稽查”是正式的执法用语，与这句日常叙述不协调。"}, "sentence_index": 0, "correct_answer": "织布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用剪刀织布。", "explanation": "这里应该用〈剪布〉。剪刀用来裁剪布料，织布要用织机和纱线。"}, {"text": "农民用锄头织布。", "explanation": "这里应该用〈锄地〉。锄头用来翻土，织布不能用锄头。"}, {"text": "她在手帕上织布。", "explanation": "这里应该用〈绣花〉。织布是用纱线织成布料，在手帕上做图案要用“绣花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39868, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "织布", "is_correct": true, "explanation": "正确答案：织布（zhī bù），用线做出布来。"}, {"text": "基部", "is_correct": false, "explanation": "jī 与 zhī 声母不同（j／zh），意思是底部、根部。"}, {"text": "支路", "is_correct": false, "explanation": "lù 与 bù 声母不同（l／b），意思是从主路分出的岔路。"}, {"text": "西部", "is_correct": false, "explanation": "xī 与 zhī 声母不同（x／zh），意思是西边的地区。"}], "explanations": {"织布": "正确答案：织布（zhī bù），用线做出布来。", "基部": "jī 与 zhī 声母不同（j／zh），意思是底部、根部。", "支路": "lù 与 bù 声母不同（l／b），意思是从主路分出的岔路。", "西部": "xī 与 zhī 声母不同（x／zh），意思是西边的地区。"}, "sentence_index": null, "correct_answer": "织布"}, "level_3": {"options": [{"text": "织布", "is_correct": true, "explanation": "正确答案：织布，问对方会不会用线做布。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“你会出生吗”没有意义，“出生”不是人可以学会的技能，与句意矛盾。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“你会融化吗”不合逻辑，人不会融化，与句意矛盾。"}, {"text": "施行", "is_correct": false, "explanation": "语域：“施行”偏书面，用在这句口语化的提问里不协调。"}], "explanations": {"织布": "正确答案：织布，问对方会不会用线做布。", "出生": "语义：“你会出生吗”没有意义，“出生”不是人可以学会的技能，与句意矛盾。", "融化": "语义：“你会融化吗”不合逻辑，人不会融化，与句意矛盾。", "施行": "语域：“施行”偏书面，用在这句口语化的提问里不协调。"}, "sentence_index": 6, "correct_answer": "织布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们正在工厂里织钢铁。", "explanation": "这里应该用〈炼〉（炼钢铁）。织布是把纱线织成布料，钢铁要用“炼”。"}, {"text": "工人们正在工厂里织汽车。", "explanation": "这里应该用〈造〉（造汽车）。织布只用于纱线，汽车要用“造”或“生产”。"}, {"text": "工人们正在工厂里织手机。", "explanation": "这里应该用〈组装〉（组装手机）。织布指织成布料，手机是电子产品，要用“组装”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时织布过。", "corrected_sentence": "他年轻时织过布。", "error_description": "错误：“织布过”。正确：“织过布”。表示曾经做过的体标“过”要紧跟动词，宾语“布”放在“过”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们织布织了一大根布。", "corrected_sentence": "他们织布织了一大块布。", "error_description": "错误：“织布织了一大根布”。正确：“织布织了一大块布”。布料的量词用“块”或“匹”，“根”用于细长的东西，不用于布。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
