INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39872, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爸爸，就是家里的大人。", "primary_collocate": null, "pronunciation": "fù qīn", "ipa": "fu⁵¹ tɕʰin⁵⁵", "syllable_count": 2, "sentences": [{"text": "我父亲今年五十岁，身体很好。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲下班回家，先洗手再吃饭。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的父亲是公交车司机。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，父亲带我们去公园玩。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲总是担心我吃得不好。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给父亲做了一碗面。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲和儿子一起在院子里踢球。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想对父亲说一声谢谢。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲不在家，母亲一个人做饭。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当了父亲以后，他变得更有耐心了。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位父亲", "label": "量词"}, {"form": "父亲节", "label": "复合"}, {"form": "父親", "label": "繁体"}], "register": "中性", "sense_fingerprint": "父亲|爸爸，家里的大人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96be1c3a-0599-4f64-80f7-0c642716e3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39872, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "附近", "is_correct": false, "explanation": "附近 fù jìn：与“父亲”的第二音节声母不同（q 与 j），意思是靠近某处。"}, {"text": "父亲", "is_correct": true, "explanation": "父亲 fù qīn：正确答案，指爸爸，即家里的大人。"}, {"text": "付钱", "is_correct": false, "explanation": "付钱 fù qián：第二音节韵母与声调不同（qīn 与 qián），意思是付款。"}, {"text": "复印", "is_correct": false, "explanation": "复印 fù yìn：第二音节声母不同（q 与 y），意思是用机器复制文件。"}], "explanations": {"附近": "附近 fù jìn：与“父亲”的第二音节声母不同（q 与 j），意思是靠近某处。", "父亲": "父亲 fù qīn：正确答案，指爸爸，即家里的大人。", "付钱": "付钱 fù qián：第二音节韵母与声调不同（qīn 与 qián），意思是付款。", "复印": "复印 fù yìn：第二音节声母不同（q 与 y），意思是用机器复制文件。"}, "sentence_index": null, "correct_answer": "父亲"}, "level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人，不能用来描述年龄和身体状况。"}, {"text": "父亲", "is_correct": true, "explanation": "正确。“父亲”指人，可以说年龄和身体状况。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是人，不能说“今年五十岁，身体很好”。"}, {"text": "老爷", "is_correct": false, "explanation": "语域：“老爷”是旧式称呼，不符合现代中性语境。"}], "explanations": {"汽车": "语义：汽车不是人，不能用来描述年龄和身体状况。", "父亲": "正确。“父亲”指人，可以说年龄和身体状况。", "树": "语义：树不是人，不能说“今年五十岁，身体很好”。", "老爷": "语域：“老爷”是旧式称呼，不符合现代中性语境。"}, "sentence_index": 0, "correct_answer": "父亲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末，父亲还在幼儿园上学，要我们照顾他。", "explanation": "这里应该用〈孩子〉。“父亲”指家里的大人，句中说他还在幼儿园上学，是小孩，应说“孩子”。"}, {"text": "这位女士是我的父亲，周末带我们去公园玩。", "explanation": "这里应该用〈母亲〉。“父亲”指家里的男性大人，句中的主语是女性，应说“母亲”。"}, {"text": "请问父亲，去公园怎么走？", "explanation": "这里应该用〈叔叔〉。“父亲”指家里的爸爸，不能用来称呼陌生男子，问路时应称〈叔叔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足球", "is_correct": false, "explanation": "语义：足球不能作“踢球”的执行者，与“和儿子一起踢球”矛盾。"}, {"text": "父亲", "is_correct": true, "explanation": "正确。“父亲”是能与儿子一起踢球的人。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能与儿子一起在院子里踢球。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“行李”不能与“踢球”这类动作搭配作主语。"}], "explanations": {"足球": "语义：足球不能作“踢球”的执行者，与“和儿子一起踢球”矛盾。", "父亲": "正确。“父亲”是能与儿子一起踢球的人。", "冰箱": "语义：冰箱不能与儿子一起在院子里踢球。", "行李": "搭配：“行李”不能与“踢球”这类动作搭配作主语。"}, "sentence_index": 6, "correct_answer": "父亲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我父亲是妈妈的弟弟，每个周末都带我去钓鱼。", "explanation": "这里应该用〈舅舅〉。“父亲”指孩子的父亲，句中说的是妈妈的弟弟，应用〈舅舅〉。"}, {"text": "这家餐厅的父亲做的菜很好吃。", "explanation": "这里把“父亲”用来指厨师，但该词只指有子女的男性家长，不指职业身份。"}, {"text": "我的父亲每天和我一起上班，我们结婚十年了。", "explanation": "这里应该用〈丈夫〉。“父亲”指孩子的父亲，句中说的却是我的配偶，应用〈丈夫〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只好父亲。", "corrected_sentence": "我有一位好父亲。", "error_description": "量词错误：“父亲”指人，应用“位”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想对父亲说一个谢谢。", "corrected_sentence": "我想对父亲说一声谢谢。", "error_description": "量词错误：“谢谢”作宾语时须用量词“声”，应说“说一声谢谢”，不能用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
