INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39873, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指有子女的男性，是家庭中的父亲角色。", "primary_collocate": null, "pronunciation": "fù qīn", "ipa": "fu⁵¹ tɕʰin⁵⁵", "syllable_count": 2, "sentences": [{"text": "父亲是家庭的权威，母亲则负责管理家务和照顾孩子。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我的父亲是一名医生。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲每天早上六点起床。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六月的第三个星期日，我给父亲买了一件礼物。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的父亲在工厂工作了三十年。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲对我说，做事要认真。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我父亲和母亲都是老师。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很爱父亲，常常给他打电话。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲看着孩子，笑了。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，父亲常常带我去河边钓鱼。", "target_word": "父亲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位父亲", "label": "量词"}, {"form": "父亲节", "label": "复合"}, {"form": "父親", "label": "繁体"}], "register": "中性", "sense_fingerprint": "父亲|有子女的男性，家庭中的父亲角色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96be1c3a-0599-4f64-80f7-0c642716e3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "附近", "is_correct": false, "explanation": "附近 fù jìn：与“父亲”的第二音节声母不同（q 与 j），意思是靠近某处。"}, {"text": "父亲", "is_correct": true, "explanation": "父亲 fù qīn：正确答案，指有子女的男性。"}, {"text": "付钱", "is_correct": false, "explanation": "付钱 fù qián：第二音节韵母与声调不同（qīn 与 qián），意思是付款。"}, {"text": "复印", "is_correct": false, "explanation": "复印 fù yìn：第二音节声母不同（q 与 y），意思是用机器复制文件。"}], "explanations": {"附近": "附近 fù jìn：与“父亲”的第二音节声母不同（q 与 j），意思是靠近某处。", "父亲": "父亲 fù qīn：正确答案，指有子女的男性。", "付钱": "付钱 fù qián：第二音节韵母与声调不同（qīn 与 qián），意思是付款。", "复印": "复印 fù yìn：第二音节声母不同（q 与 y），意思是用机器复制文件。"}, "sentence_index": null, "correct_answer": "父亲"}, "level_3": {"options": [{"text": "孩子", "is_correct": false, "explanation": "语义：孩子不是家庭的权威，且后句说的是“照顾孩子”，与此矛盾。"}, {"text": "父亲", "is_correct": true, "explanation": "正确。“父亲”指男性家长，与后句的“母亲则”形成对比。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能充当家庭的权威。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是人，不能作家庭的权威。"}], "explanations": {"孩子": "语义：孩子不是家庭的权威，且后句说的是“照顾孩子”，与此矛盾。", "父亲": "正确。“父亲”指男性家长，与后句的“母亲则”形成对比。", "厨房": "语义：厨房是场所，不能充当家庭的权威。", "电视": "语义：电视不是人，不能作家庭的权威。"}, "sentence_index": 0, "correct_answer": "父亲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个男孩子是我的父亲。", "explanation": "这里应该用〈儿子〉。“父亲”指有子女的男性家长，句中说的是一个小男孩，他不可能是父亲，应说“儿子”。"}, {"text": "这位女士是我的父亲。", "explanation": "这里应该用〈母亲〉。“父亲”指有子女的男性家长，这里的主语是女性，应说“母亲”。"}, {"text": "请问父亲，去火车站怎么走？", "explanation": "这里应该用〈叔叔〉。“父亲”只指有子女的男性家长，不能用来称呼陌生男子，问路时应称〈叔叔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是人，不能与母亲并列作“都是老师”的主语。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“学生”作并列主语时，与“都是老师”的身份不搭配。"}, {"text": "父亲", "is_correct": true, "explanation": "正确。“父亲”与“母亲”并列，指家中男性家长，与“都是老师”相合。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与老师是不同职业，与“都是老师”冲突。"}], "explanations": {"冰箱": "语义：冰箱不是人，不能与母亲并列作“都是老师”的主语。", "学生": "搭配：“学生”作并列主语时，与“都是老师”的身份不搭配。", "父亲": "正确。“父亲”与“母亲”并列，指家中男性家长，与“都是老师”相合。", "厨师": "语义：厨师与老师是不同职业，与“都是老师”冲突。"}, "sentence_index": 6, "correct_answer": "父亲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我父亲是妈妈的弟弟，每个周末都带我去钓鱼。", "explanation": "这里应该用〈舅舅〉。“父亲”指孩子的父亲，句中说的是妈妈的弟弟，应用〈舅舅〉。"}, {"text": "这家餐厅的父亲做的菜很好吃。", "explanation": "这里把“父亲”用来指厨师，但该词只指有子女的男性家长，不指职业身份。"}, {"text": "我的父亲每天和我一起上班，我们结婚十年了。", "explanation": "这里应该用〈丈夫〉。“父亲”指孩子的父亲，句中说的却是我的配偶，应用〈丈夫〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只好父亲。", "corrected_sentence": "我有一位好父亲。", "error_description": "量词错误：“父亲”指人，应用“位”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很爱父亲，常常把他打电话。", "corrected_sentence": "她很爱父亲，常常给他打电话。", "error_description": "介词误用：“打电话”的对象应由介词“给”引出，不能用“把”字句，应说“给他打电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
