INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "负责处理家庭中的日常事务，如做饭、打扫、照顾家人等。", "primary_collocate": null, "pronunciation": "guǎn lǐ jiā wù", "ipa": "kwan˨˩˦ li˨˩˦ tɕja˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "父亲是家庭的权威，母亲则负责管理家务和照顾孩子。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "奶奶年纪大了，现在由妈妈管理家务。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她结婚以后辞了工作，在家专门管理家务。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会管理家务，家里每天都干干净净。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妻子上班，丈夫在家管理家务和带孩子。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就跟着母亲学习管理家务。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱和时间都要安排，管理家务真不容易。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人生病住院，家里没人管理家务了。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把管理家务的事交给了大女儿。", "target_word": "管理家务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位阿姨负责管理家务，你不用操心。", "target_word": "管理家务", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "管理家務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "负责处理家庭日常事务（做饭、打扫、照顾家人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96be1c3a-0599-4f64-80f7-0c642716e3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出差", "is_correct": false, "explanation": "语义：“出差”与后句“照顾孩子”不能并列为母亲的职责。"}, {"text": "管理家务", "is_correct": true, "explanation": "正确。与后句“照顾孩子”并列，指处理家庭日常事务。"}, {"text": "离开", "is_correct": false, "explanation": "搭配：“负责”后接的应是任务性动词，“离开”不能与之搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”不是母亲的职责，与“负责”和“照顾孩子”的语境矛盾。"}], "explanations": {"出差": "语义：“出差”与后句“照顾孩子”不能并列为母亲的职责。", "管理家务": "正确。与后句“照顾孩子”并列，指处理家庭日常事务。", "离开": "搭配：“负责”后接的应是任务性动词，“离开”不能与之搭配。", "忘记": "语义：“忘记”不是母亲的职责，与“负责”和“照顾孩子”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "管理家务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很会管理碗，家里每天都干干净净。", "explanation": "这里应该用〈洗〉。“管理”不与“碗”搭配，洗碗要用〈洗〉。"}, {"text": "这位阿姨很会管理饭，大家都很喜欢吃。", "explanation": "这里应该用〈做〉。“管理”不与“饭”搭配，做饭要用〈做〉。"}, {"text": "她很会管理鸡蛋，每天早上都让全家吃得很香。", "explanation": "这里应该用〈煎〉。“管理”不与“鸡蛋”搭配，煎鸡蛋要用〈煎〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙发", "is_correct": false, "explanation": "语义：沙发不能作“真不容易”的主语，句意不通。"}, {"text": "管理家务", "is_correct": true, "explanation": "正确。指处理家务，与前句“钱和时间都要安排”的语境相合。"}, {"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”与前句的安排语境不符，作主语也不自然。"}, {"text": "发呆", "is_correct": false, "explanation": "搭配：“真不容易”的评价与随意的“发呆”状态不搭配。"}], "explanations": {"沙发": "语义：沙发不能作“真不容易”的主语，句意不通。", "管理家务": "正确。指处理家务，与前句“钱和时间都要安排”的语境相合。", "撒谎": "语义：“撒谎”与前句的安排语境不符，作主语也不自然。", "发呆": "搭配：“真不容易”的评价与随意的“发呆”状态不搭配。"}, "sentence_index": 6, "correct_answer": "管理家务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位阿姨负责管理窗户，你不用操心。", "explanation": "这里应该用〈擦〉。“管理”不与“窗户”搭配，擦窗户要用〈擦〉。"}, {"text": "这位阿姨负责管理衣服，你不用操心。", "explanation": "这里应该用〈洗〉。“管理”不与“衣服”搭配，洗衣服要用〈洗〉。"}, {"text": "这位阿姨负责管理饺子，你不用操心。", "explanation": "这里应该用〈包〉。“管理”不与“饺子”搭配，包饺子要用〈包〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
