INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39878, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把脏东西弄干净。", "primary_collocate": null, "pronunciation": "dǎ sǎo", "ipa": "ta˨˩˦ sɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "每个星期六，我们都打扫卫生。", "target_word": "打扫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们一大早就在打扫街道。", "target_word": "打扫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把阳台打扫得干干净净。", "target_word": "打扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的地板脏了，请清洁工来打扫。", "target_word": "打扫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，爷爷出去打扫门口的落叶。", "target_word": "打扫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年前我们把整个楼道都打扫了一遍。", "target_word": "打扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个车库很久没人打扫，到处都是灰。", "target_word": "打扫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者们周末来公园打扫，大家都很感谢他们。", "target_word": "打扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室容易脏，我每周都打扫一次。", "target_word": "打扫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她打扫得很认真，连桌子下面都擦干净了。", "target_word": "打扫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打掃", "label": "繁体"}, {"form": "打扫了", "label": "体标"}, {"form": "打扫过", "label": "体标"}, {"form": "打扫打扫", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把脏东西弄干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96be1c3a-0599-4f64-80f7-0c642716e3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打扫", "is_correct": true, "explanation": "正确：打扫（dǎ sǎo）即本词条。"}, {"text": "大嫂", "is_correct": false, "explanation": "声调不同：dǎ（第三声）与 dà（第四声）不同，大嫂（dàsǎo）指哥哥的妻子。"}, {"text": "打扰", "is_correct": false, "explanation": "声母不同：sǎo 与 rǎo 只差声母（s 与 r），打扰（dǎrǎo）指妨碍别人。"}, {"text": "打早", "is_correct": false, "explanation": "声母不同：sǎo 与 zǎo 只差声母（s 与 z），打早（dǎzǎo）为口语，指一大早。"}], "explanations": {"打扫": "正确：打扫（dǎ sǎo）即本词条。", "大嫂": "声调不同：dǎ（第三声）与 dà（第四声）不同，大嫂（dàsǎo）指哥哥的妻子。", "打扰": "声母不同：sǎo 与 rǎo 只差声母（s 与 r），打扰（dǎrǎo）指妨碍别人。", "打早": "声母不同：sǎo 与 zǎo 只差声母（s 与 z），打早（dǎzǎo）为口语，指一大早。"}, "sentence_index": null, "correct_answer": "打扫"}, "level_3": {"options": [{"text": "打扫", "is_correct": true, "explanation": "正确：“打扫”指清理卫生，与“每个星期六”的日常清洁语境相符。"}, {"text": "欺骗", "is_correct": false, "explanation": "搭配：“欺骗”的对象是人，不能说“欺骗卫生”。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”的对象是人，不能说“嘲笑卫生”。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“摧毁”含破坏之意，与“每个星期六”的日常清洁语境相反。"}], "explanations": {"打扫": "正确：“打扫”指清理卫生，与“每个星期六”的日常清洁语境相符。", "欺骗": "搭配：“欺骗”的对象是人，不能说“欺骗卫生”。", "嘲笑": "搭配：“嘲笑”的对象是人，不能说“嘲笑卫生”。", "摧毁": "语义：“摧毁”含破坏之意，与“每个星期六”的日常清洁语境相反。"}, "sentence_index": 0, "correct_answer": "打扫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上打扫碗筷。", "explanation": "这里应该用〈清洗〉。打扫多用于清理房间、地面等场所；碗筷一般说“清洗”。"}, {"text": "爸爸正在打扫坏了的电灯。", "explanation": "这里应该用〈修理〉。句中说电灯坏了，需要的是“修理”，而不是把它弄干净。"}, {"text": "他每天早上打扫脸。", "explanation": "这里应该用〈洗〉。打扫的对象是场所或物品，洗脸要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打扫", "is_correct": true, "explanation": "正确：“打扫”指清理车库，与“到处都是灰”的状况相符。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象不能是车库，不能说“没人咬车库”。"}, {"text": "祝福", "is_correct": false, "explanation": "搭配：“祝福”的对象是人，不能用于车库。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物或幼小者，不能用于车库。"}], "explanations": {"打扫": "正确：“打扫”指清理车库，与“到处都是灰”的状况相符。", "咬": "搭配：“咬”的对象不能是车库，不能说“没人咬车库”。", "祝福": "搭配：“祝福”的对象是人，不能用于车库。", "喂养": "搭配：“喂养”的对象是动物或幼小者，不能用于车库。"}, "sentence_index": 6, "correct_answer": "打扫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人正在打扫坏掉的收音机。", "explanation": "这里应该用〈修理〉。打扫指把脏东西弄干净，坏掉的收音机要用“修理”。"}, {"text": "她每天晚上打扫日记。", "explanation": "这里应该用〈写〉。打扫指清理脏东西，写日记要用“写”。"}, {"text": "他一大早就去打扫车票。", "explanation": "这里应该用〈买〉。打扫指清理脏东西，买车票要用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把客厅打扫很干净。", "corrected_sentence": "他把客厅打扫得很干净。", "error_description": "“打扫”后接程度补语时必须加“得”，应说“打扫得很干净”，不能说“打扫很干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把书房打扫。", "corrected_sentence": "我们把书房打扫干净了。", "error_description": "“把”字句中，双音节动词“打扫”单独与宾语搭配后必须再带补语或其他成分，不能只说“把书房打扫”。应补上结果补语“干净”，说“把书房打扫干净了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '436e60bb-3f73-4bae-a303-463921313a7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
