INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39883, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指模仿婴儿或儿童外形制作的玩偶，常作为儿童的玩具。", "primary_collocate": null, "pronunciation": "wá wa", "ipa": "ua˧˥ ua", "syllable_count": 2, "sentences": [{"text": "他们会玩一些简单的玩具，比如木马、娃娃或者球。", "target_word": "娃娃", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "女儿抱着一个新娃娃睡觉。", "target_word": "娃娃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个娃娃的眼睛又大又圆。", "target_word": "娃娃", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她给娃娃穿上了红色的小衣服。", "target_word": "娃娃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里卖各种各样的娃娃。", "target_word": "娃娃", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "姐姐把娃娃放在小床上。", "target_word": "娃娃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的娃娃坏了，他很难过。", "target_word": "娃娃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过生日的时候，我收到了一个娃娃。", "target_word": "娃娃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个娃娃可以闭上眼睛。", "target_word": "娃娃", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她每天都和娃娃说话。", "target_word": "娃娃", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "布娃娃", "label": "复合"}], "register": "口语", "sense_fingerprint": "模仿婴儿或儿童外形的玩偶玩具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56646db2-0ace-4b53-a4ea-9de124412b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不是玩具，不能和木马、球并列。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不属于玩具，与“玩具”的类别冲突。"}, {"text": "高个子", "is_correct": false, "explanation": "体貌：“高个子”描写人的身材，不是玩具，与句中的类别不合。"}, {"text": "娃娃", "is_correct": true, "explanation": "“娃娃”是玩偶玩具，与木马、球同属玩具，句意通顺。"}], "explanations": {"鸡蛋": "语义：鸡蛋是食物，不是玩具，不能和木马、球并列。", "水果": "语义：水果是食物，不属于玩具，与“玩具”的类别冲突。", "高个子": "体貌：“高个子”描写人的身材，不是玩具，与句中的类别不合。", "娃娃": "“娃娃”是玩偶玩具，与木马、球同属玩具，句意通顺。"}, "sentence_index": 0, "correct_answer": "娃娃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个娃娃会开车去上班。", "explanation": "这里应该用〈职员〉。娃娃指玩偶，不会开车上班，不能用来指成年人。"}, {"text": "这个娃娃今年五十岁，是我的叔叔。", "explanation": "这里应该用〈叔叔〉。娃娃指玩偶，不能用来指五十岁的人。"}, {"text": "她每天吃一个娃娃当早饭。", "explanation": "这里应该用〈面包〉。娃娃是玩具，不能当食物吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不会“坏了”，句意冲突。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以“坏了”的物品，与句意不合。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能“坏了”，与玩偶坏了令人难过的句意冲突。"}, {"text": "娃娃", "is_correct": true, "explanation": "玩偶可以“坏了”，弟弟因此难过，符合句意。"}], "explanations": {"老师": "语义：老师是人，不会“坏了”，句意冲突。", "空气": "语义：空气不是可以“坏了”的物品，与句意不合。", "月亮": "语义：月亮是天体，不能“坏了”，与玩偶坏了令人难过的句意冲突。", "娃娃": "玩偶可以“坏了”，弟弟因此难过，符合句意。"}, "sentence_index": 6, "correct_answer": "娃娃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个娃娃是我的上司，每天都来公司开会。", "explanation": "这里应该用〈上司〉。娃娃指玩偶，不能用来指每天开会的上司。"}, {"text": "她每天早上用娃娃刷牙。", "explanation": "这里应该用〈牙刷〉。娃娃是玩偶，不能用来刷牙。"}, {"text": "她把娃娃当成书，每天读一遍。", "explanation": "这里应该用〈书〉。娃娃是玩偶，不能当书来读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐抱着一只新娃娃出门了。", "corrected_sentence": "姐姐抱着一个新娃娃出门了。", "error_description": "量词错误：“一只新娃娃”中的“只”用错了。“只”多用于动物，娃娃是玩偶，应说“一个新娃娃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天买了两条娃娃送给妹妹。", "corrected_sentence": "我昨天买了两个娃娃送给妹妹。", "error_description": "量词错误：“两条娃娃”中的“条”用错了。“条”用于细长的东西，娃娃是玩偶，应说“两个娃娃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
