INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39885, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "球是一种圆形的物体，通常用于游戏、运动或娱乐，如足球、篮球、皮球等。", "primary_collocate": null, "pronunciation": "qiú", "ipa": "tɕʰjoʊ˧˥", "syllable_count": 1, "sentences": [{"text": "他们会玩一些简单的玩具，比如木马、娃娃或者球。", "target_word": "球", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他把球踢给了我。", "target_word": "球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个球是红色的，很大。", "target_word": "球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗跑去追那个球。", "target_word": "球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "球掉进了河里。", "target_word": "球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在草地上玩球。", "target_word": "球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把球递给我。", "target_word": "球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球滚到了桌子下面。", "target_word": "球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用力一扔，球飞过了墙。", "target_word": "球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给弟弟买了一个新球。", "target_word": "球", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "足球", "label": "复合"}, {"form": "篮球", "label": "复合"}], "register": "口语", "sense_fingerprint": "用于游戏或运动的圆形物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56646db2-0ace-4b53-a4ea-9de124412b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39885, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球", "is_correct": true, "explanation": "正确。“球”是玩具的一种，与前面的木马、娃娃并列。"}, {"text": "作业本", "is_correct": false, "explanation": "语义：“作业本”是学习用品，不是孩子玩的玩具。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“玩”的宾语要是游戏或玩具，不能说“玩饭”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不是孩子玩的玩具。"}], "explanations": {"球": "正确。“球”是玩具的一种，与前面的木马、娃娃并列。", "作业本": "语义：“作业本”是学习用品，不是孩子玩的玩具。", "饭": "搭配：“玩”的宾语要是游戏或玩具，不能说“玩饭”。", "桌子": "语义：“桌子”是家具，不是孩子玩的玩具。"}, "sentence_index": 0, "correct_answer": "球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一张球。", "explanation": "这里的量词用错了。“张”用于纸、桌子这类平面的东西，球是立体的，不能用“张”来数。"}, {"text": "他买了一把球。", "explanation": "量词用错了。“把”用于有柄或可以握持的东西，如刀、伞、椅子，球没有柄，不能用“把”来数。"}, {"text": "我家有两条球。", "explanation": "这里的量词用错了。“条”用于细长的东西，球是圆的，不能用“条”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "球", "is_correct": true, "explanation": "正确。“球”是可以递给别人的东西，符合“请把……递给我”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”看不见、摸不着，不能被递给别人。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象的概念，不能用手递过去。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“递”的宾语要是能拿在手里的实物，不能说“递声音”。"}], "explanations": {"球": "正确。“球”是可以递给别人的东西，符合“请把……递给我”。", "空气": "语义：“空气”看不见、摸不着，不能被递给别人。", "时间": "语义：“时间”是抽象的概念，不能用手递过去。", "声音": "搭配：“递”的宾语要是能拿在手里的实物，不能说“递声音”。"}, "sentence_index": 6, "correct_answer": "球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹妹抱着一本球。", "explanation": "这里的量词用错了。“本”用于书册，球是圆的立体物，不能用“本”来数。"}, {"text": "他一口气把这个球喝光了。", "explanation": "搭配：“喝”的对象是饮品，球不能被喝，这里的动词与“球”搭配错误。"}, {"text": "她用这个球刷了牙。", "explanation": "搭配：“刷”用于牙刷等工具，球不能用来刷牙，这里的动作与“球”搭配错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我买了两本球。", "corrected_sentence": "妈妈给我买了两个球。", "error_description": "量词错误：“球”应该用量词“个”，说“两个球”；“本”用于书册，不能用来数球。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把扔球到了树上。", "corrected_sentence": "他把球扔到了树上。", "error_description": "语序错误：“把”字句里，宾语“球”要放在“把”后面、动词前面，应说“他把球扔到了树上”，不能说“他把扔球到了树上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
