INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一种游戏，一个人藏起来，其他人找。", "primary_collocate": null, "pronunciation": "zhuō mí cáng", "ipa": "ʈʂwo˥ mi˧˥ tsʰɑŋ˧˥", "syllable_count": 3, "sentences": [{"text": "今天放学后，我们去操场玩捉迷藏吧。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫和小狗好像在捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们玩了一下午捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸陪女儿在客厅里捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "捉迷藏的时候，不能躲到太远的地方。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玩捉迷藏时，一个人先藏起来，其他人去找。", "target_word": "捉迷藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候最爱和哥哥捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，孩子们还想再玩一次捉迷藏。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在草地上捉迷藏，笑声很大。", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想和我们一起玩捉迷藏吗？", "target_word": "捉迷藏", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "捉迷藏", "label": "原形"}, {"form": "捉了迷藏", "label": "完成体"}, {"form": "捉捉迷藏", "label": "重叠"}], "register": "口语", "sense_fingerprint": "游戏：一个人藏起来，其他人找", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56646db2-0ace-4b53-a4ea-9de124412b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捉迷藏", "is_correct": true, "explanation": "正确。“捉迷藏”是游戏，可以接在“玩”后面。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”不是游戏，不能用来做“去操场玩……吧”的邀请。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“玩”后面不能接“吃饭”这类日常活动。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：“写作业”是学习任务，不是可以去操场玩的游戏。"}], "explanations": {"捉迷藏": "正确。“捉迷藏”是游戏，可以接在“玩”后面。", "散步": "语义：“散步”不是游戏，不能用来做“去操场玩……吧”的邀请。", "吃饭": "搭配：“玩”后面不能接“吃饭”这类日常活动。", "写作业": "语义：“写作业”是学习任务，不是可以去操场玩的游戏。"}, "sentence_index": 0, "correct_answer": "捉迷藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在草地上弹捉迷藏。", "explanation": "搭配：“弹”的对象是钢琴、吉他等乐器，不能与“捉迷藏”搭配，这个动词用错了。"}, {"text": "我们在草地上踢捉迷藏。", "explanation": "搭配：“踢”的对象是球类，不能与“捉迷藏”搭配，这个动词用错了。"}, {"text": "他在家里喝捉迷藏。", "explanation": "搭配：“喝”的对象是饮品，不能与“捉迷藏”搭配，这个动词用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捉迷藏", "is_correct": true, "explanation": "正确。“捉迷藏”是一种游戏，“最爱和哥哥”玩的正是这类活动。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”不是可以和人一起做的活动，句子说不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不是可以和哥哥一起做的活动，句子说不通。"}, {"text": "发愁", "is_correct": false, "explanation": "语义：“发愁”是心里烦恼，不是可以一起做的活动。"}], "explanations": {"捉迷藏": "正确。“捉迷藏”是一种游戏，“最爱和哥哥”玩的正是这类活动。", "生病": "语义：“生病”不是可以和人一起做的活动，句子说不通。", "下雨": "语义：“下雨”是天气现象，不是可以和哥哥一起做的活动，句子说不通。", "发愁": "语义：“发愁”是心里烦恼，不是可以一起做的活动。"}, "sentence_index": 6, "correct_answer": "捉迷藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们玩了一朵捉迷藏。", "explanation": "量词用错了。“朵”用于花朵等，捉迷藏是游戏活动，不能用“朵”来计量。"}, {"text": "他把捉迷藏扔到了地上。", "explanation": "搭配：“扔”的对象是具体的物体，捉迷藏是游戏，不能被扔，这里的动词与“捉迷藏”搭配错误。"}, {"text": "我们在院子里骑捉迷藏。", "explanation": "搭配：“骑”的对象是车或马，不能与“捉迷藏”搭配，这个动词用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们在树林里玩了一个捉迷藏。", "corrected_sentence": "周末我们在树林里玩了一场捉迷藏。", "error_description": "量词错误：“捉迷藏”指一场游戏，计量应用“场”或“次”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表哥正在和我玩了捉迷藏。", "corrected_sentence": "表哥正在和我玩捉迷藏。", "error_description": "体标错误：“正在”表示动作正在进行，不能和“了”同用。应说“表哥正在和我玩捉迷藏”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
