INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39891, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39891, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "兴趣指人对某种活动或事物感到喜爱、好奇，愿意花时间去了解和参与的心理倾向。", "primary_collocate": null, "pronunciation": "xìng qù", "ipa": "ɕiŋ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "虽然古罗马的生活方式和我们今天有很大不同，但孩子们对家庭的爱和对游戏的兴趣，却是跨越时空的。", "target_word": "兴趣", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我对画画很有兴趣。", "target_word": "兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的兴趣是看书和跑步。", "target_word": "兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟对汽车有很大的兴趣。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师想了解学生的兴趣。", "target_word": "兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她花很多时间培养孩子的兴趣。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸对钓鱼的兴趣越来越大。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就对音乐有兴趣。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对这本书一点兴趣也没有。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的兴趣不同，不要让他们都学钢琴。", "target_word": "兴趣", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "兴趣", "label": "原形"}, {"form": "感兴趣", "label": "复合"}, {"form": "兴趣班", "label": "复合"}, {"form": "兴趣爱好", "label": "复合"}, {"form": "一种兴趣", "label": "量词"}], "register": "中性", "sense_fingerprint": "对活动或事物的喜爱与好奇，愿意花时间参与的倾向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56646db2-0ace-4b53-a4ea-9de124412b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兴趣", "is_correct": true, "explanation": "正确：兴趣指对游戏的喜爱和好奇，与前文“对家庭的爱”形成并列。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指价钱，不能用来表示对游戏的喜爱之情。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的外观，与句中表示心理倾向的语境不合。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”表示多少，不能和“对游戏的”搭配来表示心理倾向。"}], "explanations": {"兴趣": "正确：兴趣指对游戏的喜爱和好奇，与前文“对家庭的爱”形成并列。", "价格": "语义：“价格”指价钱，不能用来表示对游戏的喜爱之情。", "颜色": "语义：“颜色”是事物的外观，与句中表示心理倾向的语境不合。", "数量": "搭配：“数量”表示多少，不能和“对游戏的”搭配来表示心理倾向。"}, "sentence_index": 0, "correct_answer": "兴趣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次谈判要保护双方的兴趣。", "explanation": "这里应该用〈利益〉。兴趣指喜爱某事物的心理倾向，谈判中双方的得失要用“利益”。"}, {"text": "这本小说很有兴趣。", "explanation": "这里应该用〈有趣〉。兴趣指人对事情的喜爱，形容小说让人觉得有意思要用“有趣”，不能说“很有兴趣”。"}, {"text": "我每天晚上都享受阅读的兴趣。", "explanation": "这里应该用〈乐趣〉。“享受”搭配快乐、满足类的事物，兴趣是心理倾向，不能被享受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兴趣", "is_correct": true, "explanation": "正确：兴趣指对钓鱼的喜爱，与“越来越大”搭配表示喜爱程度增加。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人的岁数，与“对钓鱼的”搭配后意思不通。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”指快慢，不能用来表示对钓鱼的喜爱程度。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“距离”只表示空间间隔，不能和“对钓鱼的”组成表示心理倾向的短语。"}], "explanations": {"兴趣": "正确：兴趣指对钓鱼的喜爱，与“越来越大”搭配表示喜爱程度增加。", "年龄": "语义：“年龄”指人的岁数，与“对钓鱼的”搭配后意思不通。", "速度": "语义：“速度”指快慢，不能用来表示对钓鱼的喜爱程度。", "距离": "搭配：“距离”只表示空间间隔，不能和“对钓鱼的”组成表示心理倾向的短语。"}, "sentence_index": 6, "correct_answer": "兴趣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对学习的兴趣很认真。", "explanation": "这里应该用〈态度〉。“认真”修饰态度或做事的方式，兴趣本身不能用“认真”来形容。"}, {"text": "今天我的兴趣很好。", "explanation": "这里应该用〈心情〉。兴趣指对某事的喜爱，不用来描述整体的情绪状态。"}, {"text": "这种药的兴趣很好。", "explanation": "这里应该用〈效果〉。兴趣只指人对事物的喜爱，不能用来说药物的作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我对历史很兴趣。", "corrected_sentence": "我对历史很有兴趣。", "error_description": "错误形式：“我对历史很兴趣”；正确形式：“我对历史很有兴趣”。“兴趣”是名词，前面要用动词“有”带出，不能直接在“很”后面接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对音乐有很兴趣。", "corrected_sentence": "他对音乐很有兴趣。", "error_description": "错误形式：“有很兴趣”；正确形式：“很有兴趣”。程度副词“很”要放在动词“有”之前修饰“有兴趣”，不能插在“有”和“兴趣”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3342591d-31c8-476d-9dd4-b749640aa2e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
