INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39892, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39892, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示“但是”，用来连接前后不一样的意思。", "primary_collocate": null, "pronunciation": "què shì", "ipa": "tɕʰɥe˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他说要请客，付钱的却是我。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店外面很小，里面却是个大花园。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都想去海边，他想去的却是山上。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给他打电话，接电话的却是他妈妈。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信很短，内容却是非常重要。", "target_word": "却是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她看起来很年轻，年纪却是我们中最大的。", "target_word": "却是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想吃面条，妈妈做的却是米饭。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小学画画，现在做的工作却是开车。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上写的是公园，我走到那里却是一家商店。", "target_word": "却是", "complexity_tier": "T3", "furigana": "dì tú shàng xiě de shì gōng yuán, wǒ zǒu dào nà lǐ què shì yì jiā shāng diàn。", "sentence_source": "generated"}, {"text": "我们等了很久，等来的却是坏消息。", "target_word": "却是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连接前后意思不同的两部分，相当于“但是”，后面常接名词性内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '434c0685-b138-4d57-a528-8792d79dfc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "却是", "is_correct": true, "explanation": "表示「但是」，连接前后不一样的意思，引出「付钱的人」实际是「我」，与「他说要请客」形成对照。"}, {"text": "太", "is_correct": false, "explanation": "搭配：「太」要修饰形容词，不能直接放在「是我」前面。"}, {"text": "最", "is_correct": false, "explanation": "搭配：「最」表示程度最高，后面要接形容词，这里接「是我」不成立。"}, {"text": "岂", "is_correct": false, "explanation": "语域：「岂是」属于书面反问，与这句口语化的陈述不符，并使句子变成反问。"}], "explanations": {"却是": "表示「但是」，连接前后不一样的意思，引出「付钱的人」实际是「我」，与「他说要请客」形成对照。", "太": "搭配：「太」要修饰形容词，不能直接放在「是我」前面。", "最": "搭配：「最」表示程度最高，后面要接形容词，这里接「是我」不成立。", "岂": "语域：「岂是」属于书面反问，与这句口语化的陈述不符，并使句子变成反问。"}, "sentence_index": 0, "correct_answer": "却是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和我却是都爱吃辣。", "explanation": "这里应该用〈也〉。〈却是〉表示前后不同的意思；这里只是说两人有共同的爱好，没有对照，应该用〈也〉。"}, {"text": "他下班后先去健身房，却是去超市买菜。", "explanation": "这里应该用〈然后〉。前后是先后承接的动作，没有对立，〈却是〉表示转折，用在这里不自然。"}, {"text": "这辆车很新，却是我的自行车。", "explanation": "这里应该用〈就是〉。〈却是〉表示转折，这句只是做肯定判断，没有对照，应该用〈就是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "却是", "is_correct": true, "explanation": "表示「但是」，前句说想吃面条，后面引出妈妈做的实际是米饭，两者不一样。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：「十分」修饰形容词，不能直接修饰名词「米饭」。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」要修饰形容词或状态，不能直接放在「是米饭」前面。"}, {"text": "岂是", "is_correct": false, "explanation": "语域：「岂是」为书面反问，「妈妈做的岂是米饭」意为「怎会是米饭」，与句意不符。"}], "explanations": {"却是": "表示「但是」，前句说想吃面条，后面引出妈妈做的实际是米饭，两者不一样。", "十分": "搭配：「十分」修饰形容词，不能直接修饰名词「米饭」。", "很": "搭配：「很」要修饰形容词或状态，不能直接放在「是米饭」前面。", "岂是": "语域：「岂是」为书面反问，「妈妈做的岂是米饭」意为「怎会是米饭」，与句意不符。"}, "sentence_index": 6, "correct_answer": "却是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下了一夜的雨，却是地面湿了。", "explanation": "这里应该用〈因而〉。前后是因果关系，没有相反的对照，〈却是〉表示转折，用在这里不自然。"}, {"text": "我们吃了早饭，却是去了学校。", "explanation": "这里应该用〈然后〉。前后是先后承接的动作，没有对立，〈却是〉表示转折，用在这里不自然。"}, {"text": "他每天按时吃饭，却是身体很健康。", "explanation": "这里应该用〈因此〉。前后是因果关系，不是相反的情况，〈却是〉表示转折，用在这里不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以为今天没有课，来的却是了校长。", "corrected_sentence": "我以为今天没有课，来的却是校长。", "error_description": "错误：「却是了」。正确：「却是」。「却是」是副词，后面不能再加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "平时很少做饭的爸爸，今天做的却是了一桌好菜。", "corrected_sentence": "平时很少做饭的爸爸，今天做的却是一桌好菜。", "error_description": "错误：「却是了一桌」。正确：「却是一桌」。「却是」是副词，后面不能再加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
