INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39894, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "concrete", "definition": "表示某个地方或东西里面有很多很多。", "primary_collocate": null, "pronunciation": "chōng mǎn", "ipa": "ʈʂʰʊŋ˥ man˨˩˦", "syllable_count": 2, "sentences": [{"text": "房间里充满了花的香味。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "体育馆里充满了看比赛的人。", "target_word": "充满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大街上充满了汽车的声音。", "target_word": "充满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个湖里充满了小鱼。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "厨房里充满着饭菜的香味。", "target_word": "充满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气中充满了烟味。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书店里充满了新书。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的包里充满了各种零食。", "target_word": "充满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空中充满了星星。", "target_word": "充满", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "教室里充满了孩子们的笑声。", "target_word": "充满", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "充满了", "label": "完成体"}, {"form": "充满着", "label": "持续体"}, {"form": "充满过", "label": "经历体"}, {"form": "充滿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "具体空间或容器里面有很多人、物、气味或声音，如房间里充满香味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '434c0685-b138-4d57-a528-8792d79dfc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "充满", "is_correct": true, "explanation": "表示房间里充满了气味，符合「花的香味」的语境。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：「驱散」表示赶走，与「充满」的意思相反，句意不通。"}, {"text": "挤满", "is_correct": false, "explanation": "搭配：「挤满」多指人或物挤在一起，不能用于气味。"}, {"text": "缺乏", "is_correct": false, "explanation": "语义：「缺乏」表示没有，与句中「花的香味」存在相反的语义。"}], "explanations": {"充满": "表示房间里充满了气味，符合「花的香味」的语境。", "驱散": "语义：「驱散」表示赶走，与「充满」的意思相反，句意不通。", "挤满": "搭配：「挤满」多指人或物挤在一起，不能用于气味。", "缺乏": "语义：「缺乏」表示没有，与句中「花的香味」存在相反的语义。"}, "sentence_index": 0, "correct_answer": "充满"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地面上充满了白雪。", "explanation": "这里应该用〈覆盖〉。〈覆盖〉指盖在表面，〈充满〉指填满某个空间或容器的内部。"}, {"text": "这个湖里充满了一条小鱼。", "explanation": "这里应该用〈有〉。〈充满〉要求数量很多，一条鱼不足以占满湖。"}, {"text": "墙上充满了一幅画。", "explanation": "这里应该用〈挂〉。〈充满〉不用于墙面这样的表面，墙上挂画要用〈挂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充满", "is_correct": true, "explanation": "表示书店里到处都是新书，符合句意。"}, {"text": "显示", "is_correct": false, "explanation": "语义：「显示」表示展现，书店里不能说「显示新书」，句意不通。"}, {"text": "发出", "is_correct": false, "explanation": "搭配：「发出」多用于声音、光、气味，不能用于书。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：「倒」指把液体倾出，与「新书」不搭配。"}], "explanations": {"充满": "表示书店里到处都是新书，符合句意。", "显示": "语义：「显示」表示展现，书店里不能说「显示新书」，句意不通。", "发出": "搭配：「发出」多用于声音、光、气味，不能用于书。", "倒": "搭配：「倒」指把液体倾出，与「新书」不搭配。"}, "sentence_index": 6, "correct_answer": "充满"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "树上充满了一个苹果。", "explanation": "这里应该用〈挂〉。〈充满〉指空间被大量东西占满，树上挂一个苹果要用〈挂〉。"}, {"text": "我的口袋里充满了一块糖。", "explanation": "这里应该用〈装〉。〈充满〉指大量内容占满，口袋里装一块糖要用〈装〉。"}, {"text": "桌上充满了一本书。", "explanation": "这里应该用〈放〉。〈放〉表示位置，只放一本书不会「充满」桌面，应该用〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教室里充满了了同学们的讨论声。", "corrected_sentence": "教室里充满了同学们的讨论声。", "error_description": "错误：「充满了了」。正确：「充满了」。句中只需一个「了」，重复使用「了」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房里充满过了烤面包的香味。", "corrected_sentence": "厨房里充满了烤面包的香味。", "error_description": "错误：「充满过了」。正确：「充满了」。「过」表示经历，与「了」表示完成不能同时用在同一个动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
