INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很久很久以前的时间。", "primary_collocate": null, "pronunciation": "gǔ shí hou", "ipa": "ku˨˩ ʂɨ˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "古时候，这座山上住着一位老神仙。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候人们不知道地球是圆的。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说古时候冬天比现在冷得多。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候没有汽车，人们走路去远方。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事发生在没有电的古时候。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人靠种地和打猎生活。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，古时候这里有一条大河。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的夏天没有空调，大家用扇子。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，孩子们没有玩具，只能玩泥巴。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的房子大多是用木头盖的。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "古時候", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很久很久以前的那段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3a831af-5367-40ed-841f-74e0e251ef1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古时候", "is_correct": true, "explanation": "正确：“古时候”指很久很久以前的时间，与“老神仙”的传说语境相符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”指一顿饭，不表示时间，不能作句首的时间话题。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是处所名词，与“这座山上住着神仙”的叙述不搭。"}, {"text": "年份", "is_correct": false, "explanation": "语义：“年份”指具体的年度，不指很久以前的一段时期，与“老神仙”的叙述不搭。"}], "explanations": {"古时候": "正确：“古时候”指很久很久以前的时间，与“老神仙”的传说语境相符。", "早饭": "语义：“早饭”指一顿饭，不表示时间，不能作句首的时间话题。", "厨房": "语义：“厨房”是处所名词，与“这座山上住着神仙”的叙述不搭。", "年份": "语义：“年份”指具体的年度，不指很久以前的一段时期，与“老神仙”的叙述不搭。"}, "sentence_index": 0, "correct_answer": "古时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我古时候在北京住过三年。", "explanation": "这里应该用〈以前〉。古时候指很久远的时代，不能用来说说话人自己在北京的经历。"}, {"text": "我古时候很怕黑，每次都不敢一个人睡。", "explanation": "这里应该用〈小时候〉。古时候指遥远的古代，不指说话人自己的童年。"}, {"text": "我古时候刚吃完午饭。", "explanation": "这里应该用〈刚才〉。古时候指很久远的时代，不能用来说刚刚发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古时候", "is_correct": true, "explanation": "正确：“古时候”作时间话题，与“书上说”的历史叙述相符。"}, {"text": "老铁", "is_correct": false, "explanation": "语域：“老铁”是网络口语，不能用在“书上说”这样的书面叙述中。"}, {"text": "大爷", "is_correct": false, "explanation": "语域：“大爷”是口语称呼，与书面叙述不搭，也不能表示时间。"}, {"text": "驼背", "is_correct": false, "explanation": "体貌：“驼背”描述人的体态，不表示时间，也不能作这里的时间话题。"}], "explanations": {"古时候": "正确：“古时候”作时间话题，与“书上说”的历史叙述相符。", "老铁": "语域：“老铁”是网络口语，不能用在“书上说”这样的书面叙述中。", "大爷": "语域：“大爷”是口语称呼，与书面叙述不搭，也不能表示时间。", "驼背": "体貌：“驼背”描述人的体态，不表示时间，也不能作这里的时间话题。"}, "sentence_index": 6, "correct_answer": "古时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古时候我们要去火星工作。", "explanation": "这里应该用〈将来〉。古时候指过去的时代，不能用来说还没有发生的计划。"}, {"text": "古时候，我刚见过他。", "explanation": "这里应该用〈不久前〉。古时候指很久远的时代，不能和“刚”所表示的刚刚发生的事搭配。"}, {"text": "我古时候很忙。", "explanation": "这里应该用〈目前〉。古时候指遥远的时代，不能用来说当下的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古时候的时候，这里还没有人居住。", "corrected_sentence": "古时候，这里还没有人居住。", "error_description": "「古时候」本身已表示时间，后面不能再加「的时候」。正确：古时候，这里还没有人居住；错误：古时候的时候，这里还没有人居住。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
