INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39897, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指过去的时代，通常用于讲述历史故事。", "primary_collocate": null, "pronunciation": "gǔ shí hou", "ipa": "ku˨˩ ʂɨ˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "古时候，人们修建长城是为了防御。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "古时候没有电，晚上只能点蜡烛。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人出门骑马或者坐马车。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，皇帝住在很大的皇宫里。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常给我讲古时候的故事。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候没有手机，人们靠写信联系。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的小孩子在私塾里读书。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候这里是一片森林，现在是城市。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说古时候人们用贝壳当钱。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的医生用草药给病人治病。", "target_word": "古时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "古時候", "label": "繁体"}], "register": "中性", "sense_fingerprint": "过去的时代，多用于讲历史故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3a831af-5367-40ed-841f-74e0e251ef1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古时候", "is_correct": true, "explanation": "正确：“古时候”指过去的时代，与“修建长城是为了防御”的历史语境相符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”是空间名词，不表示时间，不能充当句首的时间话题。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是现代器物，不表示时间，放在句首说不通。"}, {"text": "茶馆", "is_correct": false, "explanation": "语义：“茶馆”是处所名词，不表示时间，放在句首与修建长城的历史叙述不搭。"}], "explanations": {"古时候": "正确：“古时候”指过去的时代，与“修建长城是为了防御”的历史语境相符。", "大海": "语义：“大海”是空间名词，不表示时间，不能充当句首的时间话题。", "手机": "语义：“手机”是现代器物，不表示时间，放在句首说不通。", "茶馆": "语义：“茶馆”是处所名词，不表示时间，放在句首与修建长城的历史叙述不搭。"}, "sentence_index": 0, "correct_answer": "古时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我古时候在这家公司工作过。", "explanation": "这里应该用〈以前〉。古时候指很久远的时代，不能用来说说话人不久前在公司的经历。"}, {"text": "古时候我常去外婆家玩。", "explanation": "这里应该用〈小时候〉。古时候指遥远的古代，不指说话人自己的童年。"}, {"text": "我古时候一直在学汉语。", "explanation": "这里应该用〈过去〉。古时候指遥远的时代，不能指说话人最近几年的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古时候", "is_correct": true, "explanation": "正确：“古时候”作定语，指过去的时代，与“私塾”的情境相符。"}, {"text": "白发", "is_correct": false, "explanation": "体貌：“白发”描述老年人的头发，与“小孩子”的年龄不符。"}, {"text": "大胡子", "is_correct": false, "explanation": "体貌：“大胡子”指成年男子的胡须，与“小孩子”不相称。"}, {"text": "受试者", "is_correct": false, "explanation": "语域：“受试者”是实验或调查中的专业用语，不适合用在“私塾读书”这种叙事语境中。"}], "explanations": {"古时候": "正确：“古时候”作定语，指过去的时代，与“私塾”的情境相符。", "白发": "体貌：“白发”描述老年人的头发，与“小孩子”的年龄不符。", "大胡子": "体貌：“大胡子”指成年男子的胡须，与“小孩子”不相称。", "受试者": "语域：“受试者”是实验或调查中的专业用语，不适合用在“私塾读书”这种叙事语境中。"}, "sentence_index": 6, "correct_answer": "古时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他古时候刚从超市回来。", "explanation": "这里应该用〈不久前〉。古时候指遥远的过去，不能用来说刚发生的事。"}, {"text": "我古时候七点起床。", "explanation": "这里应该用〈平时〉。古时候指很久远的时代，不能和“七点”这样的具体钟点连用。"}, {"text": "我古时候要参加明年的比赛。", "explanation": "这里应该用〈将来〉。古时候指过去的时代，不能用来说还没有发生的计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
