INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39898, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就是挡住敌人，不让别人打进来。", "primary_collocate": null, "pronunciation": "fáng yù", "ipa": "faŋ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "我们守在门口，努力防御敌人。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城门关上了，士兵在上面防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用石头防御，不让敌人进城。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人分两路来攻，我们先防御，再反攻。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人从北边打来，我们在山口防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不进攻，只是防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的武器能帮军队更好地防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们玩游戏，一队进攻，一队防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城墙很高，很适合防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方人多，我们只能守在城里防御。", "target_word": "防御", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防御力", "label": "复合"}, {"form": "防御战", "label": "复合"}, {"form": "防禦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "挡住敌人，不让对方打进来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3a831af-5367-40ed-841f-74e0e251ef1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防御", "is_correct": true, "explanation": "正确：“防御”指挡住敌人、不让其进来，与“守在门口”的语境相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象通常是客人，不说“努力欢迎敌人”。"}, {"text": "款待", "is_correct": false, "explanation": "语义：“款待”指热情招待客人，与守在门口抵挡敌人的处境相反。"}, {"text": "抵达", "is_correct": false, "explanation": "配价：“抵达”需要处所作宾语，不能直接带“敌人”作宾语。"}], "explanations": {"防御": "正确：“防御”指挡住敌人、不让其进来，与“守在门口”的语境相符。", "欢迎": "搭配：“欢迎”的对象通常是客人，不说“努力欢迎敌人”。", "款待": "语义：“款待”指热情招待客人，与守在门口抵挡敌人的处境相反。", "抵达": "配价：“抵达”需要处所作宾语，不能直接带“敌人”作宾语。"}, "sentence_index": 0, "correct_answer": "防御"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敌人从北边防御了我们的村庄。", "explanation": "这里应该用〈进攻〉。防御是抵挡外来攻击的一方所做的动作，进攻的一方不能用它。"}, {"text": "防御感冒，要多喝水。", "explanation": "这里应该用〈预防〉。防御用于抵挡外来的攻击，不用于疾病。"}, {"text": "这件衣服能防御皮肤。", "explanation": "这里应该用〈保护〉。防御指抵挡外来攻击，不用于衣服对身体的保护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防御", "is_correct": true, "explanation": "正确：“防御”指抵挡、阻挡敌人，与“更好地”修饰的军事用途相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是悠闲的活动，与武器帮助军队作战的语境不搭。"}, {"text": "吐槽", "is_correct": false, "explanation": "语域：“吐槽”是网络口语，不适合用于描述军队装备的书面叙述。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”描述人的体态，不能用于“军队”这样的组织。"}], "explanations": {"防御": "正确：“防御”指抵挡、阻挡敌人，与“更好地”修饰的军事用途相符。", "散步": "语义：“散步”是悠闲的活动，与武器帮助军队作战的语境不搭。", "吐槽": "语域：“吐槽”是网络口语，不适合用于描述军队装备的书面叙述。", "发胖": "体貌：“发胖”描述人的体态，不能用于“军队”这样的组织。"}, "sentence_index": 6, "correct_answer": "防御"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他防御了这道数学题。", "explanation": "这里应该用〈解答〉。防御用于抵挡外来的攻击，不用于回答或解决题目。"}, {"text": "我们防御不了这么多工作。", "explanation": "这里应该用〈应付〉。防御指抵挡外来的攻击，不能用于工作量。"}, {"text": "我们热情地防御客人。", "explanation": "这里应该用〈招待〉。防御用于抵挡攻击，不能用于接待客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在桥上防御了过敌人的船。", "corrected_sentence": "我们在桥上防御过敌人的船。", "error_description": "「防御」后只能用一个体标。正确：防御过；错误：防御了过（两个体标重复）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新的武器能让军队防御更好。", "corrected_sentence": "新的武器能让军队防御得更好。", "error_description": "动词「防御」后带情态补语时，要用补语标记「得」。正确：防御得更好；错误：防御更好。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
