INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39903, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指传说中的体型巨大的龙，常用来比喻气势磅礴或雄伟的事物。", "primary_collocate": null, "pronunciation": "jù lóng", "ipa": "tɕy˥˩ lʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "长城就像一条巨龙，在山上蜿蜒。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "火车像一条巨龙，穿过了山洞。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远远看去，公路像巨龙一样躺在山间。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江像一条巨龙，从西流到东。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的路像一条巨龙，一直向上。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，车灯连成了一条巨龙。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大桥像巨龙一样横在河上。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的队伍像一条长长的巨龙。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪山好像一条白色的巨龙。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高高的城墙像巨龙一样守着这座城。", "target_word": "巨龙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "巨龍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比喻又长又雄伟的事物的大龙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3a831af-5367-40ed-841f-74e0e251ef1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巨龙", "is_correct": true, "explanation": "巨龙：比喻气势雄伟、蜿蜒曲折的事物，这里比喻长城。"}, {"text": "裤子", "is_correct": false, "explanation": "语义：裤子是衣物，不会在山上蜿蜒，与句意不符。"}, {"text": "鲸鱼", "is_correct": false, "explanation": "语义：鲸鱼生活在海里，不会在山上蜿蜒，与句意不符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不会在山上蜿蜒，与句中的比喻不符。"}], "explanations": {"巨龙": "巨龙：比喻气势雄伟、蜿蜒曲折的事物，这里比喻长城。", "裤子": "语义：裤子是衣物，不会在山上蜿蜒，与句意不符。", "鲸鱼": "语义：鲸鱼生活在海里，不会在山上蜿蜒，与句意不符。", "面包": "语义：面包不会在山上蜿蜒，与句中的比喻不符。"}, "sentence_index": 0, "correct_answer": "巨龙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条巨龙是真实存在的动物，常生活在热带雨林里。", "explanation": "这里应该用〈巨蟒〉。巨龙是神话中的生物，不指现实中的动物。"}, {"text": "这座小亭子像一条巨龙，横在山坡上。", "explanation": "这里用“巨龙”比喻，但巨龙比喻的是气势磅礴、雄伟的事物，形容小亭子不合适。"}, {"text": "我家的小猫像一条巨龙，正在窗台上打盹。", "explanation": "这里用“巨龙”比喻，但巨龙比喻的是雄伟的事物，形容一只小猫与本义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巨龙", "is_correct": true, "explanation": "巨龙：比喻雄伟的大桥横跨河面的样子。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "体貌：大桥体型巨大，“蚂蚁”与其形象不符。"}, {"text": "仙女", "is_correct": false, "explanation": "语义：仙女不会像桥一样横在河上，与句意不符。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚不能像桥一样横在河上，与句中的比喻不符。"}], "explanations": {"巨龙": "巨龙：比喻雄伟的大桥横跨河面的样子。", "蚂蚁": "体貌：大桥体型巨大，“蚂蚁”与其形象不符。", "仙女": "语义：仙女不会像桥一样横在河上，与句意不符。", "扫帚": "语义：扫帚不能像桥一样横在河上，与句中的比喻不符。"}, "sentence_index": 6, "correct_answer": "巨龙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "博物馆里展出了一具巨龙的化石。", "explanation": "这里应该用〈恐龙〉。巨龙是传说中的生物，没有真实的化石，说古生物化石要用“恐龙”。"}, {"text": "一只蚂蚁爬过墙根，像一条巨龙。", "explanation": "这里用“巨龙”比喻，却形容一只很小的蚂蚁，与巨龙气势磅礴、雄伟的比喻义不符。"}, {"text": "一只小老鼠躲在墙角，像一条巨龙一样威风。", "explanation": "这里用“巨龙”比喻，但老鼠很小，巨龙比喻的是雄伟的事物，形容老鼠的威风不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处的城墙像一个巨龙，在山脊上蜿蜒。", "corrected_sentence": "远处的城墙像一条巨龙，在山脊上蜿蜒。", "error_description": "量词错误：“巨龙”作比喻时要用量词“条”，用通用量词“个”不对，应把“个”改为“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座长桥像巨龙一样一样横卧在江上。", "corrected_sentence": "这座长桥像巨龙一样横卧在江上。", "error_description": "重复错误：“像……一样”只用一个“一样”，多出的“一样”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
