INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "敌人就是想要伤害我们的人。", "primary_collocate": null, "pronunciation": "dí rén", "ipa": "ti˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "故事里的敌人想要抢走国王的城。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小兵看见敌人来了，马上关上城门。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人很多，我们的人很少。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一起想办法，不让敌人进城。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打仗的时候，敌人不会给我们吃的。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人是我们的敌人。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人在夜里悄悄走近了村子。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们勇敢地面对敌人。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的枪很多，但战士们没有害怕。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护家人，不让敌人伤害他们。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个敌人", "label": "量词"}, {"form": "敵人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想要伤害我们的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 小兵 (Zipf 3.21), 关上 (Zipf 3.85), 城门 (Zipf 3.77)','sentence 6 above tier T1: 4 words above tier T1 (max 2): 夜里 (Zipf 3.96), 悄悄 (Zipf 3.95), 走近 (Zipf 3.74), 村子 (Zipf 3.93)']::text[], '4c8dfe5f-92b1-44b2-9118-188d529cc519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敌人", "is_correct": true, "explanation": "正确。敌人 dí rén 指想要伤害我们的人。"}, {"text": "其人", "is_correct": false, "explanation": "其人 qí rén 第一个音节声母为 q，与 dí rén 的 d 不同，意思是那个人。"}, {"text": "词人", "is_correct": false, "explanation": "词人 cí rén 第一个音节声母为 c，与 dí rén 的 d 不同，意思是写词的作者。"}, {"text": "迷人", "is_correct": false, "explanation": "迷人 mí rén 第一个音节声母为 m，与 dí rén 的 d 不同，意思是有吸引力、令人着迷。"}], "explanations": {"敌人": "正确。敌人 dí rén 指想要伤害我们的人。", "其人": "其人 qí rén 第一个音节声母为 q，与 dí rén 的 d 不同，意思是那个人。", "词人": "词人 cí rén 第一个音节声母为 c，与 dí rén 的 d 不同，意思是写词的作者。", "迷人": "迷人 mí rén 第一个音节声母为 m，与 dí rén 的 d 不同，意思是有吸引力、令人着迷。"}, "sentence_index": null, "correct_answer": "敌人"}, "level_3": {"options": [{"text": "敌人", "is_correct": true, "explanation": "正确。“敌人”是想要抢走城池的一方，与“想要抢走国王的城”的语境相合。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友不会想要抢走国王的城，与句意矛盾。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“想要”需要有意愿的主体，河流不能想要做事。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不会想要抢走国王的城，句子在常理上说不通。"}], "explanations": {"敌人": "正确。“敌人”是想要抢走城池的一方，与“想要抢走国王的城”的语境相合。", "朋友": "语义：朋友不会想要抢走国王的城，与句意矛盾。", "河流": "搭配：“想要”需要有意愿的主体，河流不能想要做事。", "厨师": "语义：厨师不会想要抢走国王的城，句子在常理上说不通。"}, "sentence_index": 0, "correct_answer": "敌人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在棋赛中，我的敌人教我下棋，还送了我一本棋谱。", "explanation": "这里应该用〈老师〉之类表达。敌人想要伤害我们，不会教我们下棋或送我礼物。"}, {"text": "他的眼神里满是敌人。", "explanation": "这里应该用〈敌意〉。敌人指想要伤害我们的人，是人而非情绪，不能用来描述眼神里流露的态度。"}, {"text": "我们的村子里来了一位敌人，大家都很欢迎他。", "explanation": "这里应该用〈客人〉之类表达。敌人指想要伤害我们的人，不能用于大家欢迎的来访者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39906, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "敌人", "is_correct": true, "explanation": "正确。敌人 dí rén 指想要伤害我们的人。"}, {"text": "吉人", "is_correct": false, "explanation": "吉人 jí rén 第一个音节声母为 j，与 dí rén 的 d 不同，意思是品行善良、吉祥的人。"}, {"text": "十人", "is_correct": false, "explanation": "十人 shí rén 第一个音节声母为 sh，与 dí rén 的 d 不同，意思是十个人。"}, {"text": "泥人", "is_correct": false, "explanation": "泥人 ní rén 第一个音节声母为 n，与 dí rén 的 d 不同，意思是用泥捏成的人像。"}], "explanations": {"敌人": "正确。敌人 dí rén 指想要伤害我们的人。", "吉人": "吉人 jí rén 第一个音节声母为 j，与 dí rén 的 d 不同，意思是品行善良、吉祥的人。", "十人": "十人 shí rén 第一个音节声母为 sh，与 dí rén 的 d 不同，意思是十个人。", "泥人": "泥人 ní rén 第一个音节声母为 n，与 dí rén 的 d 不同，意思是用泥捏成的人像。"}, "sentence_index": null, "correct_answer": "敌人"}, "level_3": {"options": [{"text": "敌人", "is_correct": true, "explanation": "正确。“敌人”是想要伤害村子的一方，“悄悄走近”与之相合。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会在夜里悄悄走近村子，句子在常理上说不通。"}, {"text": "石桥", "is_correct": false, "explanation": "语义：石桥是固定的建筑，没有行动能力，不能“走近”村子。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“悄悄”和“走近”多用于有行动能力的人或动物，桌子不能自己移动。"}], "explanations": {"敌人": "正确。“敌人”是想要伤害村子的一方，“悄悄走近”与之相合。", "太阳": "语义：太阳不会在夜里悄悄走近村子，句子在常理上说不通。", "石桥": "语义：石桥是固定的建筑，没有行动能力，不能“走近”村子。", "桌子": "搭配：“悄悄”和“走近”多用于有行动能力的人或动物，桌子不能自己移动。"}, "sentence_index": 6, "correct_answer": "敌人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要保护家人，请敌人来给他们看病。", "explanation": "这里应该用〈医生〉。敌人想要伤害我们，不能被请来为家人看病。"}, {"text": "他是我的敌人，每次见面都拥抱我。", "explanation": "这里应该用〈朋友〉。敌人指想要伤害我们的一方，与每次见面都拥抱我的人矛盾。"}, {"text": "每逢过年，敌人都来我家团聚。", "explanation": "这里应该用〈亲戚〉。敌人想要伤害我们，不会来我家团聚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一条敌人突然冲进了村子。", "corrected_sentence": "一群敌人突然冲进了村子。", "error_description": "“一群”是指人的集体量词，写作“一群敌人”；“一条”用于线状长物，不能修饰人，写成“一条敌人”是量词用错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一根敌人悄悄溜进了院子。", "corrected_sentence": "一个敌人悄悄溜进了院子。", "error_description": "“敌人”指人，量词应用“个”，写作“一个敌人”；“根”用于细长的物体，不能修饰人，写成“一根敌人”是量词用错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
