INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39907, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "敌人，指与自己利益对立、试图侵犯或伤害自己一方的人或群体。", "primary_collocate": null, "pronunciation": "dí rén", "ipa": "ti˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "边防部队保护着自己的国家，不让敌人进来。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在战场上遇到了很多敌人。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人从北边来了，大家快跑。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们守在城墙上，等着敌人过来。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这场战争中，他们打败了敌人。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士发现敌人躲在山后面。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军很了解自己的敌人，所以打赢了。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人跑得很快，我们追不上。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把敌人关进了小房子里。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不怕敌人，总是第一个冲上去。", "target_word": "敌人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个敌人", "label": "量词"}, {"form": "敵人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "与自己利益对立、试图侵犯或伤害自己一方的人或群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8dfe5f-92b1-44b2-9118-188d529cc519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39907, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敌人", "is_correct": true, "explanation": "正确。敌人 dí rén 指与自己利益对立、试图侵犯或伤害自己一方的人或群体。"}, {"text": "迷人", "is_correct": false, "explanation": "迷人 mí rén 第一个音节声母为 m，与 dí rén 的 d 不同，意思是有吸引力、令人着迷。"}, {"text": "泥人", "is_correct": false, "explanation": "泥人 ní rén 第一个音节声母为 n，与 dí rén 的 d 不同，意思是用泥捏成的人像。"}, {"text": "十人", "is_correct": false, "explanation": "十人 shí rén 第一个音节声母为 sh，与 dí rén 的 d 不同，意思是十个人。"}], "explanations": {"敌人": "正确。敌人 dí rén 指与自己利益对立、试图侵犯或伤害自己一方的人或群体。", "迷人": "迷人 mí rén 第一个音节声母为 m，与 dí rén 的 d 不同，意思是有吸引力、令人着迷。", "泥人": "泥人 ní rén 第一个音节声母为 n，与 dí rén 的 d 不同，意思是用泥捏成的人像。", "十人": "十人 shí rén 第一个音节声母为 sh，与 dí rén 的 d 不同，意思是十个人。"}, "sentence_index": null, "correct_answer": "敌人"}, "level_3": {"options": [{"text": "敌人", "is_correct": true, "explanation": "正确。“敌人”指想要进来侵犯的一方，与“保护国家，不让……进来”的语境相合。"}, {"text": "同胞", "is_correct": false, "explanation": "语义：同胞是被保护的本国人，不会被挡在国门之外，与句意矛盾。"}, {"text": "人民", "is_correct": false, "explanation": "语义：人民是国家要保护的对象，不能被“不让……进来”，与句意矛盾。"}, {"text": "百姓", "is_correct": false, "explanation": "语义：百姓同为本国民众，不会被挡在国门之外，与“保护国家”的语境矛盾。"}], "explanations": {"敌人": "正确。“敌人”指想要进来侵犯的一方，与“保护国家，不让……进来”的语境相合。", "同胞": "语义：同胞是被保护的本国人，不会被挡在国门之外，与句意矛盾。", "人民": "语义：人民是国家要保护的对象，不能被“不让……进来”，与句意矛盾。", "百姓": "语义：百姓同为本国民众，不会被挡在国门之外，与“保护国家”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "敌人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在篮球比赛中，我们的敌人主动把球传给了我们。", "explanation": "这里应该用〈队友〉之类表达。敌人想要伤害我们，不会主动把球传给我们。"}, {"text": "我的好朋友每次来看我都带着礼物，他是我的敌人。", "explanation": "这里不能用〈敌人〉指关系亲近的人，应用〈知己〉或〈挚友〉之类表达。敌人指与自己利益对立、试图伤害自己的一方。"}, {"text": "我们一起去超市买敌人。", "explanation": "这里应该用〈食物〉之类表达。敌人是人，不能作为购买的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39907, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "敌人", "is_correct": true, "explanation": "正确。敌人 dí rén 指与自己利益对立、试图侵犯或伤害自己一方的人或群体。"}, {"text": "其人", "is_correct": false, "explanation": "其人 qí rén 第一个音节声母为 q，与 dí rén 的 d 不同，意思是那个人。"}, {"text": "吉人", "is_correct": false, "explanation": "吉人 jí rén 第一个音节声母为 j，与 dí rén 的 d 不同，意思是品行善良、吉祥的人。"}, {"text": "词人", "is_correct": false, "explanation": "词人 cí rén 第一个音节声母为 c，与 dí rén 的 d 不同，意思是写词的作者。"}], "explanations": {"敌人": "正确。敌人 dí rén 指与自己利益对立、试图侵犯或伤害自己一方的人或群体。", "其人": "其人 qí rén 第一个音节声母为 q，与 dí rén 的 d 不同，意思是那个人。", "吉人": "吉人 jí rén 第一个音节声母为 j，与 dí rén 的 d 不同，意思是品行善良、吉祥的人。", "词人": "词人 cí rén 第一个音节声母为 c，与 dí rén 的 d 不同，意思是写词的作者。"}, "sentence_index": null, "correct_answer": "敌人"}, "level_3": {"options": [{"text": "敌人", "is_correct": true, "explanation": "正确。“敌人”是与将军对立的一方，“很了解”它并“打赢了”，与句意相合。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：“打赢”需要对手，朋友不是对抗的对象，句子说不通。"}, {"text": "冠军", "is_correct": false, "explanation": "搭配：“冠军”是比赛的获胜者，不能作为“打赢”的对象。"}, {"text": "家人", "is_correct": false, "explanation": "语义：家人不是对抗的一方，与“打赢”的语境矛盾。"}], "explanations": {"敌人": "正确。“敌人”是与将军对立的一方，“很了解”它并“打赢了”，与句意相合。", "朋友": "语义：“打赢”需要对手，朋友不是对抗的对象，句子说不通。", "冠军": "搭配：“冠军”是比赛的获胜者，不能作为“打赢”的对象。", "家人": "语义：家人不是对抗的一方，与“打赢”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "敌人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天把敌人放进冰箱里保存。", "explanation": "这里应该用〈食物〉之类表达。敌人是人，不能像食物一样放进冰箱保存。"}, {"text": "他把敌人借给了朋友。", "explanation": "这里混淆了〈交付〉的转移义。“借”的对象一般是物品，人不能被借给别人，应换为〈交付〉之类表达。"}, {"text": "我的妈妈每天给我做饭，她是我的敌人。", "explanation": "这里应该用〈母亲〉之类表达。敌人指想要伤害我们的一方，不能指每天为我做饭的家人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在山谷里遇到了一只敌人。", "corrected_sentence": "我们在山谷里遇到了一个敌人。", "error_description": "“敌人”指人，量词应用“个”或“名”，写作“一个敌人”；“只”多用于动物或成对的东西，写成“一只敌人”是量词用错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地敌人在山里躲了三天。", "corrected_sentence": "他的敌人在山里躲了三天。", "error_description": "“的”用在代词“他”之后，构成定语“他的”修饰“敌人”，写作“他的敌人”；“地”用于状语，不能修饰名词，写成“他地敌人”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
