INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "象征是代表别的东西的东西。", "primary_collocate": null, "pronunciation": "xiàng zhēng", "ipa": "ɕjɑŋ˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "白鸽是和平的象征。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙是中国人心中的一个象征。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座塔成了这个城市的象征。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色是好运的象征。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰是力量的象征。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国旗是一个国家的象征。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆圆的月亮是团圆的象征。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊猫是中国的象征之一。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰是爱情的象征。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这本书里，大海是自由的象征。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个象征", "label": "量词"}, {"form": "象征性", "label": "复合"}], "register": "书面", "sense_fingerprint": "代表别的事物的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8dfe5f-92b1-44b2-9118-188d529cc519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "象征", "is_correct": true, "explanation": "“象征”作名词，指代表和平的事物，与“白鸽是……的”的格式相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，不能作“和平”的代表。"}, {"text": "火车", "is_correct": false, "explanation": "语义：“火车”是交通工具，与“和平”的象征意义无关。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“和平的”一般修饰抽象事物，不修饰饮料。"}], "explanations": {"象征": "“象征”作名词，指代表和平的事物，与“白鸽是……的”的格式相符。", "厨房": "语义：“厨房”是做饭的地方，不能作“和平”的代表。", "火车": "语义：“火车”是交通工具，与“和平”的象征意义无关。", "饮料": "搭配：“和平的”一般修饰抽象事物，不修饰饮料。"}, "sentence_index": 0, "correct_answer": "象征"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的象征是小明。", "explanation": "这里应该用〈名字〉。象征是代表别的东西的东西，不能用来说人的名字。"}, {"text": "这本书的象征是一百二十页。", "explanation": "这里应该用〈页数〉。象征是代表别的东西的东西，不能用来说书有多少页。"}, {"text": "这个班的象征是四十人。", "explanation": "这里应该用〈人数〉。象征不能用来说班级里有多少人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "象征", "is_correct": true, "explanation": "“象征”指代表团圆的事物，与“圆圆的月亮”的所指相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，不能用来代表“团圆”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是水流，不能指代“团圆”这种抽象意义。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“团圆的”一般修饰人或事情，“团圆的脚步”不成立。"}], "explanations": {"象征": "“象征”指代表团圆的事物，与“圆圆的月亮”的所指相符。", "体重": "语义：“体重”指人或物的重量，不能用来代表“团圆”。", "河流": "语义：“河流”是水流，不能指代“团圆”这种抽象意义。", "脚步": "搭配：“团圆的”一般修饰人或事情，“团圆的脚步”不成立。"}, "sentence_index": 6, "correct_answer": "象征"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的象征很高。", "explanation": "这里应该用〈身高〉。象征是代表别的东西的东西，不能用来说人的身高。"}, {"text": "这张桌子的象征是四条腿。", "explanation": "这里应该用〈有〉。象征不能用来说桌子有几条腿。"}, {"text": "他的象征写得很好。", "explanation": "这里应该用〈字〉。象征是代表别的东西的东西，不能用来说人的字写得好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "荷花是一朵纯洁的象征。", "corrected_sentence": "荷花是一个纯洁的象征。", "error_description": "错误在量词“朵”。“朵”用于花，“象征”前应用“个”，应说“一个纯洁的象征”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这面旗帜是民族的一只象征。", "corrected_sentence": "这面旗帜是民族的一个象征。", "error_description": "错误在量词“只”。“只”用于动物，“象征”前应用“个”，应说“民族的一个象征”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f47a4760-db42-4e19-a3da-bbcc0e0173f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
