INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "造东西时用的办法。", "primary_collocate": null, "pronunciation": "gōng chéng jì shù", "ipa": "kʊŋ ʈʂʰəŋ tɕi ʂu", "syllable_count": 4, "sentences": [{"text": "盖高楼要用很多工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥用的工程技术很特别。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在学新的工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的工程技术比我们的好。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人没有机器，却有好的工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的工程技术很先进。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很擅长工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修隧道需要特别的工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了造房子的工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程技术不好，房子就不结实。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工程技術", "label": "繁体"}, {"form": "工程技术人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "造东西时用的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ae084-1987-4b16-afb3-69290c5fa6f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工程技术", "is_correct": true, "explanation": "“工程技术”是造东西时用的办法，“盖高楼要用很多工程技术”符合句意。"}, {"text": "糖果", "is_correct": false, "explanation": "语义：糖果不是造东西的办法，盖楼不用糖果。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是造东西的办法，句意说不通。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“用很多”后接的多是材料或工具，“游戏”不能这样用于盖楼。"}], "explanations": {"工程技术": "“工程技术”是造东西时用的办法，“盖高楼要用很多工程技术”符合句意。", "糖果": "语义：糖果不是造东西的办法，盖楼不用糖果。", "音乐": "语义：音乐不是造东西的办法，句意说不通。", "游戏": "搭配：“用很多”后接的多是材料或工具，“游戏”不能这样用于盖楼。"}, "sentence_index": 0, "correct_answer": "工程技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的戏曲工程技术很精湛。", "explanation": "这里应该用〈技艺〉。工程技术是造东西时用的办法，戏曲属于表演艺术。"}, {"text": "工程技术正在检查病人。", "explanation": "这里应该用〈医生〉。工程技术是抽象的办法，不能去“检查”病人。"}, {"text": "这项工程技术去年竣工了。", "explanation": "这里应该用〈工程〉。工程指具体的建设项目，才能“竣工”；工程技术是办法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工程技术", "is_correct": true, "explanation": "“工程技术”是一门技能，“他很擅长工程技术”符合句意。"}, {"text": "板凳", "is_correct": false, "explanation": "搭配：“擅长”后接技能或学科，板凳不是技能，“擅长板凳”说不通。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：“擅长”后接技能或学科，大门是建筑部件，“擅长大门”说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“擅长”后接技能或学科，冰箱是家电，“擅长冰箱”说不通。"}], "explanations": {"工程技术": "“工程技术”是一门技能，“他很擅长工程技术”符合句意。", "板凳": "搭配：“擅长”后接技能或学科，板凳不是技能，“擅长板凳”说不通。", "大门": "搭配：“擅长”后接技能或学科，大门是建筑部件，“擅长大门”说不通。", "冰箱": "搭配：“擅长”后接技能或学科，冰箱是家电，“擅长冰箱”说不通。"}, "sentence_index": 6, "correct_answer": "工程技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她唱歌的工程技术很好，声音很美。", "explanation": "这里应该用〈唱功〉。工程技术是造东西时用的办法，唱歌的技巧要用“唱功”。"}, {"text": "他下棋的工程技术很好。", "explanation": "这里应该用〈技巧〉。工程技术用于建造，下棋要说“技巧”。"}, {"text": "她煎蛋的工程技术很好，蛋黄很嫩。", "explanation": "这里应该用〈厨艺〉。工程技术是造东西时用的办法，煎蛋做菜的手艺要用“厨艺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们掌握了一个完整的工程技术。", "corrected_sentence": "他们掌握了一套完整的工程技术。", "error_description": "量词错误：“工程技术”是抽象的技术，可用“套”或“种”计量，不宜用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在大学里研究工程技术们。", "corrected_sentence": "他在大学里研究工程技术。", "error_description": "词形错误：“工程技术”是抽象名词，不能加“们”表示复数，应说“工程技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
