INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39915, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人们在建造房屋、修路、挖水渠等实际工作中使用的科学方法和技能。", "primary_collocate": null, "pronunciation": "gōng chéng jì shù", "ipa": "kʊŋ ʈʂʰəŋ tɕi ʂu", "syllable_count": 4, "sentences": [{"text": "他们修输水渠，靠的是重要的工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥用了很新的工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好工程技术，才能建造大楼。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代人的工程技术也很了不起。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教我们工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去大学学习工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程技术让我们的生活更方便。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修这条长路需要先进的工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的工程技术发展得很快。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有很好的工程技术。", "target_word": "工程技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工程技術", "label": "繁体"}, {"form": "工程技术人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "建造修路等实际工作中的科学方法和技能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ae084-1987-4b16-afb3-69290c5fa6f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39915, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工程技术", "is_correct": true, "explanation": "“工程技术”指建造工作中使用的科学方法和技能，“修输水渠靠的是重要的工程技术”符合句意。"}, {"text": "食物", "is_correct": false, "explanation": "语义：修渠靠的是技术和方法，不是食物，“靠的是重要的食物”说不通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：修渠靠的是技术和方法，不是乐器，“靠的是重要的乐器”说不通。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“手术”要说“做手术”或“进行手术”，不能用来指一种输水的工程方法。"}], "explanations": {"工程技术": "“工程技术”指建造工作中使用的科学方法和技能，“修输水渠靠的是重要的工程技术”符合句意。", "食物": "语义：修渠靠的是技术和方法，不是食物，“靠的是重要的食物”说不通。", "乐器": "语义：修渠靠的是技术和方法，不是乐器，“靠的是重要的乐器”说不通。", "手术": "搭配：“手术”要说“做手术”或“进行手术”，不能用来指一种输水的工程方法。"}, "sentence_index": 0, "correct_answer": "工程技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的书法工程技术很精湛。", "explanation": "这里应该用〈技艺〉。工程技术用于建造工作，书法属于艺术技艺。"}, {"text": "工程技术正在检查大桥。", "explanation": "这里应该用〈工程师〉。工程技术是抽象的办法，不能去“检查”大桥。"}, {"text": "工程技术高高地矗立在河边。", "explanation": "这里应该用〈建筑〉。工程技术是造东西时用的办法和技能，不是能矗立的实物；河边高耸的建成物要用“建筑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39915, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工程技术", "is_correct": true, "explanation": "“工程技术”能让生活更方便，“工程技术让我们的生活更方便”符合句意。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音只会打扰生活，不能让生活更方便。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不能让生活更方便。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“让……更方便”的主语多是功能性的办法或设施，“乐器”不这样搭配。"}], "explanations": {"工程技术": "“工程技术”能让生活更方便，“工程技术让我们的生活更方便”符合句意。", "噪音": "语义：噪音只会打扰生活，不能让生活更方便。", "感冒": "语义：感冒是疾病，不能让生活更方便。", "乐器": "搭配：“让……更方便”的主语多是功能性的办法或设施，“乐器”不这样搭配。"}, "sentence_index": 6, "correct_answer": "工程技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打篮球很有工程技术。", "explanation": "这里应该用〈技巧〉。工程技术用于建造工作，打篮球要说“技巧”。"}, {"text": "她做菜的工程技术很好。", "explanation": "这里应该用〈厨艺〉。工程技术是建造方面的办法，做菜要用“厨艺”。"}, {"text": "这位医生的工程技术很高明。", "explanation": "这里应该用〈医术〉。工程技术用于建造，治病要用“医术”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们运用了一个先进的工程技术。", "corrected_sentence": "工人们运用了一种先进的工程技术。", "error_description": "量词错误：“工程技术”是抽象的技术，前面宜用“种”或“项”，不宜用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们学习了新的工程技术们。", "corrected_sentence": "工人们学习了新的工程技术。", "error_description": "词形错误：“工程技术”是抽象名词，不能加“们”表示复数，应说“工程技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
