INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39916, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "这是一个给家里送水的系统。", "primary_collocate": null, "pronunciation": "gōng shuǐ xì tǒng", "ipa": "kʊŋ˥ ʂweɪ˨˩˦ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "我家的供水系统很简单。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套供水系统把水送到每个房间。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的供水系统坏了，厨房没有水。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子装了一套供水系统。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在修家里的供水系统。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个供水系统可以给三层楼送水。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的小房子没有供水系统，只能去河边打水。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，供水系统里的水会结冰。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的供水系统有一个水泵。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换水管之前，要先关闭家里的供水系统。", "target_word": "供水系统", "complexity_tier": "T3", "furigana": "gōng shuǐ xì tǒng", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "供水系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "给一户人家或一栋房子送水的水管和水泵等装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f5c53d1-4ea1-4d6d-9e6a-58003c554ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "供水系统", "is_correct": true, "explanation": "正确。供水系统指给家庭供水的装置，“我家的供水系统”与句中描述相符。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：地铁站是城市公共交通设施，普通家庭不会拥有，“我家的地铁站”不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人或动物的体型，不能用来形容一套家用供水装置。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不属于家庭所有，“我家的月亮”不通。"}], "explanations": {"供水系统": "正确。供水系统指给家庭供水的装置，“我家的供水系统”与句中描述相符。", "地铁站": "语义：地铁站是城市公共交通设施，普通家庭不会拥有，“我家的地铁站”不通。", "身材": "体貌：身材指人或动物的体型，不能用来形容一套家用供水装置。", "月亮": "语义：月亮是天体，不属于家庭所有，“我家的月亮”不通。"}, "sentence_index": 0, "correct_answer": "供水系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨房里的供水系统可以把牛奶冷藏起来。", "explanation": "这里应该用〈冰箱〉。供水系统负责送水，冷藏牛奶要靠冰箱。"}, {"text": "下雨了，我把供水系统撑开了。", "explanation": "这里应该用〈雨伞〉。撑开的是雨伞，供水系统是送水的设施，不能撑开。"}, {"text": "我爸爸是家里的供水系统，很会修东西。", "explanation": "这里应该用〈师傅〉或〈能手〉。供水系统是设施，指会修东西的人要说“师傅”或“能手”，不能说“供水系统”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "供水系统", "is_correct": true, "explanation": "正确。句中说山上的房子没有供水系统，只能去河边打水，“供水系统”指家里的供水装置，与句意相符。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色指人的面部气色，房子没有脸色，句子不通。"}, {"text": "网络", "is_correct": false, "explanation": "语义：“没有网络，只能去河边打水”逻辑不通，网络与取水没有关联。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：“没有电梯，只能去河边打水”逻辑不通，电梯与取水没有关联。"}], "explanations": {"供水系统": "正确。句中说山上的房子没有供水系统，只能去河边打水，“供水系统”指家里的供水装置，与句意相符。", "脸色": "体貌：脸色指人的面部气色，房子没有脸色，句子不通。", "网络": "语义：“没有网络，只能去河边打水”逻辑不通，网络与取水没有关联。", "电梯": "语义：“没有电梯，只能去河边打水”逻辑不通，电梯与取水没有关联。"}, "sentence_index": 6, "correct_answer": "供水系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "供水系统装在墙边，用来给房间供热。", "explanation": "这里应该用〈暖气片〉。供水系统是送水的，给房间供热要用暖气片。"}, {"text": "供水系统可以用来烤面包。", "explanation": "这里应该用〈烤箱〉。供水系统只负责送水，烤面包要用烤箱。"}, {"text": "供水系统每天都会卖出很多汽油。", "explanation": "这里应该用〈加油站〉。供水系统只负责送水，不卖汽油，卖汽油要说加油站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家的一只供水系统装好了。", "corrected_sentence": "我家的一套供水系统装好了。", "error_description": "量词错误：供水系统是成套的装置，量词应该用“套”，不能用“只”。正确说法是“一套供水系统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根供水系统是去年装的。", "corrected_sentence": "这套供水系统是去年装的。", "error_description": "量词错误：供水系统是成套的装置，量词应该用“套”，不能用“根”。正确说法是“这套供水系统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
