INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85650, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "结构助词，用在定语和中心语之间，表示领属、修饰等关系，也可以用在词语后面构成名词性短语。", "primary_collocate": null, "pronunciation": "de", "ipa": "tə", "syllable_count": 1, "sentences": [{"text": "这本书是我的。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "红的是我的，蓝的是你的。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢吃甜的。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是卖水果的。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是学校新建的图书馆。", "target_word": "的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会说汉语的同学请举手。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌上的苹果是谁的？", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说的话，我都记住了。", "target_word": "的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服太小，我想换大的。", "target_word": "的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习汉语的人越来越多。", "target_word": "的", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "结构助词，连接定语和中心语，或接在词语后构成名词性短语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ae1b019-e3ac-4d0f-b5df-a846d13cad7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "的", "is_correct": true, "explanation": "正确答案：的 de（轻声），结构助词，连接定语和中心语，或构成名词性短语。"}, {"text": "德", "is_correct": false, "explanation": "dé（第二声）与 de（轻声）声调不同，意思是品德。"}, {"text": "特", "is_correct": false, "explanation": "tè（第四声）与 de 声母不同，意思是特别。"}, {"text": "呢", "is_correct": false, "explanation": "ne 与 de 声母不同，意思是语气助词，用在句末。"}, {"text": "吗", "is_correct": false, "explanation": "ma（轻声）与 de 声母不同，意思是疑问语气词，如“好吗”。"}], "explanations": {"的": "正确答案：的 de（轻声），结构助词，连接定语和中心语，或构成名词性短语。", "德": "dé（第二声）与 de（轻声）声调不同，意思是品德。", "特": "tè（第四声）与 de 声母不同，意思是特别。", "呢": "ne 与 de 声母不同，意思是语气助词，用在句末。", "吗": "ma（轻声）与 de 声母不同，意思是疑问语气词，如“好吗”。"}, "sentence_index": null, "correct_answer": "的"}, "level_3": {"options": [{"text": "的", "is_correct": true, "explanation": "正确答案：“我的”指代“我的东西”，构成名词性短语。"}, {"text": "之", "is_correct": false, "explanation": "语域：“之”是文言用法，口语不说“这本书是我之”。"}, {"text": "地", "is_correct": false, "explanation": "配价：“地”修饰动词，“我”后面不能接“地”来指代东西。"}, {"text": "得", "is_correct": false, "explanation": "配价：“得”连接动词和补语，这里没有动词，不能接在“我”后面。"}], "explanations": {"的": "正确答案：“我的”指代“我的东西”，构成名词性短语。", "之": "语域：“之”是文言用法，口语不说“这本书是我之”。", "地": "配价：“地”修饰动词，“我”后面不能接“地”来指代东西。", "得": "配价：“得”连接动词和补语，这里没有动词，不能接在“我”后面。"}, "sentence_index": 0, "correct_answer": "的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是卖水果地。", "explanation": "这里应该用〈的〉。“地”用于修饰动词的状语，构成名词性短语要用“的”。"}, {"text": "他卖水果卖地很快。", "explanation": "这里应该用〈得〉。“卖”和“很快”之间是补语，要用“得”，不用“地”。"}, {"text": "他是的卖水果。", "explanation": "这里多用了“的”。“的”不能放在动词“卖”前面，应说“他卖水果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85650, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "的", "is_correct": true, "explanation": "正确答案：的 de（轻声），结构助词，连接定语和中心语，或构成名词性短语。"}, {"text": "了", "is_correct": false, "explanation": "le 与 de 声母不同，意思是动态助词，表示完成或变化。"}, {"text": "么", "is_correct": false, "explanation": "me 与 de 声母不同，意思是疑问助词，如“什么”里的“么”。"}, {"text": "个", "is_correct": false, "explanation": "gè（第四声）与 de 声母和声调都不同，意思是量词，用于人或事物。"}, {"text": "弟", "is_correct": false, "explanation": "dì（第四声）与 de 韵母和声调都不同，意思是弟弟。"}], "explanations": {"的": "正确答案：的 de（轻声），结构助词，连接定语和中心语，或构成名词性短语。", "了": "le 与 de 声母不同，意思是动态助词，表示完成或变化。", "么": "me 与 de 声母不同，意思是疑问助词，如“什么”里的“么”。", "个": "gè（第四声）与 de 声母和声调都不同，意思是量词，用于人或事物。", "弟": "dì（第四声）与 de 韵母和声调都不同，意思是弟弟。"}, "sentence_index": null, "correct_answer": "的"}, "level_3": {"options": [{"text": "的", "is_correct": true, "explanation": "正确答案：“谁的”指代“谁的东西”，构成疑问性名词短语。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”表示完成，不能接在疑问代词“谁”后面作句末。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示状态，“是谁着”不成立，句子不能这样问。"}, {"text": "么", "is_correct": false, "explanation": "配价：“么”不能接在疑问代词“谁”后面作句末，这里不成立。"}], "explanations": {"的": "正确答案：“谁的”指代“谁的东西”，构成疑问性名词短语。", "了": "体貌：“了”表示完成，不能接在疑问代词“谁”后面作句末。", "着": "体貌：“着”表示状态，“是谁着”不成立，句子不能这样问。", "么": "配价：“么”不能接在疑问代词“谁”后面作句末，这里不成立。"}, "sentence_index": 6, "correct_answer": "的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的常常卖水果。", "explanation": "“的”后面要接名词中心语，“常常”是副词，不能用“的”。"}, {"text": "我们班有三的学生学习汉语。", "explanation": "这里应该用量词〈个〉。数词和名词之间要用量词，“的”不能代替量词。"}, {"text": "他的很高兴。", "explanation": "“的”后面不能接形容词谓语，这里应说“他很高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班会说汉语的的人很多。", "corrected_sentence": "我们班会说汉语的人很多。", "error_description": "“的”重复：“会说汉语的人”中只用一个“的”，多写一个“的”不通顺，应为“我们班会说汉语的人很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一本很有的用书。", "corrected_sentence": "这是一本很有用的书。", "error_description": "“的”位置错误。“很有的用书”应为“很有用的书”：“的”要放在修饰成分“很有用”之后，再接中心语“书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
