INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85655, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“我”就是说话的这个人，也就是自己。", "primary_collocate": null, "pronunciation": "wǒ", "ipa": "wɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "你好，我叫小王，是新来的同学。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我昨天为什么没来。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书不是你的，是我买的。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说他累了，可是我一点也不累。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你等一下，我去拿个东西。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，我没有带伞，你呢？", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今年二十岁，我弟弟十五岁。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友给我打电话，说他明天来。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我自己做饭，不想吃外面的菜。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别担心，我会照顾好自己。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "我们", "label": "复数"}, {"form": "我的", "label": "所属形式"}], "register": "中性", "sense_fingerprint": "说话人用来指称自己的第一人称单数代词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39e035a-dda2-4ec6-9ffc-89dfa7d4a654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85655, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "我", "is_correct": true, "explanation": "正确：我（wǒ，第三声），指说话人自己。"}, {"text": "窝", "is_correct": false, "explanation": "wō（第一声）与 wǒ（第三声）声调不同，意思是窝巢。"}, {"text": "握", "is_correct": false, "explanation": "wò（第四声）与 wǒ（第三声）声调不同，意思是握住。"}, {"text": "卧", "is_correct": false, "explanation": "wò（第四声）与 wǒ（第三声）声调不同，意思是躺下。"}, {"text": "蜗", "is_correct": false, "explanation": "wō（第一声）与 wǒ（第三声）声调不同，意思是蜗牛。"}], "explanations": {"我": "正确：我（wǒ，第三声），指说话人自己。", "窝": "wō（第一声）与 wǒ（第三声）声调不同，意思是窝巢。", "握": "wò（第四声）与 wǒ（第三声）声调不同，意思是握住。", "卧": "wò（第四声）与 wǒ（第三声）声调不同，意思是躺下。", "蜗": "wō（第一声）与 wǒ（第三声）声调不同，意思是蜗牛。"}, "sentence_index": null, "correct_answer": "我"}, "level_3": {"options": [{"text": "我", "is_correct": true, "explanation": "我：代词，指说话人自己，作“叫”的主语。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指物或动物，不能用来指正在自我介绍的人。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指多人，不能与“叫小王”这样的单人自我介绍搭配。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”虽指本人，但在这里说“自己叫小王”，意思不通。"}], "explanations": {"我": "我：代词，指说话人自己，作“叫”的主语。", "它": "语义：“它”指物或动物，不能用来指正在自我介绍的人。", "大家": "搭配：“大家”指多人，不能与“叫小王”这样的单人自我介绍搭配。", "自己": "语义：“自己”虽指本人，但在这里说“自己叫小王”，意思不通。"}, "sentence_index": 0, "correct_answer": "我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一起出发吧，你们先等一下。", "explanation": "这里应该用〈咱们〉。劝对方同行时要包括听话人，用“我”就把对方排除在外了。"}, {"text": "我三个人一起去看电影。", "explanation": "这里应该用〈我们〉。“三个人”指多人，“我”只指说话的这一个人，二者不能搭配。"}, {"text": "老师问我：“我昨天为什么没来？”", "explanation": "这里是老师问学生，应该用〈你〉。“我”指说话人自己，此处指的是对方，用错了人称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85655, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "我", "is_correct": true, "explanation": "正确：我（wǒ，第三声），指说话人自己。"}, {"text": "五", "is_correct": false, "explanation": "wǔ（第三声）与 wǒ（第三声）韵母不同，意思是数字五。"}, {"text": "武", "is_correct": false, "explanation": "wǔ（第三声）与 wǒ（第三声）韵母不同，意思是武力。"}, {"text": "瓦", "is_correct": false, "explanation": "wǎ（第三声）与 wǒ（第三声）韵母不同，意思是瓦片。"}], "explanations": {"我": "正确：我（wǒ，第三声），指说话人自己。", "五": "wǔ（第三声）与 wǒ（第三声）韵母不同，意思是数字五。", "武": "wǔ（第三声）与 wǒ（第三声）韵母不同，意思是武力。", "瓦": "wǎ（第三声）与 wǒ（第三声）韵母不同，意思是瓦片。"}, "sentence_index": null, "correct_answer": "我"}, "level_3": {"options": [{"text": "我", "is_correct": true, "explanation": "我：代词，指说话人自己，作“今年二十岁”的主语。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”指多人，与单独一人的年龄信息“今年二十岁”不符。"}, {"text": "此", "is_correct": false, "explanation": "语域：“此”是书面词，口语叙述中不能这样用，也不能指人。"}, {"text": "其", "is_correct": false, "explanation": "语域：“其”是书面语中的指代词，用在这里很不自然，口语中不这样说。"}], "explanations": {"我": "我：代词，指说话人自己，作“今年二十岁”的主语。", "我们": "语义：“我们”指多人，与单独一人的年龄信息“今年二十岁”不符。", "此": "语域：“此”是书面词，口语叙述中不能这样用，也不能指人。", "其": "语域：“其”是书面语中的指代词，用在这里很不自然，口语中不这样说。"}, "sentence_index": 6, "correct_answer": "我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和我都是学生。", "explanation": "这里应该用〈你〉。“我和我”指同一个人，并列时要说两个人，应说“我和你”。"}, {"text": "我每个人都要做好准备。", "explanation": "这里应该用〈我们〉。“每个人”指一群人，前面的“我”是单数，二者不能配合，应说“我们每个人”。"}, {"text": "爸爸问我：“我怎么还没吃饭？”", "explanation": "这里是爸爸问孩子，应该用〈你〉。“我”指说话人自己，此处指的是对方，用错了人称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一个人去。", "corrected_sentence": "我一个人去。", "error_description": "错误：“我们一个人”，“我们”是复数，不能与“一个人”搭配。正确：“我一个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我书。", "corrected_sentence": "这是我的书。", "error_description": "错误：“我书”，“我”作定语修饰名词时要加“的”。正确：“我的书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
