INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85660, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第二人称代词，指称听话的对方。", "primary_collocate": null, "pronunciation": "nǐ", "ipa": "ni˨˩˦", "syllable_count": 1, "sentences": [{"text": "你叫什么名字？", "target_word": "你", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你今天想吃什么？", "target_word": "你", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谢谢你帮我找到手机。", "target_word": "你", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你住在哪儿？", "target_word": "你", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我很想你。", "target_word": "你", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书是给你的。", "target_word": "你", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看，天上有一只小鸟。", "target_word": "你", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师问你，昨天为什么没来？", "target_word": "你", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的帽子很漂亮。", "target_word": "你", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们明天去公园，你去吗？", "target_word": "你", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "你们", "label": "复数"}, {"form": "您", "label": "敬称"}, {"form": "你的", "label": "所属形式"}], "register": "通用", "sense_fingerprint": "第二人称代词，称呼正在听自己说话的对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0a5167-b7a0-4535-b648-c4ab11c8f416') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85660, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "你", "is_correct": true, "explanation": "nǐ（第三声）是第二人称代词，指正在听话的对方。"}, {"text": "里", "is_correct": false, "explanation": "lǐ 与 nǐ 声母不同（l/n），意思是里面。"}, {"text": "米", "is_correct": false, "explanation": "mǐ 与 nǐ 声母不同（m/n），意思是大米。"}, {"text": "泥", "is_correct": false, "explanation": "ní 与 nǐ 声调不同（第二声），意思是泥土。"}, {"text": "努", "is_correct": false, "explanation": "nǔ 与 nǐ 韵母不同（u/i），意思是努力。"}], "explanations": {"你": "nǐ（第三声）是第二人称代词，指正在听话的对方。", "里": "lǐ 与 nǐ 声母不同（l/n），意思是里面。", "米": "mǐ 与 nǐ 声母不同（m/n），意思是大米。", "泥": "ní 与 nǐ 声调不同（第二声），意思是泥土。", "努": "nǔ 与 nǐ 韵母不同（u/i），意思是努力。"}, "sentence_index": null, "correct_answer": "你"}, "level_3": {"options": [{"text": "你", "is_correct": true, "explanation": "“你”指正在听话的人，与“叫什么名字”的提问对象一致。"}, {"text": "我", "is_correct": false, "explanation": "语义：这是问听话人的名字，“我”指说话者自己，问自己的名字不合语境。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括说话者在内，向对方发问时不能这样指代提问对象。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”指说话者本人，不能作为向对方提问的主语。"}], "explanations": {"你": "“你”指正在听话的人，与“叫什么名字”的提问对象一致。", "我": "语义：这是问听话人的名字，“我”指说话者自己，问自己的名字不合语境。", "咱们": "语义：“咱们”包括说话者在内，向对方发问时不能这样指代提问对象。", "自己": "搭配：“自己”指说话者本人，不能作为向对方提问的主语。"}, "sentence_index": 0, "correct_answer": "你"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树很高，你发芽了。", "explanation": "这里应该用〈它〉。“你”只指人，指树要用“它”。"}, {"text": "我买了一台电脑，你很快就坏了。", "explanation": "这里应该用〈它〉。“你”只指人，指电脑要用“它”。"}, {"text": "我买了一本书，你很贵。", "explanation": "这里应用“它”。“你”只指人，指书要用“它”，不能说“你很贵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85660, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "你", "is_correct": true, "explanation": "nǐ（第三声）是第二人称代词，指正在听话的对方。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ 与 nǐ 声母不同（l/n），意思是礼物。"}, {"text": "女", "is_correct": false, "explanation": "nǚ 与 nǐ 韵母不同（ü/i），意思是女性。"}, {"text": "逆", "is_correct": false, "explanation": "nì 与 nǐ 声调不同（第四声），意思是逆向。"}, {"text": "尼", "is_correct": false, "explanation": "ní 与 nǐ 声调不同（第二声），意思是尼姑。"}], "explanations": {"你": "nǐ（第三声）是第二人称代词，指正在听话的对方。", "礼": "lǐ 与 nǐ 声母不同（l/n），意思是礼物。", "女": "nǚ 与 nǐ 韵母不同（ü/i），意思是女性。", "逆": "nì 与 nǐ 声调不同（第四声），意思是逆向。", "尼": "ní 与 nǐ 声调不同（第二声），意思是尼姑。"}, "sentence_index": null, "correct_answer": "你"}, "level_3": {"options": [{"text": "你", "is_correct": true, "explanation": "“你”指正在听话的人，这里用来招呼对方看天上的小鸟。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指物或动物，不能用来招呼听话的人去看天上的小鸟。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，会把句子变成疑问，与后面的陈述不连贯。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”是物，不能看天上的小鸟，句子不通。"}], "explanations": {"你": "“你”指正在听话的人，这里用来招呼对方看天上的小鸟。", "它": "语义：“它”指物或动物，不能用来招呼听话的人去看天上的小鸟。", "谁": "语义：“谁”是疑问代词，会把句子变成疑问，与后面的陈述不连贯。", "书": "语义：“书”是物，不能看天上的小鸟，句子不通。"}, "sentence_index": 6, "correct_answer": "你"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "陛下，你请坐。", "explanation": "这里应用“您”。对皇帝这样的尊者说话要用敬称“您”，用“你”极不得体。"}, {"text": "这位院士，你请坐。", "explanation": "这里应用“您”。对院士等德高望重的人说话用“您”，用“你”显得失礼。"}, {"text": "太后，你请坐。", "explanation": "这里应用“您”。对太后等尊贵长辈说话要用敬称“您”，不能用“你”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是你杯子。", "corrected_sentence": "这是你的杯子。", "error_description": "“你”作定语表示所属时，后面要加“的”。应说“你的杯子”，不能说“你杯子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王，你们今天来吗？", "corrected_sentence": "小王，你今天来吗？", "error_description": "“你们”是复数，只对几个人说话时用；只对一个人说话应用“你”，应说“你今天来吗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
