INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85669, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示以年计的一段较长时间，如“住了三年”“认识很多年”。", "primary_collocate": null, "pronunciation": "nián", "ipa": "njɛn˧˥", "syllable_count": 1, "sentences": [{"text": "我在北京住了三年。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了两年中文。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了一年，终于等到了回信。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在这所学校学习了很多年，终于毕业了。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路修了好几年。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们认识很多年了。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年很长，也很短。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她已经三年没回家了。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我花了好几年，才学会了做饭。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在这个村子里生活了七十年。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年年", "label": "重叠"}, {"form": "过年", "label": "复合"}], "register": "通用", "sense_fingerprint": "以年计的较长时间跨度，不指日历年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ddbf6c1-65b5-4c28-9abb-1fe3d7a1f8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85669, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "年", "is_correct": true, "explanation": "年 nián：一年那么长的一段时间，是本题正确答案。"}, {"text": "连", "is_correct": false, "explanation": "连 lián 与 nián 声母不同（l 与 n），意思是连接。"}, {"text": "练", "is_correct": false, "explanation": "练 liàn 与 nián 声母不同（l 与 n），声调也不同（第四声），意思是练习。"}, {"text": "脸", "is_correct": false, "explanation": "脸 liǎn 与 nián 声母不同（l 与 n），声调也不同（第三声），意思是脸。"}, {"text": "念", "is_correct": false, "explanation": "念 niàn 与 nián 声调不同（第四声与第二声），意思是朗读。"}], "explanations": {"年": "年 nián：一年那么长的一段时间，是本题正确答案。", "连": "连 lián 与 nián 声母不同（l 与 n），意思是连接。", "练": "练 liàn 与 nián 声母不同（l 与 n），声调也不同（第四声），意思是练习。", "脸": "脸 liǎn 与 nián 声母不同（l 与 n），声调也不同（第三声），意思是脸。", "念": "念 niàn 与 nián 声调不同（第四声与第二声），意思是朗读。"}, "sentence_index": null, "correct_answer": "年"}, "level_3": {"options": [{"text": "岁", "is_correct": false, "explanation": "语义：“岁”指年龄，不能用来计算住在北京的时间。"}, {"text": "年", "is_correct": true, "explanation": "年：正确答案，表示时间长度，与“住了三”搭配。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：“公斤”是重量单位，不能用来计量住的时间。"}, {"text": "块", "is_correct": false, "explanation": "搭配：“块”用于块状物或钱，不能与“住了三”搭配计量时间。"}], "explanations": {"岁": "语义：“岁”指年龄，不能用来计算住在北京的时间。", "年": "年：正确答案，表示时间长度，与“住了三”搭配。", "公斤": "语义：“公斤”是重量单位，不能用来计量住的时间。", "块": "搭配：“块”用于块状物或钱，不能与“住了三”搭配计量时间。"}, "sentence_index": 0, "correct_answer": "年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "放假的年我回家了。", "explanation": "这里应该用〈时候〉。“年”指一段较长的时间，不能指“放假”这样的某个时刻。"}, {"text": "我的生日在八年。", "explanation": "这里应该用〈月〉。“年”不能指某一个月份，“八月”才是月份。"}, {"text": "我七年到家。", "explanation": "这里应该用〈点钟〉。“年”不能表示具体的时刻，到家的时间要说“七点钟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85669, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "年", "is_correct": true, "explanation": "年 nián：一年那么长的一段时间，是本题正确答案。"}, {"text": "联", "is_correct": false, "explanation": "联 lián 与 nián 声母不同（l 与 n），意思是联系。"}, {"text": "恋", "is_correct": false, "explanation": "恋 liàn 与 nián 声母不同（l 与 n），声调也不同（第四声），意思是恋爱。"}, {"text": "碾", "is_correct": false, "explanation": "碾 niǎn 与 nián 声调不同（第三声与第二声），意思是用碾子压。"}], "explanations": {"年": "年 nián：一年那么长的一段时间，是本题正确答案。", "联": "联 lián 与 nián 声母不同（l 与 n），意思是联系。", "恋": "恋 liàn 与 nián 声母不同（l 与 n），声调也不同（第四声），意思是恋爱。", "碾": "碾 niǎn 与 nián 声调不同（第三声与第二声），意思是用碾子压。"}, "sentence_index": null, "correct_answer": "年"}, "level_3": {"options": [{"text": "斤", "is_correct": false, "explanation": "语义：“斤”是重量单位，不能指一段很长或很短的时间。"}, {"text": "元", "is_correct": false, "explanation": "语义：“元”是货币单位，不能用“很长，也很短”来评价。"}, {"text": "年", "is_correct": true, "explanation": "年：正确答案，指一段时间，可以说“一年很长，也很短”。"}, {"text": "人", "is_correct": false, "explanation": "配价：“很长，也很短”评价的是时间，“人”不能作为这个评价的对象。"}], "explanations": {"斤": "语义：“斤”是重量单位，不能指一段很长或很短的时间。", "元": "语义：“元”是货币单位，不能用“很长，也很短”来评价。", "年": "年：正确答案，指一段时间，可以说“一年很长，也很短”。", "人": "配价：“很长，也很短”评价的是时间，“人”不能作为这个评价的对象。"}, "sentence_index": 6, "correct_answer": "年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今年十八年了。", "explanation": "这里应该用〈岁〉。表示年龄要用“岁”，“年”表示时间的长度。"}, {"text": "我们买了一年椅子。", "explanation": "这里应该用〈把〉。“年”是时间单位，不能用来计量椅子，椅子要用量词“把”。"}, {"text": "这年课很长。", "explanation": "这里应该用〈节〉。“节”指一段课堂时间，“年”不能指一节课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在国外留学了三个年。", "corrected_sentence": "他在国外留学了三年。", "error_description": "错误：“三个年”；正确：“三年”。表示时间长度的“年”前面不加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间房子空了一多年。", "corrected_sentence": "这间房子空了一年多。", "error_description": "错误：“一多年”；正确：“一年多”。“多”应放在“年”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
