INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的妹妹在一九九九个年出生。", "corrected_sentence": "我的妹妹在一九九九年出生。", "error_description": "错误：“个”；正确：去掉“个”。年份后面的“年”前面不加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们结婚已经年两多了。", "corrected_sentence": "他们结婚已经两年多了。", "error_description": "错误：“年两多”；正确：“两年多”。数量词“两”要放在“年”前面，“多”放在“年”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
