INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85673, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“对”是说脸或动作朝着某个人或某样东西。", "primary_collocate": null, "pronunciation": "duì", "ipa": "tweɪ̯˥˩", "syllable_count": 1, "sentences": [{"text": "他对我笑了笑。", "target_word": "对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗对我摇尾巴。", "target_word": "对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对着镜子画画。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对着我挥手。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你对着我看。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对孩子点点头。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机对我们招手。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对着手机大声说话。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩对妈妈做了个鬼脸。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对着大家鞠了一个躬。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对：脸或动作朝向某人某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20eaa319-c57d-469c-b2b7-b9adb94399fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85673, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对", "is_correct": true, "explanation": "对（duì）：介词，表示脸或动作朝向某人或某物。"}, {"text": "堆", "is_correct": false, "explanation": "堆（duī）与对（duì）声调不同（第一声与第四声），意思是堆积。"}, {"text": "退", "is_correct": false, "explanation": "退（tuì）与对（duì）声母不同（t 与 d），意思是后退。"}, {"text": "推", "is_correct": false, "explanation": "推（tuī）与对（duì）声母与声调都不同，意思是用力向前移动。"}, {"text": "最", "is_correct": false, "explanation": "最（zuì）与对（duì）声母不同（z 与 d），意思是程度最高。"}], "explanations": {"对": "对（duì）：介词，表示脸或动作朝向某人或某物。", "堆": "堆（duī）与对（duì）声调不同（第一声与第四声），意思是堆积。", "退": "退（tuì）与对（duì）声母不同（t 与 d），意思是后退。", "推": "推（tuī）与对（duì）声母与声调都不同，意思是用力向前移动。", "最": "最（zuì）与对（duì）声母不同（z 与 d），意思是程度最高。"}, "sentence_index": null, "correct_answer": "对"}, "level_3": {"options": [{"text": "对", "is_correct": true, "explanation": "对：引出笑的朝向对象，“对我笑”是通顺的说法。"}, {"text": "从", "is_correct": false, "explanation": "配价：“笑”引出对象用“对”或“向”，不能用“从”引出。"}, {"text": "在", "is_correct": false, "explanation": "语义：“在”引出处所，“我”不是笑的场所，句子不通。"}, {"text": "用", "is_correct": false, "explanation": "语义：“用”引出凭借或工具，“我”不能作为笑的工具，句子不通。"}], "explanations": {"对": "对：引出笑的朝向对象，“对我笑”是通顺的说法。", "从": "配价：“笑”引出对象用“对”或“向”，不能用“从”引出。", "在": "语义：“在”引出处所，“我”不是笑的场所，句子不通。", "用": "语义：“用”引出凭借或工具，“我”不能作为笑的工具，句子不通。"}, "sentence_index": 0, "correct_answer": "对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一对西瓜。", "explanation": "这里的“对”是量词，指成双的东西，与“西瓜”不搭，不是介词“对”的用法。"}, {"text": "我们对北京出发去上海。", "explanation": "这里应该用〈从〉。“对”引出朝向或针对的对象，不能表示出发的地点。"}, {"text": "我们对五点见面。", "explanation": "这里应该用〈在〉。“对”只能引出人或事物，不能引出时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85673, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "对", "is_correct": true, "explanation": "对（duì）：介词，表示朝向或针对某人某物。"}, {"text": "碎", "is_correct": false, "explanation": "碎（suì）与对（duì）声母不同（s 与 d），意思是破碎。"}, {"text": "翠", "is_correct": false, "explanation": "翠（cuì）与对（duì）声母不同（c 与 d），意思是翠绿色。"}, {"text": "罪", "is_correct": false, "explanation": "罪（zuì）与对（duì）声母不同（z 与 d），意思是罪过。"}, {"text": "随", "is_correct": false, "explanation": "随（suí）与对（duì）声母与声调都不同，意思是跟着。"}], "explanations": {"对": "对（duì）：介词，表示朝向或针对某人某物。", "碎": "碎（suì）与对（duì）声母不同（s 与 d），意思是破碎。", "翠": "翠（cuì）与对（duì）声母不同（c 与 d），意思是翠绿色。", "罪": "罪（zuì）与对（duì）声母不同（z 与 d），意思是罪过。", "随": "随（suí）与对（duì）声母与声调都不同，意思是跟着。"}, "sentence_index": null, "correct_answer": "对"}, "level_3": {"options": [{"text": "对", "is_correct": true, "explanation": "对：引出招手的朝向对象，“对我们招手”是通顺的说法。"}, {"text": "往", "is_correct": false, "explanation": "语义：“往”引出移动的方向，“招手”不是移动，句子不通。"}, {"text": "按", "is_correct": false, "explanation": "语义：“按”引出依据，不能说“按我们招手”，句意不通。"}, {"text": "由", "is_correct": false, "explanation": "配价：“由”引出施事或依据，不能引出“招手”的对象“我们”。"}], "explanations": {"对": "对：引出招手的朝向对象，“对我们招手”是通顺的说法。", "往": "语义：“往”引出移动的方向，“招手”不是移动，句子不通。", "按": "语义：“按”引出依据，不能说“按我们招手”，句意不通。", "由": "配价：“由”引出施事或依据，不能引出“招手”的对象“我们”。"}, "sentence_index": 6, "correct_answer": "对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对朋友做了一顿饭。", "explanation": "这里应该用〈为〉。“对”引出朝向或针对的对象，不能表示为某人做事。"}, {"text": "他对前走了两步。", "explanation": "这里应该用〈向〉。“对”表示朝向人或事物，不能用来表示向前移动的方向。"}, {"text": "我对朋友一起去公园。", "explanation": "这里应该用〈跟〉。“对”引出针对的对象，不能表示一起行动的伙伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对了窗户招手。", "corrected_sentence": "他对着窗户招手。", "error_description": "错误：“对着”是固定格式，“着”不能换成“了”，写成“对了窗户”不通，正确为“他对着窗户招手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他着对镜头微笑。", "corrected_sentence": "他对着镜头微笑。", "error_description": "错误：“对着”是一个整体，“着”必须紧跟在“对”后面。写成“着对”不通，正确为“对着镜头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
