INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85677, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“上”是说在高一点的地方，或者在东西的表面。", "primary_collocate": null, "pronunciation": "shàng", "ipa": "ʂaŋ˥˩", "syllable_count": 1, "sentences": [{"text": "猫在沙发上睡觉。", "target_word": "上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "墙上挂着一张地图。", "target_word": "上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上有很多星星。", "target_word": "上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她脸上有笑容。", "target_word": "上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上放了一杯热茶。", "target_word": "上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在地图上找到了我们的学校。", "target_word": "上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树上有一只小鸟，它在唱歌。", "target_word": "上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水面上漂着几片绿叶。", "target_word": "上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了今天的日期。", "target_word": "上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "床上放着我的书包，不要动它。", "target_word": "上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上面", "label": "复合"}, {"form": "上边", "label": "复合"}], "register": "中性", "sense_fingerprint": "方位词：较高的位置或东西的表面（桌子上）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 漂 (Zipf 3.31), 几片 (Zipf 3.15), 绿叶 (Zipf 3.12)']::text[], 'b8131328-20b4-4215-a0e0-a53110e45ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85677, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上", "is_correct": true, "explanation": "正确答案。“上”（shàng，第四声）指在高处或物体表面。"}, {"text": "伤", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是伤害。"}, {"text": "商", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是商业、商量。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng（第三声）与 shàng（第四声）声调不同，意思是欣赏、奖赏。"}, {"text": "丧", "is_correct": false, "explanation": "sàng（第四声）与 shàng 声母不同（s 与 sh），韵母与声调相同，意思是丧事、丧失。"}, {"text": "唱", "is_correct": false, "explanation": "chàng 与 shàng 声母不同（ch 与 sh），声调相同，意思是唱歌。"}], "explanations": {"上": "正确答案。“上”（shàng，第四声）指在高处或物体表面。", "伤": "shāng（第一声）与 shàng（第四声）声调不同，意思是伤害。", "商": "shāng（第一声）与 shàng（第四声）声调不同，意思是商业、商量。", "赏": "shǎng（第三声）与 shàng（第四声）声调不同，意思是欣赏、奖赏。", "丧": "sàng（第四声）与 shàng 声母不同（s 与 sh），韵母与声调相同，意思是丧事、丧失。", "唱": "chàng 与 shàng 声母不同（ch 与 sh），声调相同，意思是唱歌。"}, "sentence_index": null, "correct_answer": "上"}, "level_3": {"options": [{"text": "上", "is_correct": true, "explanation": "“上”表示在沙发的表面，猫趴着睡，符合句意。"}, {"text": "之间", "is_correct": false, "explanation": "配价：“之间”要求两个或以上的对象，句中只有一张沙发，不能说“沙发之间”。"}, {"text": "之中", "is_correct": false, "explanation": "语域：“沙发之中”偏书面，口语说“沙发里”或“沙发上”。"}, {"text": "内", "is_correct": false, "explanation": "语域：“沙发内”属书面语，此处的口语语境应说“上”。"}], "explanations": {"上": "“上”表示在沙发的表面，猫趴着睡，符合句意。", "之间": "配价：“之间”要求两个或以上的对象，句中只有一张沙发，不能说“沙发之间”。", "之中": "语域：“沙发之中”偏书面，口语说“沙发里”或“沙发上”。", "内": "语域：“沙发内”属书面语，此处的口语语境应说“上”。"}, "sentence_index": 0, "correct_answer": "上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他上了公交车，去了市中心。", "explanation": "这里的“上”表示“登上、乘坐”，指进入交通工具，不表示位置或表面。"}, {"text": "我上个月去了北京。", "explanation": "这里的“上”表示时间，指过去的一个月，不表示位置或表面。"}, {"text": "这件事上我们已经达成了一致。", "explanation": "这里的“上”表示“在……方面”，不表示位置或表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3759b3a1-4b2d-47f6-96ea-4217dde1ffe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85677, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "上", "is_correct": true, "explanation": "正确答案。“上”（shàng，第四声）指在高处或物体表面。"}, {"text": "扇", "is_correct": false, "explanation": "shàn 与 shàng 韵母不同（an 与 ang），声调相同，意思是扇子。"}, {"text": "伤", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是伤害。"}, {"text": "让", "is_correct": false, "explanation": "ràng 与 shàng 声母不同（r 与 sh），声调相同，意思是让。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng（第三声）与 shàng（第四声）声调不同，意思是欣赏、奖赏。"}, {"text": "丧", "is_correct": false, "explanation": "sàng（第四声）与 shàng 声母不同（s 与 sh），韵母与声调相同，意思是丧事、丧失。"}], "explanations": {"上": "正确答案。“上”（shàng，第四声）指在高处或物体表面。", "扇": "shàn 与 shàng 韵母不同（an 与 ang），声调相同，意思是扇子。", "伤": "shāng（第一声）与 shàng（第四声）声调不同，意思是伤害。", "让": "ràng 与 shàng 声母不同（r 与 sh），声调相同，意思是让。", "赏": "shǎng（第三声）与 shàng（第四声）声调不同，意思是欣赏、奖赏。", "丧": "sàng（第四声）与 shàng 声母不同（s 与 sh），韵母与声调相同，意思是丧事、丧失。"}, "sentence_index": null, "correct_answer": "上"}, "level_3": {"options": [{"text": "上", "is_correct": true, "explanation": "“树上”表示在树的枝头，与“有一只小鸟”搭配自然。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“之前”指时间上的先后或正面的方向，与树的空间位置不合。"}, {"text": "之外", "is_correct": false, "explanation": "语域：“树之外”偏书面，且指树的外面，与“树上有鸟”的语境不符。"}, {"text": "之旁", "is_correct": false, "explanation": "语域：“之旁”偏书面，口语在此处要说“上”或“边”，与句子的口语语境不合。"}], "explanations": {"上": "“树上”表示在树的枝头，与“有一只小鸟”搭配自然。", "之前": "语义：“之前”指时间上的先后或正面的方向，与树的空间位置不合。", "之外": "语域：“树之外”偏书面，且指树的外面，与“树上有鸟”的语境不符。", "之旁": "语域：“之旁”偏书面，口语在此处要说“上”或“边”，与句子的口语语境不合。"}, "sentence_index": 6, "correct_answer": "上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他已经上了年纪，走路比以前慢了。", "explanation": "这里的“上”属于“上年纪”，表示年岁变大，不表示位置或表面。"}, {"text": "我每天七点上班。", "explanation": "这里的“上”是“去工作”的意思，不表示位置或表面。"}, {"text": "我刚上楼去找妈妈。", "explanation": "这里的“上”表示向高处移动（上楼），属于方向用法，不表示位置或表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3759b3a1-4b2d-47f6-96ea-4217dde1ffe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书架的上摆着一排书。", "corrected_sentence": "书架上摆着一排书。", "error_description": "错误在“上”前面加了“的”。应说“书架上”，或说“书架的上面”。单音节方位词“上”直接放在“的”后面并不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3759b3a1-4b2d-47f6-96ea-4217dde1ffe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
