INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吗", "is_correct": true, "explanation": "ma（轻声）是本词，句末语气助词，表示疑问。"}, {"text": "呢", "is_correct": false, "explanation": "ne（轻声）与 ma 声母不同（n 与 m），是语气助词。"}, {"text": "码", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是号码。"}, {"text": "蚂", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是蚂蚁。"}], "explanations": {"吗": "ma（轻声）是本词，句末语气助词，表示疑问。", "呢": "ne（轻声）与 ma 声母不同（n 与 m），是语气助词。", "码": "mǎ（第三声）与 ma（轻声）声调不同，意思是号码。", "蚂": "mǎ（第三声）与 ma（轻声）声调不同，意思是蚂蚁。"}, "sentence_index": null, "correct_answer": "吗"}, "level_3": {"options": [{"text": "吗", "is_correct": true, "explanation": "吗：句末语气助词，表示疑问。"}, {"text": "了", "is_correct": false, "explanation": "体貌：了表示完成或变化，问句问的是他现在在不在，不用“了”。"}, {"text": "着", "is_correct": false, "explanation": "体貌：着表示状态持续，“在家着”不能用来提问是非。"}, {"text": "地", "is_correct": false, "explanation": "语义：地是结构助词，不能用在句末。"}], "explanations": {"吗": "吗：句末语气助词，表示疑问。", "了": "体貌：了表示完成或变化，问句问的是他现在在不在，不用“了”。", "着": "体貌：着表示状态持续，“在家着”不能用来提问是非。", "地": "语义：地是结构助词，不能用在句末。"}, "sentence_index": 0, "correct_answer": "吗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "真漂亮吗！", "explanation": "这里应该用〈啊〉。表示赞叹要用“啊”，“吗”只表示疑问，不能表示感叹。"}, {"text": "你是哪里人吗？", "explanation": "这里应该用〈特指问〉。“吗”只用于是非问，句中已有疑问代词“哪里”，不能再加“吗”。"}, {"text": "你为什么不去吗？", "explanation": "这里应该用〈特指问〉。“为什么”已是疑问词，句子是特指问，不能再加“吗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85680, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吗", "is_correct": true, "explanation": "ma（轻声）是本词，句末语气助词，表示疑问。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 ma（轻声）声调不同，意思是妈妈。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 ma（轻声）声调不同，意思是麻烦。"}, {"text": "骂", "is_correct": false, "explanation": "mà（第四声）与 ma（轻声）声调不同，意思是骂。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是马。"}], "explanations": {"吗": "ma（轻声）是本词，句末语气助词，表示疑问。", "妈": "mā（第一声）与 ma（轻声）声调不同，意思是妈妈。", "麻": "má（第二声）与 ma（轻声）声调不同，意思是麻烦。", "骂": "mà（第四声）与 ma（轻声）声调不同，意思是骂。", "马": "mǎ（第三声）与 ma（轻声）声调不同，意思是马。"}, "sentence_index": null, "correct_answer": "吗"}, "level_3": {"options": [{"text": "吗", "is_correct": true, "explanation": "吗：句末语气助词，表示疑问，用于请求许可的问句。"}, {"text": "过", "is_correct": false, "explanation": "体貌：过表示经历，句中是请求许可，不用“过”。"}, {"text": "啊", "is_correct": false, "explanation": "语义：啊表示感叹或招呼，不能用于请求许可的问句。"}, {"text": "地", "is_correct": false, "explanation": "语义：地是结构助词，不能用在句末。"}], "explanations": {"吗": "吗：句末语气助词，表示疑问，用于请求许可的问句。", "过": "体貌：过表示经历，句中是请求许可，不用“过”。", "啊": "语义：啊表示感叹或招呼，不能用于请求许可的问句。", "地": "语义：地是结构助词，不能用在句末。"}, "sentence_index": 6, "correct_answer": "吗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "快点回家吗！", "explanation": "这是命令句，句末不能用“吗”，应说“快点回家！”"}, {"text": "你要不要喝水吗？", "explanation": "这里应该用〈正反问〉。“要不要”已构成正反问，句子本身已是疑问句，不能再加“吗”。"}, {"text": "我的手机吗？", "explanation": "这里应该用〈呢〉。问东西在哪里要用“呢”，“吗”只用于是非问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你吃饭了吗吗？", "corrected_sentence": "你吃饭了吗？", "error_description": "重复语气词：句末只用一个“吗”，多出的“吗”要删去。应说“你吃饭了吗？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你今天想去公园玩吧吗？", "corrected_sentence": "你今天想去公园玩吗？", "error_description": "语气词错误：句末只用一个语气词，“吗”前不能再加“吧”。应说“你今天想去公园玩吗？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
