INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85682, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第一人称复数代词，指说话人一方的多个人，有时也包括听话人。", "primary_collocate": null, "pronunciation": "wǒ men", "ipa": "wɔ˨˩˦ mən", "syllable_count": 2, "sentences": [{"text": "我们明天一起去公园玩。", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“我们现在开始上课。”", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都是中国人。", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司在北京。", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们走吧，我们在这里等你。", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家有四口人。", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午我们要开会。", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家好，今天我们学习新课。", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的老师很年轻。", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们常去图书馆看书。", "target_word": "我们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "我们的", "label": "领属形式"}], "register": "中性", "sense_fingerprint": "第一人称复数代词，说话人一方，可含听话人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9dc599-3173-4820-a892-52e831b34649') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "我们", "is_correct": true, "explanation": "正确。“一起去公园”需要多人共同行动，“我们”指说话人一方的多人，与句意相符。"}, {"text": "我", "is_correct": false, "explanation": "语义：“一起”表示多人共同行动，单数的“我”与之不合，应说“我一个人”。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指事物或动物，而“去公园玩”的主体须是人，所以不能作主语。"}, {"text": "您", "is_correct": false, "explanation": "语义：“您”是对听话人的尊称，不能指说话人一方，与“我们”的所指不合。"}], "explanations": {"我们": "正确。“一起去公园”需要多人共同行动，“我们”指说话人一方的多人，与句意相符。", "我": "语义：“一起”表示多人共同行动，单数的“我”与之不合，应说“我一个人”。", "它们": "语义：“它们”指事物或动物，而“去公园玩”的主体须是人，所以不能作主语。", "您": "语义：“您”是对听话人的尊称，不能指说话人一方，与“我们”的所指不合。"}, "sentence_index": 0, "correct_answer": "我们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们昨天一个人去了图书馆。", "explanation": "这里应该用〈我〉。〈我们〉指说话人一方的多人，只有一个人去时要用〈我〉，与“一个人”矛盾。"}, {"text": "我一个人坐在教室里，我们认真地复习。", "explanation": "这里应该用〈我〉。〈我们〉指说话人一方的多人，句中只有我一个人，不能用〈我们〉。"}, {"text": "我一个人在家，我们都睡得很早。", "explanation": "这里应该用〈我〉。〈我们〉指说话人一方的多人，句中只有我一个人，不能用“我们都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "我们", "is_correct": true, "explanation": "正确。“要开会”需要说话人一方的多人参加，“我们”与句意相符。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指事物，不能参加开会，与“要开会”的主体不合。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指说话人以外的人，与句中说话人一方要开会的意思不合。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人本人，只表示单独一人，与句中“我们”指的说话人一方多人不合。"}], "explanations": {"我们": "正确。“要开会”需要说话人一方的多人参加，“我们”与句意相符。", "它": "语义：“它”指事物，不能参加开会，与“要开会”的主体不合。", "他们": "语义：“他们”指说话人以外的人，与句中说话人一方要开会的意思不合。", "自己": "语义：“自己”指说话人本人，只表示单独一人，与句中“我们”指的说话人一方多人不合。"}, "sentence_index": 6, "correct_answer": "我们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是中国人，我们美国的大学很多。", "explanation": "这里不能用〈我们〉指美国。〈我们〉指说话人一方，说话人是中国人，不属于美国，应直接说“美国的大学”。"}, {"text": "老师对我说：“我们都是学生，你要认真听课。”", "explanation": "这里不能用〈我们〉。〈我们〉包括说话人，老师说“我们都是学生”把自己算作学生，与身份不符；对学生说话应用〈你们〉。"}, {"text": "我们俩都是学生，我们一个人是老师。", "explanation": "这里不能用〈我们〉。〈我们〉指说话人一方的多人，“我们俩”与“一个人”数量不合，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们们俩是好朋友。", "corrected_sentence": "我们俩是好朋友。", "error_description": "错误：“我们们俩”。“我们”已经是复数，再加“们”造成重复；正确形式是“我们俩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都俩喜欢音乐。", "corrected_sentence": "我们俩都喜欢音乐。", "error_description": "错误：“我们都俩”。“都”要放在“俩”之后，应说“我们俩都”；正确形式是“我们俩都喜欢音乐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
