INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85699, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“但”用在后面的话里，是说和前面的话不太一样。", "primary_collocate": null, "pronunciation": "dàn", "ipa": "tan˥˩", "syllable_count": 1, "sentences": [{"text": "虽然很贵，但我还是买了。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然天气冷，但他穿得很少。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然我不饿，但想吃点东西。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然他很忙，但每天都来看我。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然下雨了，但我们还是去了。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然路很远，但我不觉得累。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然她年纪大，但身体很好。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事虽然小，但很重要。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然我学了很久，但还是不会。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然房子旧，但住着很舒服。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "但是", "label": "复合"}], "register": "中性", "sense_fingerprint": "但：与“虽然”呼应，用在后一分句，说明情况与前文不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c39c2f0b-1c7d-4288-9529-c42fc1d1b19a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85699, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "但", "is_correct": true, "explanation": "正确：“但”读 dàn（第四声），表示转折。"}, {"text": "担", "is_correct": false, "explanation": "dān（第一声）与 dàn（第四声）声调不同，“担”的意思是挑、背。"}, {"text": "大", "is_correct": false, "explanation": "dà 与 dàn 的韵尾不同（少了鼻音 n），“大”的意思是大小的大。"}, {"text": "段", "is_correct": false, "explanation": "duàn（第四声）与 dàn 只差介音 u，声调相同，“段”的意思是段落。"}, {"text": "叹", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），声调相同，“叹”的意思是叹气。"}, {"text": "带", "is_correct": false, "explanation": "dài 与 dàn 韵尾不同（i 与 n），声调相同，“带”的意思是带领、携带。"}], "explanations": {"但": "正确：“但”读 dàn（第四声），表示转折。", "担": "dān（第一声）与 dàn（第四声）声调不同，“担”的意思是挑、背。", "大": "dà 与 dàn 的韵尾不同（少了鼻音 n），“大”的意思是大小的大。", "段": "duàn（第四声）与 dàn 只差介音 u，声调相同，“段”的意思是段落。", "叹": "tàn 与 dàn 声母不同（t 与 d），声调相同，“叹”的意思是叹气。", "带": "dài 与 dàn 韵尾不同（i 与 n），声调相同，“带”的意思是带领、携带。"}, "sentence_index": null, "correct_answer": "但"}, "level_3": {"options": [{"text": "但", "is_correct": true, "explanation": "正确：“但”与“虽然”呼应，引出转折的后一分句。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结论，与“虽然”的让步关系冲突。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，与“虽然”的让步关系冲突。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”要和“不但”或“又”呼应，不能跟在“虽然”后面。"}], "explanations": {"但": "正确：“但”与“虽然”呼应，引出转折的后一分句。", "所以": "语义：“所以”表示结论，与“虽然”的让步关系冲突。", "因为": "语义：“因为”表示原因，与“虽然”的让步关系冲突。", "而且": "搭配：“而且”要和“不但”或“又”呼应，不能跟在“虽然”后面。"}, "sentence_index": 0, "correct_answer": "但"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "因为天气很好，但我们去了公园。", "explanation": "这里应该用〈所以〉。“但”表示转折，前后要是对比关系；这里前后是因果关系，应该用“所以”。"}, {"text": "他既会唱歌，但会跳舞。", "explanation": "这里应该用〈又〉。“既……又……”表示并列，要用“又”连接；“但”表示转折，前后没有对比，不能替代“又”。"}, {"text": "我去超市，但买东西。", "explanation": "这里应该去掉〈但〉，直接说“去超市买东西”。“但”表示转折，前后两个动作之间没有对比，不能用在连续动作之间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85699, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "但", "is_correct": true, "explanation": "正确：“但”读 dàn（第四声），表示转折。"}, {"text": "单", "is_correct": false, "explanation": "dān（第一声）与 dàn（第四声）声调不同，“单”的意思是单独。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn（第三声）与 dàn（第四声）声调不同，“胆”的意思是胆子。"}, {"text": "荡", "is_correct": false, "explanation": "dàng 与 dàn 韵尾不同（ng 与 n），声调相同，“荡”的意思是摇荡。"}, {"text": "地", "is_correct": false, "explanation": "dì 与 dàn 韵尾不同（i 与 n），声调相同，“地”的意思是地面。"}], "explanations": {"但": "正确：“但”读 dàn（第四声），表示转折。", "单": "dān（第一声）与 dàn（第四声）声调不同，“单”的意思是单独。", "胆": "dǎn（第三声）与 dàn（第四声）声调不同，“胆”的意思是胆子。", "荡": "dàng 与 dàn 韵尾不同（ng 与 n），声调相同，“荡”的意思是摇荡。", "地": "dì 与 dàn 韵尾不同（i 与 n），声调相同，“地”的意思是地面。"}, "sentence_index": null, "correct_answer": "但"}, "level_3": {"options": [{"text": "但", "is_correct": true, "explanation": "正确：“但”与“虽然”呼应，引出转折的后一分句。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果结论，与“虽然”的让步关系矛盾。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示承接的结果，与“虽然”的让步关系不合。"}, {"text": "从而", "is_correct": false, "explanation": "搭配：“从而”多接在动作之后表示结果，不与“虽然”呼应。"}], "explanations": {"但": "正确：“但”与“虽然”呼应，引出转折的后一分句。", "因此": "语义：“因此”表示因果结论，与“虽然”的让步关系矛盾。", "于是": "语义：“于是”表示承接的结果，与“虽然”的让步关系不合。", "从而": "搭配：“从而”多接在动作之后表示结果，不与“虽然”呼应。"}, "sentence_index": 6, "correct_answer": "但"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不仅很忙，但每天都来看我。", "explanation": "这里应该用〈还〉。“不仅……还……”表示递进，“但”表示转折，不能替代“还”。"}, {"text": "我吃完饭，但去了学校。", "explanation": "这里应该用〈然后〉。表示动作先后要用“然后”；“但”表示转折，两个动作之间没有对比关系。"}, {"text": "我来这里，但学习汉语。", "explanation": "这里应该用〈为了〉。表示目的要用“为了”，或直接说“来这里学习汉语”；“但”表示转折，不能用在目的和行为之间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85699, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "虽然天气很好，但但我们没有去公园。", "corrected_sentence": "虽然天气很好，但我们没有去公园。", "error_description": "“但”重复出现了两次。“虽然……，但……”中“但”只用一次，应删去多余的“但”，说成“虽然天气很好，但我们没有去公园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85699, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "因为这家店很小，但生意也很好。", "corrected_sentence": "虽然这家店很小，但生意也很好。", "error_description": "“但”与“虽然”呼应表示转折，这里前一分句用了“因为”，表示原因，与“但”的转折关系不搭配。应把“因为”改为“虽然”，说成“虽然这家店很小，但生意也很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
