INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85700, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示转折，引出与前面意思相反或有所限制的内容。", "primary_collocate": null, "pronunciation": "dàn", "ipa": "tan˥˩", "syllable_count": 1, "sentences": [{"text": "这家店很小，但东西很好。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去，但今天没有时间。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很累，但还是做完了作业。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不好，但我们还是出门了。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜很辣，但我很喜欢。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会说汉语，但说得不太好。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道这件事，但不想告诉你。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书不新，但很有意思。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪小，但懂很多事。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路很远，但我们走得很开心。", "target_word": "但", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "但是", "label": "复合"}], "register": "中性", "sense_fingerprint": "但：连词，转折，引出与前文相反或加以限制的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c39c2f0b-1c7d-4288-9529-c42fc1d1b19a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "但", "is_correct": true, "explanation": "但（dàn）表示转折，是正确答案。"}, {"text": "担", "is_correct": false, "explanation": "dān（第一声）与 dàn 声调不同，意思是挑、扛。"}, {"text": "叹", "is_correct": false, "explanation": "tàn（第四声）与 dàn 声母不同（t 与 d），意思是叹息。"}, {"text": "代", "is_correct": false, "explanation": "dài（第四声）与 dàn 韵尾不同（ai 与 an），意思是代替、时代。"}], "explanations": {"但": "但（dàn）表示转折，是正确答案。", "担": "dān（第一声）与 dàn 声调不同，意思是挑、扛。", "叹": "tàn（第四声）与 dàn 声母不同（t 与 d），意思是叹息。", "代": "dài（第四声）与 dàn 韵尾不同（ai 与 an），意思是代替、时代。"}, "sentence_index": null, "correct_answer": "但"}, "level_3": {"options": [{"text": "但", "is_correct": true, "explanation": "正确：“但”表示转折，“店小，但东西好”前后意思相反，句意通顺。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“店很小，因为东西很好”因果颠倒，句意不通。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“店很小，所以东西很好”前后逻辑不通。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“如果”表示假设，需与“就”呼应，此句没有“就”，句意不完整。"}], "explanations": {"但": "正确：“但”表示转折，“店小，但东西好”前后意思相反，句意通顺。", "因为": "语义：“因为”表示原因，“店很小，因为东西很好”因果颠倒，句意不通。", "所以": "语义：“所以”表示结果，“店很小，所以东西很好”前后逻辑不通。", "如果": "搭配：“如果”表示假设，需与“就”呼应，此句没有“就”，句意不完整。"}, "sentence_index": 0, "correct_answer": "但"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子聪明但勤奋。", "explanation": "这里应该用〈而〉。“但”表示转折，两个并列的优点之间不用转折，应说“聪明而勤奋”。"}, {"text": "他写完作业，但睡觉了。", "explanation": "这里应该用〈然后〉。表示动作先后要用“然后”；“但”表示转折，两个动作之间没有对比关系。"}, {"text": "他不但聪明，但勤奋。", "explanation": "这里应该用〈而且〉。“不但”要与“而且”呼应，“但”不能用于递进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85700, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "但", "is_correct": true, "explanation": "但（dàn）表示转折，是正确答案。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn（第三声）与 dàn 声调不同，意思是胆子、胆量。"}, {"text": "半", "is_correct": false, "explanation": "bàn（第四声）与 dàn 声母不同（b 与 d），意思是一半。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dàn 韵尾不同（a 与 an），意思是大。"}], "explanations": {"但": "但（dàn）表示转折，是正确答案。", "胆": "dǎn（第三声）与 dàn 声调不同，意思是胆子、胆量。", "半": "bàn（第四声）与 dàn 声母不同（b 与 d），意思是一半。", "大": "dà（第四声）与 dàn 韵尾不同（a 与 an），意思是大。"}, "sentence_index": null, "correct_answer": "但"}, "level_3": {"options": [{"text": "但", "is_correct": true, "explanation": "正确：“但”表示转折，“我知道这件事，但不想告诉你”前后意思相反，句意通顺。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”表示让步，需与“也”或“还”呼应，此句没有这些词，句意不完整。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”需与“但”呼应，此句没有“但”，句意不完整。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，“我知道这件事，或者不想告诉你”前后并不构成选择。"}], "explanations": {"但": "正确：“但”表示转折，“我知道这件事，但不想告诉你”前后意思相反，句意通顺。", "即使": "搭配：“即使”表示让步，需与“也”或“还”呼应，此句没有这些词，句意不完整。", "虽然": "搭配：“虽然”需与“但”呼应，此句没有“但”，句意不完整。", "或者": "语义：“或者”表示选择，“我知道这件事，或者不想告诉你”前后并不构成选择。"}, "sentence_index": 6, "correct_answer": "但"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他但生病，没来上课。", "explanation": "这里应该用〈因为〉。“但”只表示转折，不表示原因，应说“因为生病，没来上课”。"}, {"text": "但你不来，我就不去。", "explanation": "这里应该用〈如果〉。“但”只表示转折，不表示假设条件，应说“如果你不来，我就不去”。"}, {"text": "他看书，但吃饭。", "explanation": "这里应该用〈又〉，说“他又看书又吃饭”。并列的同时动作不用“但”，“但”表示转折，这里没有对比关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很忙，但但还是来了。", "corrected_sentence": "他很忙，但还是来了。", "error_description": "错误：“但”重复使用。转折只需用一次“但”，应说“他很忙，但还是来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路很远，可是但我们终于到了。", "corrected_sentence": "路很远，但我们终于到了。", "error_description": "错误：“可是”与“但”重复表示转折，只用其一。应说“路很远，但我们终于到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
