INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85712, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示动作行为的起点，包括时间、地点或来源。", "primary_collocate": null, "pronunciation": "cóng", "ipa": "tsʰʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他从学校回家。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里往前走就是医院。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从图书馆借了三本书。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从中午就一直在等你。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是从哪里听来的？", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从后门走了出去。", "target_word": "从", "complexity_tier": "T3", "furigana": "tā cóng hòu mén zǒu le chū qù.", "sentence_source": "generated"}, {"text": "我们从下午两点开会。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从口袋里拿出一支笔。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果是从南方来的。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从我家到公司要四十分钟。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從", "label": "繁体"}, {"form": "从前", "label": "复合"}, {"form": "从来", "label": "复合"}], "register": "中性", "sense_fingerprint": "从：介词，表示动作的起点（时间、地点、来源）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c39c2f0b-1c7d-4288-9529-c42fc1d1b19a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85712, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "从", "is_correct": true, "explanation": "正确：“从”读 cóng（第二声），表示动作的起点。"}, {"text": "同", "is_correct": false, "explanation": "tóng 与 cóng 声母不同（t 与 c），声调相同，“同”的意思是相同。"}, {"text": "虫", "is_correct": false, "explanation": "chóng 与 cóng 声母不同（ch 与 c），声调相同，“虫”的意思是虫子。"}, {"text": "层", "is_correct": false, "explanation": "céng 与 cóng 韵母不同（e 与 o），声调相同，“层”的意思是层次。"}], "explanations": {"从": "正确：“从”读 cóng（第二声），表示动作的起点。", "同": "tóng 与 cóng 声母不同（t 与 c），声调相同，“同”的意思是相同。", "虫": "chóng 与 cóng 声母不同（ch 与 c），声调相同，“虫”的意思是虫子。", "层": "céng 与 cóng 韵母不同（e 与 o），声调相同，“层”的意思是层次。"}, "sentence_index": null, "correct_answer": "从"}, "level_3": {"options": [{"text": "从", "is_correct": true, "explanation": "正确：“从学校回家”表示动作从学校这个起点开始。"}, {"text": "离", "is_correct": false, "explanation": "语义：“离”表示距离，不表示动作的起点。"}, {"text": "对", "is_correct": false, "explanation": "配价：“对”引出对象，不能引出动作的起点。"}, {"text": "到", "is_correct": false, "explanation": "语义：“到”表示终点，与“回家”所表示的起点不合。"}], "explanations": {"从": "正确：“从学校回家”表示动作从学校这个起点开始。", "离": "语义：“离”表示距离，不表示动作的起点。", "对": "配价：“对”引出对象，不能引出动作的起点。", "到": "语义：“到”表示终点，与“回家”所表示的起点不合。"}, "sentence_index": 0, "correct_answer": "从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们从教室学习。", "explanation": "这里应该用〈在〉。说明在某地学习要用“在”，“从”表示起点，不表示地点。"}, {"text": "学校从车站很近。", "explanation": "这里应该用〈离〉。表示两地的距离要用“离”，“从”不表示距离。"}, {"text": "我从很喜欢这本书。", "explanation": "这里应该去掉〈从〉，直接说“很喜欢这本书”。“从”表示起点，不能放在表示心理状态的词语前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85712, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "从", "is_correct": true, "explanation": "正确：“从”读 cóng（第二声），表示动作的起点。"}, {"text": "葱", "is_correct": false, "explanation": "cōng（第一声）与 cóng（第二声）声调不同，“葱”的意思是葱。"}, {"text": "铜", "is_correct": false, "explanation": "tóng 与 cóng 声母不同（t 与 c），声调相同，“铜”的意思是金属铜。"}, {"text": "重", "is_correct": false, "explanation": "chóng 与 cóng 声母不同（ch 与 c），声调相同，“重”读 chóng 时的意思是重复。"}, {"text": "曾", "is_correct": false, "explanation": "céng 与 cóng 韵母不同（e 与 o），声调相同，“曾”的意思是曾经。"}], "explanations": {"从": "正确：“从”读 cóng（第二声），表示动作的起点。", "葱": "cōng（第一声）与 cóng（第二声）声调不同，“葱”的意思是葱。", "铜": "tóng 与 cóng 声母不同（t 与 c），声调相同，“铜”的意思是金属铜。", "重": "chóng 与 cóng 声母不同（ch 与 c），声调相同，“重”读 chóng 时的意思是重复。", "曾": "céng 与 cóng 韵母不同（e 与 o），声调相同，“曾”的意思是曾经。"}, "sentence_index": null, "correct_answer": "从"}, "level_3": {"options": [{"text": "从", "is_correct": true, "explanation": "正确：“从……两点”表示时间的起点，与“开会”搭配。"}, {"text": "往", "is_correct": false, "explanation": "配价：“往”引出方向，不能引出时间的起点。"}, {"text": "朝", "is_correct": false, "explanation": "语义：“朝”表示朝向，不表示时间的起点。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向或对象，不能用来引出时间的起点。"}], "explanations": {"从": "正确：“从……两点”表示时间的起点，与“开会”搭配。", "往": "配价：“往”引出方向，不能引出时间的起点。", "朝": "语义：“朝”表示朝向，不表示时间的起点。", "向": "语义：“向”表示方向或对象，不能用来引出时间的起点。"}, "sentence_index": 6, "correct_answer": "从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从老师问了问题。", "explanation": "这里应该用〈向〉。问问题是向人请教，要用“向”；“从”不能引出提问的对象。"}, {"text": "他从大家说了实话。", "explanation": "这里应该用〈对〉。引出说话的对象要用“对”，“从”不能这样用。"}, {"text": "他从老师一起吃饭。", "explanation": "这里应该用〈跟〉。表示和某人一起做事要用“跟”或“和”，“从”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从从公司出来，去了医院。", "corrected_sentence": "他从公司出来，去了医院。", "error_description": "“从”重复出现了两次，“从从公司”是重复错误。表示动作的起点只用一个“从”，应说成“他从公司出来，去了医院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "从周一到，我每天早起。", "corrected_sentence": "从周一起，我每天早起。", "error_description": "“从……起”表示从某个时间开始往后，后面不需要终点；“从……到……”需要终点，这里缺少终点，应把“到”改为“起”，说成“从周一起，我每天早起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
