INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85713, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“以”是说用什么东西或什么办法做事。", "primary_collocate": null, "pronunciation": "yǐ", "ipa": "i˨˩˦", "syllable_count": 1, "sentences": [{"text": "农民以牛耕地，不用机器。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她以手机拍下了美丽的日出。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师以粉笔在黑板上写字。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以行动证明了自己的想法。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们以书信的方式保持联系。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人以拐杖支撑着身体。", "target_word": "以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以微笑回答了我的问题。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家以热烈的掌声欢迎校长。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈以牛奶和面粉做了蛋糕。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请以简单的话告诉我答案。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "以……的方式", "label": "常用结构"}], "register": "书面", "sense_fingerprint": "介词，引出做事所用的东西或办法，相当于“用”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 粉笔 (Zipf 3.19), 黑板 (Zipf 3.41), 写字 (Zipf 3.59)']::text[], 'ae0a5167-b7a0-4535-b648-c4ab11c8f416') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85713, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以", "is_correct": true, "explanation": "yǐ（第三声）是介词，表示用什么东西或办法做事。"}, {"text": "衣", "is_correct": false, "explanation": "yī（第一声）与 yǐ 声调不同，意思是衣服。"}, {"text": "易", "is_correct": false, "explanation": "yì（第四声）与 yǐ 声调不同，意思是容易。"}, {"text": "移", "is_correct": false, "explanation": "yí（第二声）与 yǐ 声调不同，意思是移动。"}], "explanations": {"以": "yǐ（第三声）是介词，表示用什么东西或办法做事。", "衣": "yī（第一声）与 yǐ 声调不同，意思是衣服。", "易": "yì（第四声）与 yǐ 声调不同，意思是容易。", "移": "yí（第二声）与 yǐ 声调不同，意思是移动。"}, "sentence_index": null, "correct_answer": "以"}, "level_3": {"options": [{"text": "以", "is_correct": true, "explanation": "“以”引出所用的东西“牛”，句意是用牛耕地。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，“对牛耕地”不通。"}, {"text": "在", "is_correct": false, "explanation": "搭配：“在”表示处所，“农民在牛耕地”不能表示用牛的办法。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示目的，与“用牛耕地”的办法不符。"}], "explanations": {"以": "“以”引出所用的东西“牛”，句意是用牛耕地。", "对": "语义：“对”引出对象，“对牛耕地”不通。", "在": "搭配：“在”表示处所，“农民在牛耕地”不能表示用牛的办法。", "为": "语义：“为”表示目的，与“用牛耕地”的办法不符。"}, "sentence_index": 0, "correct_answer": "以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他以筷子开车。", "explanation": "“以”引出的所用之物要能用于所做的事，“筷子”不能用来“开车”。表示用某物做事应说“用”，如“他用手机打电话”。"}, {"text": "她以牛奶修电脑。", "explanation": "“以”引出的所用之物要能用于所做的事，“牛奶”不能用来“修电脑”。表示用某物做事应说“用”，如“她用螺丝刀修电脑”。"}, {"text": "我以眼睛写字。", "explanation": "“以”引出的所用之物要能用于所做的事，“眼睛”不能用来“写字”。表示用某物做事应说“用”，如“我用铅笔写字”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85713, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "以", "is_correct": true, "explanation": "yǐ（第三声）是介词，表示用什么东西或办法做事。"}, {"text": "医", "is_correct": false, "explanation": "yī（第一声）与 yǐ 声调不同，意思是医生。"}, {"text": "意", "is_correct": false, "explanation": "yì（第四声）与 yǐ 声调不同，意思是意思。"}, {"text": "姨", "is_correct": false, "explanation": "yí（第二声）与 yǐ 声调不同，意思是阿姨。"}], "explanations": {"以": "yǐ（第三声）是介词，表示用什么东西或办法做事。", "医": "yī（第一声）与 yǐ 声调不同，意思是医生。", "意": "yì（第四声）与 yǐ 声调不同，意思是意思。", "姨": "yí（第二声）与 yǐ 声调不同，意思是阿姨。"}, "sentence_index": null, "correct_answer": "以"}, "level_3": {"options": [{"text": "以", "is_correct": true, "explanation": "“以”引出回答所用的方式“微笑”，句意通顺。"}, {"text": "按", "is_correct": false, "explanation": "语义：“按”表示依照，“按微笑回答”不通。"}, {"text": "因", "is_correct": false, "explanation": "语义：“因”表示原因，“因微笑回答”不通。"}, {"text": "替", "is_correct": false, "explanation": "搭配：“替”表示代替他人，“替微笑回答”不搭配。"}], "explanations": {"以": "“以”引出回答所用的方式“微笑”，句意通顺。", "按": "语义：“按”表示依照，“按微笑回答”不通。", "因": "语义：“因”表示原因，“因微笑回答”不通。", "替": "搭配：“替”表示代替他人，“替微笑回答”不搭配。"}, "sentence_index": 6, "correct_answer": "以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他以微笑喝水。", "explanation": "“以”引出的所用之物要能用于所做的事，“微笑”不能用来“喝水”。表示用某物做事应说“用”，如“他用杯子喝水”。"}, {"text": "我们以掌声吃饭。", "explanation": "“以”引出的所用之物要能用于所做的事，“掌声”不能用来“吃饭”。表示用某物做事应说“用”，如“我们用筷子吃饭”。"}, {"text": "她以歌声写作业。", "explanation": "“以”引出的所用之物要能用于所做的事，“歌声”不能用来“写作业”。表示用某物做事应说“用”，如“她用笔写作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以一把钥匙以打开了门。", "corrected_sentence": "他以一把钥匙打开了门。", "error_description": "“以”只引出一次凭借之物，之后直接接动词，动词前不能再加“以”。删去多余的一个“以”，应说“他以一把钥匙打开了门。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刀以切开了蛋糕。", "corrected_sentence": "他以刀切开了蛋糕。", "error_description": "错误在于“以”的位置：“以”应放在所用工具“刀”之前，说“他以刀切开了蛋糕”；不能说“他刀以切开了蛋糕”，“以”放在“刀”后面不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
