INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85714, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示凭借、使用某种工具、方式或根据，相当于“用”“拿”。", "primary_collocate": null, "pronunciation": "yǐ", "ipa": "i˨˩˦", "syllable_count": 1, "sentences": [{"text": "他以最快的速度跑到了终点。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师以讲故事的方式教我们汉字。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们以电话的方式联系。", "target_word": "以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司以质量赢得了客户。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以真诚的态度向大家道歉。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她以优秀的成绩考上了大学。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想以朋友的身份给你一个建议。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王以笑脸迎接每一位客人。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生以耐心的话安慰了病人。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们以投票的方法选出班长。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "以……的方式", "label": "常用结构"}], "register": "书面", "sense_fingerprint": "介词，引出凭借的方式、手段或依据，相当于“用”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0a5167-b7a0-4535-b648-c4ab11c8f416') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85714, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以", "is_correct": true, "explanation": "yǐ（第三声）是介词，表示凭借某种方式或手段。"}, {"text": "衣", "is_correct": false, "explanation": "yī（第一声）与 yǐ 声调不同，意思是衣服。"}, {"text": "易", "is_correct": false, "explanation": "yì（第四声）与 yǐ 声调不同，意思是容易。"}, {"text": "移", "is_correct": false, "explanation": "yí（第二声）与 yǐ 声调不同，意思是移动。"}], "explanations": {"以": "yǐ（第三声）是介词，表示凭借某种方式或手段。", "衣": "yī（第一声）与 yǐ 声调不同，意思是衣服。", "易": "yì（第四声）与 yǐ 声调不同，意思是容易。", "移": "yí（第二声）与 yǐ 声调不同，意思是移动。"}, "sentence_index": null, "correct_answer": "以"}, "level_3": {"options": [{"text": "以", "is_correct": true, "explanation": "“以”引出做事的方式“最快的速度”，句意通顺。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，“对最快的速度”不通。"}, {"text": "在", "is_correct": false, "explanation": "搭配：“在”引出处所或范围，“在最快的速度”不搭配这种表达。"}, {"text": "被", "is_correct": false, "explanation": "语义：“被”表示被动，“被最快的速度跑到了终点”不通。"}], "explanations": {"以": "“以”引出做事的方式“最快的速度”，句意通顺。", "对": "语义：“对”引出对象，“对最快的速度”不通。", "在": "搭配：“在”引出处所或范围，“在最快的速度”不搭配这种表达。", "被": "语义：“被”表示被动，“被最快的速度跑到了终点”不通。"}, "sentence_index": 0, "correct_answer": "以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他以红笔吃饭。", "explanation": "“以”引出的凭借之物要能用于所做的事，“红笔”不能用来“吃饭”。表示用工具做事应说“用”，如“他用筷子吃饭”。"}, {"text": "老师以粉笔喝水。", "explanation": "“以”引出的凭借之物要能用于所做的事，“粉笔”不能用来“喝水”。表示用工具做事应说“用”，如“老师用杯子喝水”。"}, {"text": "她以电脑洗衣服。", "explanation": "“以”引出的凭借之物要能用于所做的事，“电脑”不能用来“洗衣服”。表示用工具做事应说“用”，如“她用洗衣机洗衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
