INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以一封电子邮件以通知大家。", "corrected_sentence": "我以一封电子邮件通知大家。", "error_description": "“以”在此句只能出现一次：“以一封电子邮件”已引出凭借之物，动词“通知”前不能再加“以”。删去多余的一个“以”，应说“我以一封电子邮件通知大家。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
