INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85717, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“着”放在动作后面，是说这件事正在做，或者一直这样。", "primary_collocate": null, "pronunciation": "zhe", "ipa": "tʂɤ", "syllable_count": 1, "sentences": [{"text": "他坐着看书。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开着，里面没有人。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在外面玩着。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着对我说话。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上挂着一张地图。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很好，我们走着去学校吧。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想着家里的事。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外下着大雨。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师站着给我们讲课。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着三本书。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "动词后的助词，表示动作进行或状态持续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027318f4-2b33-4396-a5c8-0febbc57a5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85717, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "着", "is_correct": true, "explanation": "「着」读轻声 zhe，是助词，表示动作持续或状态保持。"}, {"text": "这", "is_correct": false, "explanation": "「zhè」（第四声）与「zhe」（轻声）声调不同，意思是「这」。"}, {"text": "者", "is_correct": false, "explanation": "「zhě」（第三声）与「zhe」（轻声）声调不同，意思是「者」。"}, {"text": "折", "is_correct": false, "explanation": "「zhé」（第二声）与「zhe」（轻声）声调不同，意思是「折断」。"}, {"text": "哲", "is_correct": false, "explanation": "「zhé」（第二声）与「zhe」（轻声）声调不同，意思是「哲学」。"}, {"text": "遮", "is_correct": false, "explanation": "「zhē」（第一声）与「zhe」（轻声）声调不同，意思是「遮挡」。"}], "explanations": {"着": "「着」读轻声 zhe，是助词，表示动作持续或状态保持。", "这": "「zhè」（第四声）与「zhe」（轻声）声调不同，意思是「这」。", "者": "「zhě」（第三声）与「zhe」（轻声）声调不同，意思是「者」。", "折": "「zhé」（第二声）与「zhe」（轻声）声调不同，意思是「折断」。", "哲": "「zhé」（第二声）与「zhe」（轻声）声调不同，意思是「哲学」。", "遮": "「zhē」（第一声）与「zhe」（轻声）声调不同，意思是「遮挡」。"}, "sentence_index": null, "correct_answer": "着"}, "level_3": {"options": [{"text": "着", "is_correct": true, "explanation": "「着」表示动作持续，「坐着看书」描述的正是持续的状态。"}, {"text": "了", "is_correct": false, "explanation": "体貌：「了」表示动作完成，句子说的是坐着看书的持续状态。"}, {"text": "过", "is_correct": false, "explanation": "体貌：「过」表示曾经有过的经历，不表示眼下持续的动作。"}, {"text": "得", "is_correct": false, "explanation": "配价：「得」后需要补语，「坐得」后不能直接接宾语「看书」。"}], "explanations": {"着": "「着」表示动作持续，「坐着看书」描述的正是持续的状态。", "了": "体貌：「了」表示动作完成，句子说的是坐着看书的持续状态。", "过": "体貌：「过」表示曾经有过的经历，不表示眼下持续的动作。", "得": "配价：「得」后需要补语，「坐得」后不能直接接宾语「看书」。"}, "sentence_index": 0, "correct_answer": "着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一听这个消息就着急了。", "explanation": "这里的「着」读 zháo，属于词〈着急〉，表示心里慌，不是表示动作持续的助词。"}, {"text": "飞机十点准时着陆。", "explanation": "这里的「着」读 zhuó，属于词〈着陆〉，指飞机落地，不是表示动作持续的助词。"}, {"text": "屋子里突然着了火。", "explanation": "这里的「着」读 zháo，属于词〈着火〉，指燃烧，不是表示动作持续的助词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85717, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "着", "is_correct": true, "explanation": "「着」读轻声 zhe，是助词，表示动作持续或状态保持。"}, {"text": "的", "is_correct": false, "explanation": "「de」（轻声）与「zhe」（轻声）声母不同，意思是「的」。"}, {"text": "了", "is_correct": false, "explanation": "「le」（轻声）与「zhe」（轻声）声母不同，意思是「了」。"}, {"text": "地", "is_correct": false, "explanation": "「de」（轻声）与「zhe」（轻声）声母不同，意思是「地」。"}, {"text": "得", "is_correct": false, "explanation": "「de」（轻声）与「zhe」（轻声）声母不同，意思是「得」。"}], "explanations": {"着": "「着」读轻声 zhe，是助词，表示动作持续或状态保持。", "的": "「de」（轻声）与「zhe」（轻声）声母不同，意思是「的」。", "了": "「le」（轻声）与「zhe」（轻声）声母不同，意思是「了」。", "地": "「de」（轻声）与「zhe」（轻声）声母不同，意思是「地」。", "得": "「de」（轻声）与「zhe」（轻声）声母不同，意思是「得」。"}, "sentence_index": null, "correct_answer": "着"}, "level_3": {"options": [{"text": "着", "is_correct": true, "explanation": "「着」表示状态持续，「一直想着家里的事」描述的正是持续的状态。"}, {"text": "地", "is_correct": false, "explanation": "搭配：「地」需接在形容词或副词后作状语，「一直想地」不成立。"}, {"text": "的", "is_correct": false, "explanation": "配价：「的」构成定语，「想的」后不能直接带「家里的事」作宾语。"}, {"text": "吧", "is_correct": false, "explanation": "语域：「吧」是语气词，表示商量或推测，不能用在叙述句中间。"}], "explanations": {"着": "「着」表示状态持续，「一直想着家里的事」描述的正是持续的状态。", "地": "搭配：「地」需接在形容词或副词后作状语，「一直想地」不成立。", "的": "配价：「的」构成定语，「想的」后不能直接带「家里的事」作宾语。", "吧": "语域：「吧」是语气词，表示商量或推测，不能用在叙述句中间。"}, "sentence_index": 6, "correct_answer": "着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他处处为别人着想。", "explanation": "这里的「着」读 zhuó，属于词〈着想〉，指考虑，不是表示状态持续的助词。"}, {"text": "昨晚他吹了风，今天着了凉。", "explanation": "这里的「着」读 zháo，属于词〈着凉〉，指感冒，不是表示状态持续的助词。"}, {"text": "他对音乐很着迷。", "explanation": "这里的「着」读 zháo，属于词〈着迷〉，指入迷，不是表示状态持续的助词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她站了着等我。", "corrected_sentence": "她站着等我。", "error_description": "助词错误：「了」和「着」不能同时用在同一个动词后，「站着等我」表示持续的状态，应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他低头着写字。", "corrected_sentence": "他低着头写字。", "error_description": "位置错误：「着」应紧接在动词「低」后，表示低头的持续状态，应为「低着头写字」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
