INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85718, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85718, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用在动词后面，表示动作正在进行或状态在持续。", "primary_collocate": null, "pronunciation": "zhe", "ipa": "tʂɤ", "syllable_count": 1, "sentences": [{"text": "她穿着红色的衣服。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗躺着睡觉。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看着电视吃饭。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯还亮着，他没有睡。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里拿着一杯茶。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们听着音乐写作业。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的风吹着树叶。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭着找妈妈。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的门关着，我进不去。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在厨房里忙着做饭。", "target_word": "着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "动词后的助词，表示动作正在进行或状态持续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027318f4-2b33-4396-a5c8-0febbc57a5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "着", "is_correct": true, "explanation": "着（zhe，轻声）是助词，用在动词后表示动作正在进行或状态持续，这里“穿着”表示穿的状态。"}, {"text": "这", "is_correct": false, "explanation": "这（zhè，第四声）与着（zhe，轻声）声调不同，意思是“这个”，不表示动作持续。"}, {"text": "折", "is_correct": false, "explanation": "折（zhé，第二声）与着（zhe，轻声）声调不同，意思是“折断、折叠”。"}, {"text": "遮", "is_correct": false, "explanation": "遮（zhē，第一声）与着（zhe，轻声）声调不同，意思是“遮挡”。"}, {"text": "者", "is_correct": false, "explanation": "者（zhě，第三声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“人、人士”。"}, {"text": "哲", "is_correct": false, "explanation": "哲（zhé，第二声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“智慧、明智”。"}], "explanations": {"着": "着（zhe，轻声）是助词，用在动词后表示动作正在进行或状态持续，这里“穿着”表示穿的状态。", "这": "这（zhè，第四声）与着（zhe，轻声）声调不同，意思是“这个”，不表示动作持续。", "折": "折（zhé，第二声）与着（zhe，轻声）声调不同，意思是“折断、折叠”。", "遮": "遮（zhē，第一声）与着（zhe，轻声）声调不同，意思是“遮挡”。", "者": "者（zhě，第三声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“人、人士”。", "哲": "哲（zhé，第二声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“智慧、明智”。"}, "sentence_index": null, "correct_answer": "着"}, "level_3": {"options": [{"text": "着", "is_correct": true, "explanation": "着表示“穿”这一状态的持续，填入后句意通顺。"}, {"text": "的", "is_correct": false, "explanation": "配价：“穿”后直接带宾语“红色的衣服”，加“的”会使“她穿的”成为定语，句子缺少谓语。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”用于在动词前修饰动词，“穿”前没有需要修饰的状语，“穿地”不成立。"}, {"text": "得", "is_correct": false, "explanation": "配价：“得”引出补语，但“穿”后已带宾语“红色的衣服”，“穿得”后缺少补语，结构不成立。"}], "explanations": {"着": "着表示“穿”这一状态的持续，填入后句意通顺。", "的": "配价：“穿”后直接带宾语“红色的衣服”，加“的”会使“她穿的”成为定语，句子缺少谓语。", "地": "搭配：“地”用于在动词前修饰动词，“穿”前没有需要修饰的状语，“穿地”不成立。", "得": "配价：“得”引出补语，但“穿”后已带宾语“红色的衣服”，“穿得”后缺少补语，结构不成立。"}, "sentence_index": 0, "correct_answer": "着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买着一台电脑。", "explanation": "这里应该用〈了〉。“着”表示动作正在进行或状态持续，用于“昨天”这样已完成的一次性动作时不成立，应说“买了”。"}, {"text": "他每天吃着三次药。", "explanation": "这里不应用〈着〉。“着”表示动作或状态正在持续，不能用于“每天”这样的习惯性重复，应直接说“吃三次药”。"}, {"text": "他终于考着大学。", "explanation": "这里应该用〈上〉。“着”表示持续，“考上”表示考试达到录取的结果，应说“考上大学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85718, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "着", "is_correct": true, "explanation": "着（zhe，轻声）是助词，用在动词后表示动作正在进行或状态持续，这里“吹着”表示风正在吹的动作。"}, {"text": "者", "is_correct": false, "explanation": "者（zhě，第三声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“人、人士”。"}, {"text": "遮", "is_correct": false, "explanation": "遮（zhē，第一声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“遮挡”。"}, {"text": "哲", "is_correct": false, "explanation": "哲（zhé，第二声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“智慧、明智”。"}, {"text": "浙", "is_correct": false, "explanation": "浙（zhè，第四声）与着（zhe，轻声）声母韵母相同而声调不同，是“浙江”的“浙”。"}, {"text": "辙", "is_correct": false, "explanation": "辙（zhé，第二声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“车轮碾过的痕迹”。"}], "explanations": {"着": "着（zhe，轻声）是助词，用在动词后表示动作正在进行或状态持续，这里“吹着”表示风正在吹的动作。", "者": "者（zhě，第三声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“人、人士”。", "遮": "遮（zhē，第一声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“遮挡”。", "哲": "哲（zhé，第二声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“智慧、明智”。", "浙": "浙（zhè，第四声）与着（zhe，轻声）声母韵母相同而声调不同，是“浙江”的“浙”。", "辙": "辙（zhé，第二声）与着（zhe，轻声）声母韵母相同而声调不同，意思是“车轮碾过的痕迹”。"}, "sentence_index": null, "correct_answer": "着"}, "level_3": {"options": [{"text": "着", "is_correct": true, "explanation": "着表示“吹”这一动作正在进行，填入后句意通顺。"}, {"text": "似的", "is_correct": false, "explanation": "搭配：“似的”表示比拟，需与“像”等配合，“吹似的树叶”不成立。"}, {"text": "来着", "is_correct": false, "explanation": "语义：“来着”用于追述或询问刚才的情况，与“吹”的正在进行义不符，且不能插在动词与宾语之间。"}, {"text": "罢了", "is_correct": false, "explanation": "搭配：“罢了”表示“而已”，用在句末，不能插在动词和宾语之间。"}], "explanations": {"着": "着表示“吹”这一动作正在进行，填入后句意通顺。", "似的": "搭配：“似的”表示比拟，需与“像”等配合，“吹似的树叶”不成立。", "来着": "语义：“来着”用于追述或询问刚才的情况，与“吹”的正在进行义不符，且不能插在动词与宾语之间。", "罢了": "搭配：“罢了”表示“而已”，用在句末，不能插在动词和宾语之间。"}, "sentence_index": 6, "correct_answer": "着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天出发着去北京。", "explanation": "这里不能用〈着〉。“出发”是一次性的动作，“着”表示持续，二者冲突，应说“我们明天出发去北京”。"}, {"text": "他很早就知道着这件事。", "explanation": "这里不能用〈着〉。“知道”是状态动词，一般不带“着”表示持续，应说“他很早就知道这件事”。"}, {"text": "他这次考试一定会取得着好成绩。", "explanation": "这里不能用〈着〉。“取得”表示达成的结果，“着”表示持续，二者冲突，应说“取得好成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站了着等我。", "corrected_sentence": "他站着等我。", "error_description": "“站着”中的“着”已表示“站”的状态持续，“了”与“着”不能同时标记同一状态。错误形式“站了着”在“站”与“着”之间多加了“了”，应改为“站着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐着了看报。", "corrected_sentence": "他坐着看报。", "error_description": "“坐着”中的“着”已表示“坐”的状态持续，其后不能再加“了”。错误形式“坐着了看报”重复标记了状态，应删去“了”，说“他坐着看报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85721, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
