INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85721, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“自己”是说自己这个人，不是别人。", "primary_collocate": null, "pronunciation": "zì jǐ", "ipa": "tsɨ˥˩ tɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "我自己做饭。", "target_word": "自己", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你要相信自己。", "target_word": "自己", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他自己去了学校。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请介绍一下你自己。", "target_word": "自己", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子想自己穿衣服。", "target_word": "自己", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在镜子里看见了自己。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我自己画的画。", "target_word": "自己", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别人不会，只有你自己能做。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想麻烦别人，什么都自己做。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该爱护自己的身体。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "自己人", "label": "复合"}], "register": "通用", "sense_fingerprint": "强调是本人亲自，而不是别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d46218-0b69-4845-8d22-7c88f2e3105e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85721, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自己", "is_correct": true, "explanation": "正确答案：自己（zì jǐ），指本人，强调不是别人。"}, {"text": "自习", "is_correct": false, "explanation": "zì xí 与 zì jǐ 第二个音节声母和声调不同（x 与 j，第二声与第三声），自习指自学。"}, {"text": "字句", "is_correct": false, "explanation": "zì jù 与 zì jǐ 第二个音节韵母和声调不同（ü 与 i，第四声与第三声），字句指文字和词句。"}, {"text": "自拟", "is_correct": false, "explanation": "zì nǐ 与 zì jǐ 第二个音节声母不同（n 与 j），自拟指自己起草。"}], "explanations": {"自己": "正确答案：自己（zì jǐ），指本人，强调不是别人。", "自习": "zì xí 与 zì jǐ 第二个音节声母和声调不同（x 与 j，第二声与第三声），自习指自学。", "字句": "zì jù 与 zì jǐ 第二个音节韵母和声调不同（ü 与 i，第四声与第三声），字句指文字和词句。", "自拟": "zì nǐ 与 zì jǐ 第二个音节声母不同（n 与 j），自拟指自己起草。"}, "sentence_index": null, "correct_answer": "自己"}, "level_3": {"options": [{"text": "别人", "is_correct": false, "explanation": "搭配：“别人”指他人，“我别人做饭”不成立，不能表示“我自己做”。"}, {"text": "自己", "is_correct": true, "explanation": "正确：“自己”强调是我本人做饭，不是别人，符合句意。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指众人，与“我”单独做饭的意思冲突。"}, {"text": "他人", "is_correct": false, "explanation": "搭配：“他人”指别的人，“我他人做饭”不成立。"}], "explanations": {"别人": "搭配：“别人”指他人，“我别人做饭”不成立，不能表示“我自己做”。", "自己": "正确：“自己”强调是我本人做饭，不是别人，符合句意。", "大家": "语义：“大家”指众人，与“我”单独做饭的意思冲突。", "他人": "搭配：“他人”指别的人，“我他人做饭”不成立。"}, "sentence_index": 0, "correct_answer": "自己"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的自己意识很强。", "explanation": "这里应该用〈自我〉。“自我意识”是固定说法，指对自身的认识；“自己意识”不能这样用。"}, {"text": "自己都来了，我们开始吧。", "explanation": "这里应该用〈大家〉。句中没有可指代的先行词，“自己”无法指代全体；表示全体要用“大家”。"}, {"text": "这个问题自己很简单。", "explanation": "这里应该用〈本身〉。“自己”多指人，指事物本身时用“本身”，应说“这个问题本身很简单”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85721, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "自己", "is_correct": true, "explanation": "正确答案：自己（zì jǐ），指本人，强调不是别人。"}, {"text": "自治", "is_correct": false, "explanation": "zì zhì 与 zì jǐ 第二个音节声母和声调不同（zh 与 j，第四声与第三声），自治指自己管理自己的事务。"}, {"text": "自始", "is_correct": false, "explanation": "zì shǐ 与 zì jǐ 第二个音节声母不同（sh 与 j），自始指从开始。"}, {"text": "自警", "is_correct": false, "explanation": "zì jǐng 与 zì jǐ 第二个音节韵母不同（-ing 与 -i，声调相同），自警指自我警醒。"}], "explanations": {"自己": "正确答案：自己（zì jǐ），指本人，强调不是别人。", "自治": "zì zhì 与 zì jǐ 第二个音节声母和声调不同（zh 与 j，第四声与第三声），自治指自己管理自己的事务。", "自始": "zì shǐ 与 zì jǐ 第二个音节声母不同（sh 与 j），自始指从开始。", "自警": "zì jǐng 与 zì jǐ 第二个音节韵母不同（-ing 与 -i，声调相同），自警指自我警醒。"}, "sentence_index": null, "correct_answer": "自己"}, "level_3": {"options": [{"text": "人家", "is_correct": false, "explanation": "搭配：“人家”指别人，“这是我人家画的画”不成立。"}, {"text": "自己", "is_correct": true, "explanation": "正确：“自己”强调画是我本人画的，符合句意。"}, {"text": "对方", "is_correct": false, "explanation": "语义：“对方”指另一方，与“我”指向冲突。"}, {"text": "各人", "is_correct": false, "explanation": "搭配：“各人”指每个人，不能与“我”并列修饰“画的画”。"}], "explanations": {"人家": "搭配：“人家”指别人，“这是我人家画的画”不成立。", "自己": "正确：“自己”强调画是我本人画的，符合句意。", "对方": "语义：“对方”指另一方，与“我”指向冲突。", "各人": "搭配：“各人”指每个人，不能与“我”并列修饰“画的画”。"}, "sentence_index": 6, "correct_answer": "自己"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师表扬了自己。", "explanation": "这里应该用〈我〉。“自己”指句中主语“老师”本人，这句是说老师表扬了他自己，应说“老师表扬了我”。"}, {"text": "我的父母很忙，他们很少陪自己。", "explanation": "这里应该用〈我〉。“自己”指句中主语本人，这句是说父母陪自己，应说“他们很少陪我”。"}, {"text": "我帮助了朋友们，他们都很感谢自己。", "explanation": "这里应该用〈我〉。“自己”指主语“他们”本人，这句是说朋友们感谢他们自己；感谢的其实是说话人，应说“他们都很感谢我”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我要自己的解决这个问题。", "corrected_sentence": "我要自己解决这个问题。", "error_description": "“自己”修饰动词“解决”时，后面不能加“的”。正确应为“我要自己解决这个问题”，去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我自己书。", "corrected_sentence": "这是我自己的书。", "error_description": "“自己”修饰名词“书”时漏掉“的”。正确：应为“自己的书”，“自己”与名词之间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
