INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指代前面提到的人本身；也指说话人本身。", "primary_collocate": null, "pronunciation": "zì jǐ", "ipa": "tsɨ˥˩ tɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "小明告诉我，他自己也不知道。", "target_word": "自己", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说她要自己照顾自己。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对自己很有信心。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是只想着自己。", "target_word": "自己", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家介绍自己。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，自己的事要自己做。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟生自己的气了。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把自己关在房间里。", "target_word": "自己", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事是我自己的错。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着看了看自己的手。", "target_word": "自己", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自己人", "label": "复合"}], "register": "通用", "sense_fingerprint": "反身代词，回指前面提到的人或说话人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d46218-0b69-4845-8d22-7c88f2e3105e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一个", "is_correct": false, "explanation": "语义：「一个」与「也」连用为“一个也不知道”，表示一个都不知道，与“他自己也不知道”句意不同。"}, {"text": "自己", "is_correct": true, "explanation": "反身代词，指代前句的“他”本人，意思是他也不知道。"}, {"text": "一点", "is_correct": false, "explanation": "语义：「一点」与「也」连用为“一点也不知道”，表示完全不知道，与“他自己也不知道”句意不同。"}, {"text": "半点", "is_correct": false, "explanation": "语义：「半点」与「也」连用为“半点也不知道”，表示完全不知道，与“他自己也不知道”句意不同。"}], "explanations": {"一个": "语义：「一个」与「也」连用为“一个也不知道”，表示一个都不知道，与“他自己也不知道”句意不同。", "自己": "反身代词，指代前句的“他”本人，意思是他也不知道。", "一点": "语义：「一点」与「也」连用为“一点也不知道”，表示完全不知道，与“他自己也不知道”句意不同。", "半点": "语义：「半点」与「也」连用为“半点也不知道”，表示完全不知道，与“他自己也不知道”句意不同。"}, "sentence_index": 0, "correct_answer": "自己"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是只想着本人。", "explanation": "这里应该用〈自己〉。「本人」多作定语或状语（本人签字、本人到场），不宜作“想着”的宾语，口语中应用“自己”。"}, {"text": "他总是只想着自我。", "explanation": "这里应该用〈自己〉。「自我」偏抽象或专业用语，“想着自我”语感生硬，指具体的人想着自己时应用“自己”。"}, {"text": "他总是只想着自身。", "explanation": "这里应该用〈自己〉。「自身」偏书面，多指事物本身的属性（自身条件），不用于口语中指人作“想着”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大家", "is_correct": false, "explanation": "语义：「大家」指全体，“弟弟生大家的气”与句意不符。"}, {"text": "自己", "is_correct": true, "explanation": "反身代词，指弟弟自己，「生自己的气」表示对自己不满。"}, {"text": "别人", "is_correct": false, "explanation": "语义：「别人」指他人，“弟弟生别人的气”与句意不符。"}, {"text": "他们", "is_correct": false, "explanation": "语义：「他们」指多人，“弟弟生他们的气”与句意不符。"}], "explanations": {"大家": "语义：「大家」指全体，“弟弟生大家的气”与句意不符。", "自己": "反身代词，指弟弟自己，「生自己的气」表示对自己不满。", "别人": "语义：「别人」指他人，“弟弟生别人的气”与句意不符。", "他们": "语义：「他们」指多人，“弟弟生他们的气”与句意不符。"}, "sentence_index": 6, "correct_answer": "自己"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他笑着看了看自我的手。", "explanation": "这里应该用〈自己〉。「自我」指抽象的自我意识，不能修饰具体的身体部位。"}, {"text": "他笑着看了看本人的手。", "explanation": "这里应该用〈自己〉。「本人」修饰身体部位时语感生硬，看自己的身体部位应用“自己的手”。"}, {"text": "他笑着看了看手本身。", "explanation": "这里应该用〈自己〉。「本身」指事物自身，“手本身”指手这个东西，不能表示“看自己的手”中的所属关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该多为自己的着想。", "corrected_sentence": "我们应该多为自己着想。", "error_description": "错误：「为……着想」中「着想」是动词，「自己」后面不能加「的」。正确：应为「为自己着想」，去掉「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把自己书放回了书架上。", "corrected_sentence": "他把自己的书放回了书架上。", "error_description": "错误：「自己」修饰名词「书」时漏掉「的」。正确：应为「自己的书」，「自己」与「的」连用后修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "正确：“给”是交出去，“收”是接受过来，二者为反义。"}, {"text": "唱", "is_correct": false, "explanation": "与“给”的任何义项都不构成反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "与“给”的任何义项都不构成反义关系。"}, {"text": "想", "is_correct": false, "explanation": "与“给”的任何义项都不构成反义关系。"}], "correct_answer": "收", "explanations": {"收": "正确：“给”是交出去，“收”是接受过来，二者为反义。", "唱": "与“给”的任何义项都不构成反义关系。", "跑": "与“给”的任何义项都不构成反义关系。", "想": "与“给”的任何义项都不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "正确：“给”是交出去，“收”是接受过来，二者为反义。"}, {"text": "跳", "is_correct": false, "explanation": "与“给”的任何义项都不构成反义关系。"}, {"text": "哭", "is_correct": false, "explanation": "与“给”的任何义项都不构成反义关系。"}, {"text": "看", "is_correct": false, "explanation": "与“给”的任何义项都不构成反义关系。"}], "correct_answer": "收", "explanations": {"收": "正确：“给”是交出去，“收”是接受过来，二者为反义。", "跳": "与“给”的任何义项都不构成反义关系。", "哭": "与“给”的任何义项都不构成反义关系。", "看": "与“给”的任何义项都不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“给”是把东西交到别人手里，让别人有。", "primary_collocate": null, "pronunciation": "gěi", "ipa": "kei˨˩˦", "syllable_count": 1, "sentences": [{"text": "他给我一本书。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请给我一杯水。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给了我一个苹果。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们很多作业。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钥匙在这儿，给你。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸每个月给我五百块钱。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你给我一张纸，我写个名字。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她给过我一件很漂亮的礼物。", "target_word": "给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给了他一瓶药，让他按时吃。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天朋友给了我两张电影票。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "给了", "label": "体标"}, {"form": "给过", "label": "体标"}, {"form": "給", "label": "繁体"}], "register": "口语", "sense_fingerprint": "动词给：把东西交到别人手里，让对方得到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '978170ba-3e1a-45cc-a780-edc5c61ec137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "给", "is_correct": true, "explanation": "正确答案：给（gěi），动词，把东西交到别人手里。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 gěi 声母不同（b 对 g），意思是北方。"}, {"text": "美", "is_correct": false, "explanation": "měi（第三声）与 gěi 声母不同（m 对 g），意思是美丽。"}, {"text": "得", "is_correct": false, "explanation": "děi（第三声）与 gěi 声母不同（d 对 g），意思是必须。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 gěi 韵母不同（ai 对 ei），意思是改变。"}, {"text": "鬼", "is_correct": false, "explanation": "guǐ（第三声）与 gěi 韵母不同（多出 u 介音，ui 对 ei），意思是鬼。"}], "explanations": {"给": "正确答案：给（gěi），动词，把东西交到别人手里。", "北": "běi（第三声）与 gěi 声母不同（b 对 g），意思是北方。", "美": "měi（第三声）与 gěi 声母不同（m 对 g），意思是美丽。", "得": "děi（第三声）与 gěi 声母不同（d 对 g），意思是必须。", "改": "gǎi（第三声）与 gěi 韵母不同（ai 对 ei），意思是改变。", "鬼": "guǐ（第三声）与 gěi 韵母不同（多出 u 介音，ui 对 ei），意思是鬼。"}, "sentence_index": null, "correct_answer": "给"}, "level_3": {"options": [{"text": "给", "is_correct": true, "explanation": "正确：动词“给”表示把东西交给“我”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能接“一本书”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“我”和“一本书”两个宾语。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣服，不能接“书”。"}], "explanations": {"给": "正确：动词“给”表示把东西交给“我”。", "吃": "搭配：“吃”的宾语是食物，不能接“一本书”。", "笑": "配价：“笑”是不及物动词，不能带“我”和“一本书”两个宾语。", "穿": "搭配：“穿”的宾语是衣服，不能接“书”。"}, "sentence_index": 0, "correct_answer": "给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师给我们英语。", "explanation": "这里应该用〈教〉。“教”指传授知识，“给”表示交付实物，不能把“英语”当作可以交付的东西。"}, {"text": "我给你吃饭了。", "explanation": "这里应该用〈请〉。“请你吃饭”表示邀请，“给”表示交付或为了某人，不能表示邀请。"}, {"text": "我给你回家了。", "explanation": "这里应该用〈送〉。“送你回家”表示陪同送行，“给”表示交付，不能表示送行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "给", "is_correct": true, "explanation": "正确：动词“给”表示把纸交给“我”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮品，不能接“一张纸”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带宾语。"}, {"text": "闻", "is_correct": false, "explanation": "搭配：“闻”的宾语是气味，不能接“纸”。"}], "explanations": {"给": "正确：动词“给”表示把纸交给“我”。", "喝": "搭配：“喝”的宾语是饮品，不能接“一张纸”。", "哭": "配价：“哭”是不及物动词，不能带宾语。", "闻": "搭配：“闻”的宾语是气味，不能接“纸”。"}, "sentence_index": 6, "correct_answer": "给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我起床了。", "explanation": "这里应该用〈叫〉。“叫某人做某事”表示使令，“给”表示交付，不能用于使令。"}, {"text": "他给老人过马路。", "explanation": "这里应该用〈扶〉。搀扶别人做某事用“扶”，“给”不能表示搀扶。"}, {"text": "老师给我们跑步了。", "explanation": "这里应该用〈训练〉。“训练”指按计划使人掌握技能，“给”表示交付，不能表示训练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐给我了一支笔。", "corrected_sentence": "姐姐给了我一支笔。", "error_description": "错误：动态助词“了”放在了宾语“我”之后，“给我了”不成立。正确：“了”紧跟动词，写作“给了我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给我过一张地图。", "corrected_sentence": "他给过我一张地图。", "error_description": "错误：体标“过”放在了宾语“我”之后，“给我过”不成立。正确：“过”紧跟动词，写作“给过我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
