INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示选择关系，相当于“或者”。", "primary_collocate": null, "pronunciation": "huò", "ipa": "xwo˥˩", "syllable_count": 1, "sentences": [{"text": "你可以坐地铁或坐公交车去。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我想去看电影或爬山。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请用笔或电脑写下你的名字。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早饭我常吃面包或鸡蛋。", "target_word": "或", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天或后天，我给你打电话。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有问题的话，请发邮件或打电话。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个星期里，他会去两次或三次健身房。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想喝茶或咖啡的人，请在这里排队。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以现在来，或明天早上来都行。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管是白天或晚上，这里都很安静。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "或者", "label": "复合"}, {"form": "或许", "label": "复合"}], "register": "通用", "sense_fingerprint": "或|连词|表示选择关系，相当于或者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d46218-0b69-4845-8d22-7c88f2e3105e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "或", "is_correct": true, "explanation": "目标词，读 huò（第四声），表示选择关系。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是“火”。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是“活着、活动”。"}, {"text": "户", "is_correct": false, "explanation": "hù 与 huò 的韵母和声调都不同，意思是“门户、户口”。"}], "explanations": {"或": "目标词，读 huò（第四声），表示选择关系。", "火": "huǒ（第三声）与 huò（第四声）声调不同，意思是“火”。", "活": "huó（第二声）与 huò（第四声）声调不同，意思是“活着、活动”。", "户": "hù 与 huò 的韵母和声调都不同，意思是“门户、户口”。"}, "sentence_index": null, "correct_answer": "或"}, "level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "搭配：「而是」需与前面的否定词「不是」搭配，这里没有否定。"}, {"text": "或", "is_correct": true, "explanation": "连词，表示选择，“坐地铁或坐公交车”是二选一。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，句中两种交通方式之间没有转折。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示因果，句中没有因果关系。"}], "explanations": {"而是": "搭配：「而是」需与前面的否定词「不是」搭配，这里没有否定。", "或": "连词，表示选择，“坐地铁或坐公交车”是二选一。", "但是": "语义：「但是」表示转折，句中两种交通方式之间没有转折。", "因此": "语义：「因此」表示因果，句中没有因果关系。"}, "sentence_index": 0, "correct_answer": "或"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早饭我常吃面包或鸡蛋，两样都吃。", "explanation": "「或」表示二选一，说两样都吃就与它的选择意义矛盾，应该用「和」。"}, {"text": "我今天买了笔或本子，两样都买了。", "explanation": "「或」表示二选一，两样都买了应该用「和」，不能用「或」。"}, {"text": "我昨天吃了米饭或面条，两样都吃了。", "explanation": "这里应该用〈和〉。「或」表示二选一，两样都吃了要用「和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示递进或并列，这里需要的是选择关系。"}, {"text": "或", "is_correct": true, "explanation": "连词，表示选择，“两次或三次”表示次数在两者之间二选一。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：「然而」要求前后转折，“两次”和“三次”之间没有转折。"}, {"text": "从而", "is_correct": false, "explanation": "语义：「从而」表示结果，句中“去健身房的次数”与结果无关。"}], "explanations": {"而且": "语义：「而且」表示递进或并列，这里需要的是选择关系。", "或": "连词，表示选择，“两次或三次”表示次数在两者之间二选一。", "然而": "搭配：「然而」要求前后转折，“两次”和“三次”之间没有转折。", "从而": "语义：「从而」表示结果，句中“去健身房的次数”与结果无关。"}, "sentence_index": 6, "correct_answer": "或"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我白天或晚上都去那里，每次两个时间都去。", "explanation": "「或」表示二选一，两个时间都去应该用「和」。"}, {"text": "我问了老师或同学，两个人都回答了。", "explanation": "这里应该用〈和〉。“或”表示二选一，而句中两个人都回答了，应用「和」。"}, {"text": "我周末或周一都去过，两天都去过。", "explanation": "这里应该用〈和〉。「或」表示二选一，说两天都去过要用「和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末你可以去公园或和爬山。", "corrected_sentence": "周末你可以去公园或爬山。", "error_description": "错误：「或」已表示二选一，后面不能再加「和」。正确：应为「去公园或爬山」，去掉「和」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周一或周二或，你都可以来。", "corrected_sentence": "周一或周二，你都可以来。", "error_description": "错误：句末多了一个「或」。「或」是连词，需连接两个成分，不能悬空。正确：应为「周一或周二，你都可以来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“因为”是用来说事情为什么会这样的。", "primary_collocate": null, "pronunciation": "yīn wèi", "ipa": "in˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "我没去，因为我生病了。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么哭？因为我的手机丢了。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑了，因为大家都夸他。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太贵，我没有买。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这座城市，因为这里的人很热情。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天没来上课，因为家里有事。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雪，飞机晚点了。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很高兴，因为考试得了第一名。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不去了，因为时间太晚。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，因为他想妈妈了。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "因为：回答“为什么”，单独引出原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d3283c2-c3c9-456b-a54d-b3cbf61747b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结果，而“我生病了”是原因，这样说因果颠倒。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出结果，放在“我生病了”前，与原句的因果方向相反。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“如果”要与“就”呼应，且句子说的是已经发生的事，不能用假设。"}, {"text": "因为", "is_correct": true, "explanation": "“因为”引出原因，与“我没去”构成因果，解释没去的理由。"}], "explanations": {"所以": "语义：“所以”引出结果，而“我生病了”是原因，这样说因果颠倒。", "因此": "语义：“因此”引出结果，放在“我生病了”前，与原句的因果方向相反。", "如果": "搭配：“如果”要与“就”呼应，且句子说的是已经发生的事，不能用假设。", "因为": "“因为”引出原因，与“我没去”构成因果，解释没去的理由。"}, "sentence_index": 0, "correct_answer": "因为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "因为天冷，但是他没穿外套。", "explanation": "这里应该用〈虽然〉。“但是”表示转折，要与让步的“虽然”呼应；“因为”引出原因，两者不能这样配合。"}, {"text": "他没有努力，因为没有通过考试。", "explanation": "这里应该用〈因此〉。“没有努力”是原因，“没有通过考试”是结果，结果应说“因此没有通过考试”。"}, {"text": "因为下雨，我们还是去了公园。", "explanation": "这里应该用〈虽然〉。“还是”要与让步的“虽然”呼应，用“因为”会使前后句意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "搭配：“而是”要与前面的否定呼应，句中没有否定词，不能这样用。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”表示结果，不能用来引出“下雪”这一原因。"}, {"text": "以致", "is_correct": false, "explanation": "语义：“以致”表示结果，与“下雪”和“飞机晚点”的因果方向相反。"}, {"text": "因为", "is_correct": true, "explanation": "“因为”引出“下雪”这一原因，说明飞机晚点的理由。"}], "explanations": {"而是": "搭配：“而是”要与前面的否定呼应，句中没有否定词，不能这样用。", "因而": "语义：“因而”表示结果，不能用来引出“下雪”这一原因。", "以致": "语义：“以致”表示结果，与“下雪”和“飞机晚点”的因果方向相反。", "因为": "“因为”引出“下雪”这一原因，说明飞机晚点的理由。"}, "sentence_index": 6, "correct_answer": "因为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "因为努力，才能成功。", "explanation": "这里应该用〈只有〉。“只有……才……”表示唯一条件；“因为”只能引出已经发生的原因，不能接条件。"}, {"text": "他很高，因为很瘦。", "explanation": "这里应该用〈而且〉。“而且”把两个特点并列起来；“因为”要求后半句是前半句的原因，“很瘦”解释不了“很高”。"}, {"text": "她很聪明，因为成绩不好。", "explanation": "这里应该用〈然而〉。“然而”表示转折，前后意思相反；“因为”表示原因，这里不能说成因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你怎么不吃饭？因为我因为不饿。", "corrected_sentence": "你怎么不吃饭？因为我不饿。", "error_description": "连词重复：“因为”只用一次，“我因为不饿”里又加了一个“因为”，应只说“因为我不饿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
